export type Cents = number;

/**
 * Unique identifier for entities (UUID or deterministic hash).
 */
export type EntityId = string;

/**
 * ISO 8601 Date string (YYYY-MM-DD).
 * @example "2026-01-17"
 */
export type ISODateString = string;

/**
 * Isomorphic timer handle that resolves to the correct type in both Node and Browser.
 */
export type TimerHandle = ReturnType<typeof setInterval>;

/**
 * Transaction status in the ledger lifecycle.
 */
export enum TransactionStatus {
    /** Imported but not yet matched or verified by the user. */
    Pending = 'pending',
    /** Matched with bank statement but not yet frozen. */
    Cleared = 'cleared',
    /** User-verified and locked; immutable for ledger integrity. */
    Reconciled = 'reconciled'
}

/**
 * Core supported account types.
 */
export enum AccountType {
    Checking = 'checking',
    Savings = 'savings',
    Credit = 'credit',
    Cash = 'cash',
    Mortgage = 'mortgage',
    AutoLoan = 'auto_loan',
    PersonalLoan = 'personal_loan'
}

/**
 * Types of recurring schedules.
 */
export enum ScheduleType {
    Debit = 'debit',
    Deposit = 'deposit',
    Paycheck = 'paycheck'
}

export interface IMortgageMetadata {
    propertyAddress?: string;
    propertyValue?: Cents;
    escrowIncluded: boolean;
    escrowAmount?: Cents;
}

export interface IAutoLoanMetadata {
    vehicleMake?: string;
    vehicleModel?: string;
    vehicleYear?: number;
    vin?: string;
}

export interface IPersonalLoanMetadata {
    purpose?: string;
    secured: boolean;
}

export interface ILoanDetails {
    /** Original principal amount in cents */
    originalAmount: Cents;
    /** Annual Percentage Rate as decimal (e.g., 0.0375 = 3.75%) */
    interestRate: number;
    /** Total loan term in months */
    termMonths: number;
    /** Monthly payment amount in cents */
    monthlyPayment: Cents;
    /** Day of month payment is due (1-31) */
    paymentDueDay: number;
    /** Loan origination date */
    startDate: ISODateString;
    /** Type-specific metadata */
    metadata?: IMortgageMetadata | IAutoLoanMetadata | IPersonalLoanMetadata;
}

/**
 * A sub-allocation of a transaction to a category.
 */
export interface ISplit {
    /** Unique ID for the split. */
    id: EntityId;
    /** Category to which this amount is allocated. Null if uncategorized. */
    categoryId: EntityId | null;
    /** Descriptive text for this split. */
    memo: string;
    /** Amount in cents. Can be negative for deductions (taxes, fees). */
    amount: Cents;
}

/**
 * A financial transaction in the ledger.
 * Transactions consist of a total amount and one or more splits.
 */
export interface ITransaction {
    /** Unique ID for the transaction. */
    id: EntityId;
    /** ID of the account this transaction belongs to. */
    accountId: EntityId;
    /** Mandatory ID of the payee entity. */
    payeeId: EntityId;
    /** Date the transaction occurred. */
    date: ISODateString;
    /** Name of the payee or entity involved (cached for performance). */
    payee: string;
    /** Optional descriptive text for the transaction. */
    memo: string;
    /** Total amount in cents. Rule: Sum(splits) === totalAmount. */
    totalAmount: Cents;
    /** Current status in the reconciliation lifecycle. */
    status: TransactionStatus;
    /** List of splits. Must contain at least one split. */
    splits: Array<ISplit>;
    /** Optional check number for bank transactions. */
    checkNumber: string | null;
    /** SHA-256 hash for duplicate detection during imports. */
    importHash: string;
    /** ISO timestamp when the record was created. */
    createdAt: ISODateString;
    /** ISO timestamp when the record was last modified. */
    updatedAt: ISODateString;
    /** Optional ID of a linked transfer record if this transaction is part of a cross-account transfer. */
    linkedTransferId?: EntityId;
}

/**
 * A cross-account transfer connecting two transactions.
 */
export interface ITransfer {
    /** Unique ID for the transfer record. */
    id: EntityId;
    /** Date the transfer occurred. */
    date: ISODateString;
    /** Amount of the transfer (positive absolute value). */
    amount: Cents;
    /** ID of the source account. */
    fromAccountId: EntityId;
    /** ID of the destination account. */
    toAccountId: EntityId;
    /** ID of the transaction recorded in the source account. */
    fromTransactionId: EntityId;
    /** ID of the transaction recorded in the destination account. */
    toTransactionId: EntityId;
    /** Snapshot of the source account name in case it is deleted. */
    fromAccountNameSnapshot: string;
    /** Snapshot of the destination account name in case it is deleted. */
    toAccountNameSnapshot: string;
    /** Optional memo for the transfer. */
    memo: string;
    /** ISO timestamp when the record was created. */
    createdAt: ISODateString;
    /** ISO timestamp when the record was last modified. */
    updatedAt: ISODateString;
    /** ISO timestamp when the record was soft-deleted (null if active). */
    deletedAt: ISODateString | null;
}

/**
 * An entity that receives or pays money.
 */
export interface IPayee {
    /** Unique ID for the payee. */
    id: EntityId;
    /** Human-readable name (e.g., "Starbucks"). */
    name: string;
    /** Geographical Address. */
    address: string | null;
    /** City location. */
    city: string | null;
    /** State/Province. */
    state: string | null;
    /** Postal/Zip code. */
    zipCode: string | null;
    /** Coordinate for map visualization. */
    latitude: number | null;
    /** Coordinate for map visualization. */
    longitude: number | null;
    /** Official website or portal. */
    website: string | null;
    /** Contact phone number. */
    phone: string | null;
    /** Arbitrary notes about this payee. */
    notes: string | null;
    /** Default category ID suggested for new transactions. */
    defaultCategoryId: EntityId | null;
    /** ISO timestamp when the record was created. */
    createdAt: ISODateString;
    /** ISO timestamp when the record was last modified. */
    updatedAt: ISODateString;
}

/**
 * A category for organizing transactions (e.g., "Groceries", "Rent").
 * Supports a hierarchical tree structure.
 */
export interface ICategory {
    /** Unique ID for the category. */
    id: EntityId;
    /** ID of the parent category (null if top-level). */
    parentId: EntityId | null;
    /** Name of the category (e.g., "Dining Out"). */
    name: string;
    /** Optional detailed description. */
    description: string | null;
    /** Whether the category is currently available for selection. */
    isActive: boolean;
    /** ISO timestamp when the record was created. */
    createdAt: ISODateString;
    /** ISO timestamp when the record was last modified. */
    updatedAt: ISODateString;
}

/**
 * An account containing a collection of transactions.
 */
export interface IAccount {
    /** Unique ID for the account. */
    id: EntityId;
    /** Human-readable name (e.g., "Main Checking"). */
    name: string;
    /** Type of account (e.g., checking, savings). */
    type: AccountType;
    /** Financial institution name. */
    institutionName: string;
    /** Sum of all Cleared/Reconciled transactions. */
    clearedBalance: Cents;
    /** Sum of all transactions (Cleared + Pending). */
    pendingBalance: Cents;
    /** Whether the account is currently in use. */
    isActive: boolean;
    /** ISO timestamp when the record was created. */
    createdAt: ISODateString;
    /** ISO timestamp when the record was last modified. */
    updatedAt: ISODateString;
    /** ISO timestamp when the record was soft-deleted (null if active). */
    deletedAt: ISODateString | null;
    /** Optional detailed information for loan accounts. */
    loanDetails?: ILoanDetails;
}

/**
 * Frequency interval for recurring scheduled items.
 */
export enum Frequency {
    Daily = 'daily',
    Weekly = 'weekly',
    Biweekly = 'biweekly',
    EveryFourWeeks = 'every_four_weeks',
    Monthly = 'monthly',
    TwiceAMonth = 'twice_a_month',
    Bimonthly = 'bimonthly',
    Quarterly = 'quarterly',
    Yearly = 'yearly'
}

/**
 * Payment methods for scheduled transactions.
 */
export enum PaymentMethod {
    DirectDebit = 'direct_debit',
    DirectDeposit = 'direct_deposit',
    WriteCheck = 'write_check',
    ElectronicTransfer = 'electronic_transfer',
    Other = 'other'
}

/**
 * A template for generating recurring transactions.
 */
export interface IRecurringSchedule {
    /** Unique ID for the schedule. */
    id: EntityId;
    /** The account where generated transactions will be posted. */
    accountId: EntityId;
    /** Default payee for generated transactions. */
    payee: string;
    /** Total amount for the transaction (parent). */
    amount: Cents;
    /** The type of schedule (Debit, Deposit, Paycheck). */
    type: ScheduleType;
    /** How often the transaction repeats. */
    frequency: Frequency;
    /** How the payment is processed. */
    paymentMethod: PaymentMethod;
    /** Date when the schedule begins. */
    startDate: ISODateString;
    /** Optional date when the schedule ends. */
    endDate: ISODateString | null;
    /** Calculated date of the next occurrence. */
    nextDueDate: ISODateString;
    /** Date when the last transaction was posted from this schedule. */
    lastOccurredDate: ISODateString | null;
    /** Splits for the generated transaction. */
    splits: Array<ISplit>;
    /** Optional memo for the transaction. */
    memo: string;
    /** Whether to automatically post the transaction to the ledger on the due date. */
    autoPost: boolean;
    /** Whether the schedule is active and generating projections. */
    isActive: boolean;
}

/**
 * Result of parsing a single split from an external source (e.g. QIF).
 */
export interface IParsedSplit {
    category: string | null;
    amount: Cents;
    memo: string | null;
}

/**
 * Result of parsing a single transaction from an external source (e.g. QIF).
 */
export interface IParsedTransaction {
    date: ISODateString;
    amount: Cents;
    payee: string;
    memo: string;
    checkNumber: string | null;
    category: string | null;
    splits: Array<IParsedSplit>;
    importHash: string;
}

import { CommonModule } from '@angular/common';
import {
    ChangeDetectionStrategy,
    Component,
    computed,
    effect,
    inject,
    input,
    output,
    signal,
    viewChild
} from '@angular/core';
import { FormsModule } from '@angular/forms';
import { Router } from '@angular/router';

import type { IAccount, ISODateString } from '@core';
import { AccountType, TypeGuards } from '@core';
import { Button } from 'primeng/button';
import { Dialog } from 'primeng/dialog';
import { Step, StepList, StepPanel, StepPanels, Stepper } from 'primeng/stepper';
import { CategoryMappingDialogComponent } from '../../ledger/category-mapping-dialog/category-mapping-dialog.component';

import { ImportOrchestrationService } from '../../../services/import/import-orchestration.service';
import { PostHogService } from '../../../services/posthog/posthog.service';
import { LoanDetailsFormComponent } from '../loan-details-form/loan-details-form.component';

/**
 * Wizard step types.
 */
type WizardStep = 'select-type' | 'enter-details' | 'import-data' | 'creating';

/**
 * Account type option for the wizard.
 */
interface IAccountTypeOption {
    type: AccountType;
    icon: string;
    label: string;
    description: string;
}

const PRIMARY_TYPES: Array<IAccountTypeOption> = [
    {
        type: AccountType.Checking,
        icon: 'pi-building-columns',
        label: 'Checking',
        description: 'Daily spending & income'
    },
    {
        type: AccountType.Savings,
        icon: 'pi-money-bill',
        label: 'Savings',
        description: 'Long-term goals'
    },
    {
        type: AccountType.Credit,
        icon: 'pi-credit-card',
        label: 'Credit Card',
        description: 'Track spending & debt'
    },
    {
        type: AccountType.Cash,
        icon: 'pi-wallet',
        label: 'Cash',
        description: 'Physical currency'
    }
];

const LOAN_TYPES: Array<IAccountTypeOption> = [
    {
        type: AccountType.Mortgage,
        icon: 'pi-home',
        label: 'Mortgage',
        description: 'Home loan & equity'
    },
    {
        type: AccountType.AutoLoan,
        icon: 'pi-car',
        label: 'Auto Loan',
        description: 'Vehicle financing'
    },
    {
        type: AccountType.PersonalLoan,
        icon: 'pi-receipt',
        label: 'Personal Loan',
        description: 'Unsecured debt'
    }
];

/**
 * Styling and theming for account types.
 */
const TYPE_THEMING: Record<
    string,
    { accentBg: string; borderHover: string; iconText: string; iconBg: string; iconBorder: string }
> = {
    [AccountType.Checking]: {
        accentBg: 'bg-teal-500',
        borderHover: 'border-teal-500/30 hover:border-teal-500',
        iconText: 'text-teal-600 dark:text-teal-400',
        iconBg: 'bg-teal-500/10',
        iconBorder: 'border-teal-500/20'
    },
    [AccountType.Savings]: {
        accentBg: 'bg-blue-500',
        borderHover: 'border-blue-500/30 hover:border-blue-500',
        iconText: 'text-blue-600 dark:text-blue-400',
        iconBg: 'bg-blue-500/10',
        iconBorder: 'border-blue-500/20'
    },
    [AccountType.Credit]: {
        accentBg: 'bg-purple-500',
        borderHover: 'border-purple-500/30 hover:border-purple-500',
        iconText: 'text-purple-600 dark:text-purple-400',
        iconBg: 'bg-purple-500/10',
        iconBorder: 'border-purple-500/20'
    },
    [AccountType.Cash]: {
        accentBg: 'bg-green-500',
        borderHover: 'border-green-500/30 hover:border-green-500',
        iconText: 'text-green-600 dark:text-green-400',
        iconBg: 'bg-green-500/10',
        iconBorder: 'border-green-500/20'
    },
    [AccountType.Mortgage]: {
        accentBg: 'bg-amber-500',
        borderHover: 'border-amber-500/30 hover:border-amber-500',
        iconText: 'text-amber-600 dark:text-amber-400',
        iconBg: 'bg-amber-500/10',
        iconBorder: 'border-amber-500/20'
    },
    [AccountType.AutoLoan]: {
        accentBg: 'bg-amber-500',
        borderHover: 'border-amber-500/30 hover:border-amber-500',
        iconText: 'text-amber-600 dark:text-amber-400',
        iconBg: 'bg-amber-500/10',
        iconBorder: 'border-amber-500/20'
    },
    [AccountType.PersonalLoan]: {
        accentBg: 'bg-amber-500',
        borderHover: 'border-amber-500/30 hover:border-amber-500',
        iconText: 'text-amber-600 dark:text-amber-400',
        iconBg: 'bg-amber-500/10',
        iconBorder: 'border-amber-500/20'
    }
};

/**
 * Dialog for creating a new account.
 * Guides the user through type selection, configuration, and optional initial data import.
 */
@Component({
    selector: 'new-account-dialog',
    standalone: true,
    imports: [
        CommonModule,
        FormsModule,
        LoanDetailsFormComponent,
        Stepper,
        StepList,
        StepPanels,
        Step,
        StepPanel,
        Button,
        Dialog,
        CategoryMappingDialogComponent
    ],
    templateUrl: './new-account-dialog.component.html',
    styleUrls: ['./new-account-dialog.component.css'],
    changeDetection: ChangeDetectionStrategy.OnPush
})
export class NewAccountDialogComponent {
    private readonly posthogService = inject(PostHogService);
    readonly importService = inject(ImportOrchestrationService);
    private readonly router = inject(Router);

    /** Reference to the embedded loan-details-form for triggering submit from the dialog footer. */
    readonly loanFormRef = viewChild(LoanDetailsFormComponent);

    // Inputs
    readonly isOpen = input.required<boolean>();

    // Outputs
    readonly closed = output();
    readonly accountCreated = output<IAccount>();

    // State
    readonly step = signal<WizardStep>('select-type');
    readonly selectedType = signal<AccountType | null>(null);
    readonly showLoans = signal<boolean>(false);
    readonly accountName = signal<string>('');
    readonly institutionName = signal<string>('');
    readonly initialBalance = signal<string>('');
    readonly error = signal<string | null>(null);

    /** The newly-created account — populated after handleCreate() succeeds */
    readonly createdAccount = signal<IAccount | null>(null);

    /** Tracks drag-over state for the drop zone */
    readonly isDropZoneActive = signal<boolean>(false);
    readonly isNavigating = signal<boolean>(false);
    readonly loanShouldImport = signal<boolean>(false);

    // Computed
    readonly stepValue = computed(() => {
        switch (this.step()) {
            case 'select-type':
                return 1;
            case 'enter-details':
                return 2;
            case 'creating':
                return 2;
            case 'import-data':
                return 3;
            default:
                return 1;
        }
    });

    readonly primaryTypes = signal(PRIMARY_TYPES);
    readonly loanTypes = signal(LOAN_TYPES);

    readonly selectedOption = computed(() => {
        const type = this.selectedType();
        if (!type) return null;
        return [...PRIMARY_TYPES, ...LOAN_TYPES].find(opt => opt.type === type) || null;
    });

    readonly theming = computed(() => {
        const type = this.selectedType();
        if (!type || !TYPE_THEMING[type]) {
            return {
                accentBg: 'bg-primary',
                borderHover: 'border-primary/30',
                iconText: 'text-primary',
                iconBg: 'bg-primary/10',
                iconBorder: 'border-primary/20'
            };
        }
        return TYPE_THEMING[type];
    });

    readonly isLoan = computed(() => {
        const type = this.selectedType();
        return type ? TypeGuards.isLoanAccount(type) : false;
    });

    readonly importProgress = this.importService.progress;
    readonly importStats = this.importService.stats;
    readonly importDone = computed(() => this.importService.progress().stage === 'done');

    /** Whether the standard (non-loan) form has enough data to create an account. */
    readonly isFormValid = computed(() => {
        return this.accountName().trim().length > 0;
    });

    /** Whether the loan form is valid — bridges to the child loanForm's FormGroup validity. */
    readonly isLoanFormValid = computed(() => {
        const ref = this.loanFormRef();
        return ref ? ref.isValid() : false;
    });

    constructor() {
        // Reset state when closing
        effect(() => {
            if (!this.isOpen()) {
                this.step.set('select-type');
                this.selectedType.set(null);
                this.accountName.set('');
                this.institutionName.set('');
                this.initialBalance.set('');
                this.error.set(null);
                this.createdAccount.set(null);
            } else {
                this.importService.reset();
            }
        });
    }

    handleTypeSelect(type: AccountType): void {
        this.selectedType.set(type);
        this.step.set('enter-details');
        this.error.set(null);

        const defaultNames: Record<string, string> = {
            [AccountType.Checking]: 'Main Checking',
            [AccountType.Savings]: 'Savings',
            [AccountType.Credit]: 'Credit Card',
            [AccountType.Cash]: 'Cash'
        };
        const defaultName = defaultNames[type];
        if (defaultName) {
            this.accountName.set(defaultName);
        }
    }

    async handleCreate(goToImport = false): Promise<void> {
        if (!this.accountName().trim()) {
            this.error.set('Account name is required');
            return;
        }

        this.error.set(null);
        this.step.set('creating');

        try {
            const type = this.selectedType();
            if (!type) {
                this.error.set('Account type is required');
                this.step.set('select-type');
                return;
            }
            const now = new Date().toISOString() as ISODateString;
            let val = parseFloat(this.initialBalance() || '0');

            if (this.selectedType() === AccountType.Credit) {
                val = -Math.abs(val);
            } else {
                val = Math.abs(val);
            }

            const balanceCents = Math.round(val * 100);

            const newAccount: IAccount = {
                id: `acc-${Date.now()}`,
                name: this.accountName().trim(),
                type: type,
                institutionName: this.institutionName().trim(),
                clearedBalance: balanceCents,
                pendingBalance: balanceCents,
                isActive: true,
                deletedAt: null,
                createdAt: now,
                updatedAt: now
            };

            this.createdAccount.set(newAccount);
            this.accountCreated.emit(newAccount);
            this.posthogService.posthog.capture('account_created', {
                account_type: type,
                has_institution_name: !!this.institutionName().trim(),
                has_initial_balance: !!this.initialBalance(),
                will_import: goToImport
            });

            if (goToImport) {
                this.importService.reset();
                this.step.set('import-data');
            } else {
                this.closed.emit();
            }
        } catch {
            this.error.set('Failed to create account');
            this.step.set('enter-details');
        }
    }

    // ── Import step helpers ───────────────────────────────────────────────────

    onDropZoneDragOver(event: DragEvent): void {
        event.preventDefault();
        this.isDropZoneActive.set(true);
    }

    onDropZoneDragLeave(): void {
        this.isDropZoneActive.set(false);
    }

    onDropZoneDrop(event: DragEvent): void {
        event.preventDefault();
        this.isDropZoneActive.set(false);
        const file = event.dataTransfer?.files[0];
        if (file) this.startImportFromFile(file);
    }

    onImportFileSelected(event: Event): void {
        const input = event.target as HTMLInputElement;
        const file = input.files?.[0];
        if (file) this.startImportFromFile(file);
        input.value = '';
    }

    private startImportFromFile(file: File): void {
        const accountId = this.createdAccount()?.id ?? '';
        this.importService.startImport(file, accountId);
    }

    skipImport(): void {
        this.importService.reset();
        this.closed.emit();
    }

    async finishAfterImport(): Promise<void> {
        this.isNavigating.set(true);
        const accountId = this.createdAccount()?.id;

        if (accountId) {
            try {
                await this.importService.commitImport(accountId);
            } catch (err) {
                console.error('Failed to commit imported transactions:', err);
            }
        }

        setTimeout(() => {
            if (accountId) {
                void this.router.navigate(['/accounts', accountId]).then(() => {
                    this.closed.emit();
                    this.isNavigating.set(false);
                });
            } else {
                this.closed.emit();
                this.isNavigating.set(false);
            }
        }, 50);
    }

    handleCancel(): void {
        this.closed.emit();
    }

    getTypeTheming(type: AccountType): {
        accentBg: string;
        borderHover: string;
        iconText: string;
        iconBg: string;
        iconBorder: string;
    } {
        return (
            TYPE_THEMING[type] || {
                accentBg: 'bg-primary',
                borderHover: 'border-primary/30',
                iconText: 'text-primary',
                iconBg: 'bg-primary/10',
                iconBorder: 'border-primary/20'
            }
        );
    }

    onStepValueChange(value: number | undefined): void {
        if (value === undefined) return;
        if (value === 1) {
            this.step.set('select-type');
        } else if (value === 2) {
            this.step.set('enter-details');
        } else if (value === 3) {
            this.step.set('import-data');
        }
    }

    submitLoanForm(shouldImport: boolean): void {
        this.loanShouldImport.set(shouldImport);
        void this.loanFormRef()?.handleSubmit();
    }

    handleLoanSubmitted(newAccount: IAccount): void {
        this.createdAccount.set(newAccount);
        this.accountCreated.emit(newAccount);
        this.posthogService.posthog.capture('account_created', {
            account_type: newAccount.type,
            has_institution_name: !!newAccount.institutionName?.trim(),
            has_initial_balance: true,
            will_import: this.loanShouldImport()
        });

        if (this.loanShouldImport()) {
            this.importService.reset();
            this.step.set('import-data');
        } else {
            this.closed.emit();
        }
    }

    // Lucide Icons
}

