export class QifTestComponent {
    private readonly ledgerStore = inject(LedgerStore);

    readonly filename = signal<string | null>(null);
    readonly isProcessing = signal<boolean>(false);
    readonly anomalies = signal<Array<IAnomaly>>([]);
    readonly reportMarkdown = signal<string | null>(null);

    async onFileSelected(event: Event): Promise<void> {
        const input = event.target as HTMLInputElement;
        if (!input?.files || input.files.length === 0) return;

        const file = input.files.item(0);
        if (!file) return;

        this.filename.set(file.name);
        this.isProcessing.set(true);
        this.reportMarkdown.set(null);
        this.anomalies.set([]);

        try {
            const content = await file.text();
            this.analyzeQif(content);
        } catch (e) {
            console.error('Failed to read file', e);
        } finally {
            this.isProcessing.set(false);
            // Reset input so the same file can be selected again
            input.value = '';
        }
    }

    private getCategorySearchPaths(qifCategory: string): Array<string> {
        const isTransfer = qifCategory.startsWith('[') && qifCategory.endsWith(']');
        if (isTransfer) {
            return ['[TRANSFER]'];
        }

        const cleanName = qifCategory.replace(/[[\]]/g, '').trim();
        const paths = [cleanName];

        if (cleanName.includes(':')) {
            const parts = cleanName.split(':');
            const lastPart = parts[parts.length - 1];
            if (lastPart) {
                paths.push(lastPart.trim());
            }
        }

        return paths;
    }

    private analyzeQif(content: string): void {
        const parser = new QIFParser();
        const result = parser.parse(content);
        const categories = this.ledgerStore.categories();

        const anomalies: Array<IAnomaly> = [];

        for (const tx of result.transactions) {
            let hasIssue = false;
            const reasons: Array<string> = [];

            const checkCat = (catRaw: string | null, context: string): void => {
                if (!catRaw) return;
                const paths = this.getCategorySearchPaths(catRaw);

                for (const path of paths) {
                    if (path === '[TRANSFER]') return;

                    // 1. Exact match
                    const exactMatch = categories.find(
                        c => c.name.toLowerCase() === path.toLowerCase()
                    );
                    if (exactMatch) return;

                    // 2. Alias match
                    const aliasMatch = this.ledgerStore.getCategoryAlias(path);
                    if (aliasMatch) return;
                }

                hasIssue = true;
                reasons.push(
                    `Unknown ${context} Category: "${catRaw}" (Tried: ${paths.join(', ')})`
                );
            };

            checkCat(tx.category, 'Main');
            const splits = tx.splits || [];
            let splitIdx = 1;
            for (const split of splits) {
                checkCat(split.category, `Split ${splitIdx}`);
                splitIdx++;
            }

            // Check math for splits
            if (tx.splits && tx.splits.length > 0) {
                const sumSplits = tx.splits.reduce(
                    (acc: number, s: IParsedSplit) => acc + s.amount,
                    0
                );
                if (sumSplits !== tx.amount) {
                    hasIssue = true;
                    reasons.push(
                        `Math Mismatch: Total Amount (${tx.amount}) !== Sum of Splits (${sumSplits})`
                    );
                }
            }

            if (hasIssue) {
                anomalies.push({
                    reason: reasons.join(' | '),
                    transaction: tx
                });
            }
        }

        this.anomalies.set(anomalies);
        this.generateMarkdown(result.transactions.length, anomalies, result.errors);
    }

    private generateMarkdown(
        totalTxs: number,
        anomalies: Array<IAnomaly>,
        errors: Array<unknown>
    ): void {
        let md = `# QIF Import Diagnostic Report\n\n`;
        md += `- **Total Transactions Parsed:** ${totalTxs}\n`;
        md += `- **Anomalies Detected:** ${anomalies.length}\n`;
        md += `- **Parser Errors:** ${errors.length}\n\n`;

        if (errors.length > 0) {
            md += `## Parser Errors\n\n` + JSON.stringify(errors, null, 2) + '\n\n';
        }

        if (anomalies.length === 0) {
            md += `*No unknown categories or math mismatches found!*\n`;
        } else {
            md += `## Anomalous Transactions\n\n`;
            anomalies.forEach((a, index) => {
                md += `### ${index + 1}. ${a.reason}\n`;
                md += `\`\`\`json\n`;
                md += JSON.stringify(a.transaction, null, 2) + '\n';
                md += `\`\`\`\n\n`;
            });
        }

        this.reportMarkdown.set(md);
    }

    async copyReport(): Promise<void> {
        const md = this.reportMarkdown();
        if (md) {
            try {
                await navigator.clipboard.writeText(md);
            } catch (err) {
                console.error('Failed to copy', err);
            }
        }
    }
}

export type Cents = number;

/**
 * Unique identifier for entities (UUID or deterministic hash).
 */
export type EntityId = string;

/**
 * ISO 8601 Date string (YYYY-MM-DD).
 * @example "2026-01-17"
 */
export type ISODateString = string;

/**
 * Isomorphic timer handle that resolves to the correct type in both Node and Browser.
 */
export type TimerHandle = ReturnType<typeof setInterval>;

/**
 * Transaction status in the ledger lifecycle.
 */
export enum TransactionStatus {
    /** Imported but not yet matched or verified by the user. */
    Pending = 'pending',
    /** Matched with bank statement but not yet frozen. */
    Cleared = 'cleared',
    /** User-verified and locked; immutable for ledger integrity. */
    Reconciled = 'reconciled'
}

/**
 * Core supported account types.
 */
export enum AccountType {
    Checking = 'checking',
    Savings = 'savings',
    Credit = 'credit',
    Cash = 'cash',
    Mortgage = 'mortgage',
    AutoLoan = 'auto_loan',
    PersonalLoan = 'personal_loan'
}

/**
 * Types of recurring schedules.
 */
export enum ScheduleType {
    Debit = 'debit',
    Deposit = 'deposit',
    Paycheck = 'paycheck'
}

export interface IMortgageMetadata {
    propertyAddress?: string;
    propertyValue?: Cents;
    escrowIncluded: boolean;
    escrowAmount?: Cents;
}

export interface IAutoLoanMetadata {
    vehicleMake?: string;
    vehicleModel?: string;
    vehicleYear?: number;
    vin?: string;
}

export interface IPersonalLoanMetadata {
    purpose?: string;
    secured: boolean;
}

export interface ILoanDetails {
    /** Original principal amount in cents */
    originalAmount: Cents;
    /** Annual Percentage Rate as decimal (e.g., 0.0375 = 3.75%) */
    interestRate: number;
    /** Total loan term in months */
    termMonths: number;
    /** Monthly payment amount in cents */
    monthlyPayment: Cents;
    /** Day of month payment is due (1-31) */
    paymentDueDay: number;
    /** Loan origination date */
    startDate: ISODateString;
    /** Type-specific metadata */
    metadata?: IMortgageMetadata | IAutoLoanMetadata | IPersonalLoanMetadata;
}

/**
 * A sub-allocation of a transaction to a category.
 */
export interface ISplit {
    /** Unique ID for the split. */
    id: EntityId;
    /** Category to which this amount is allocated. Null if uncategorized. */
    categoryId: EntityId | null;
    /** Descriptive text for this split. */
    memo: string;
    /** Amount in cents. Can be negative for deductions (taxes, fees). */
    amount: Cents;
}

/**
 * A financial transaction in the ledger.
 * Transactions consist of a total amount and one or more splits.
 */
export interface ITransaction {
    /** Unique ID for the transaction. */
    id: EntityId;
    /** ID of the account this transaction belongs to. */
    accountId: EntityId;
    /** Mandatory ID of the payee entity. */
    payeeId: EntityId;
    /** Date the transaction occurred. */
    date: ISODateString;
    /** Name of the payee or entity involved (cached for performance). */
    payee: string;
    /** Optional descriptive text for the transaction. */
    memo: string;
    /** Total amount in cents. Rule: Sum(splits) === totalAmount. */
    totalAmount: Cents;
    /** Current status in the reconciliation lifecycle. */
    status: TransactionStatus;
    /** List of splits. Must contain at least one split. */
    splits: Array<ISplit>;
    /** Optional check number for bank transactions. */
    checkNumber: string | null;
    /** SHA-256 hash for duplicate detection during imports. */
    importHash: string;
    /** ISO timestamp when the record was created. */
    createdAt: ISODateString;
    /** ISO timestamp when the record was last modified. */
    updatedAt: ISODateString;
    /** Optional ID of a linked transfer record if this transaction is part of a cross-account transfer. */
    linkedTransferId?: EntityId;
}

/**
 * A cross-account transfer connecting two transactions.
 */
export interface ITransfer {
    /** Unique ID for the transfer record. */
    id: EntityId;
    /** Date the transfer occurred. */
    date: ISODateString;
    /** Amount of the transfer (positive absolute value). */
    amount: Cents;
    /** ID of the source account. */
    fromAccountId: EntityId;
    /** ID of the destination account. */
    toAccountId: EntityId;
    /** ID of the transaction recorded in the source account. */
    fromTransactionId: EntityId;
    /** ID of the transaction recorded in the destination account. */
    toTransactionId: EntityId;
    /** Snapshot of the source account name in case it is deleted. */
    fromAccountNameSnapshot: string;
    /** Snapshot of the destination account name in case it is deleted. */
    toAccountNameSnapshot: string;
    /** Optional memo for the transfer. */
    memo: string;
    /** ISO timestamp when the record was created. */
    createdAt: ISODateString;
    /** ISO timestamp when the record was last modified. */
    updatedAt: ISODateString;
    /** ISO timestamp when the record was soft-deleted (null if active). */
    deletedAt: ISODateString | null;
}

/**
 * An entity that receives or pays money.
 */
export interface IPayee {
    /** Unique ID for the payee. */
    id: EntityId;
    /** Human-readable name (e.g., "Starbucks"). */
    name: string;
    /** Geographical Address. */
