import type { Database, SqlValue } from 'sql.js';

import { SQL_QUERIES } from '../storage/SQLiteAdapter';

// ── Public types ──────────────────────────────────────────────────────────────

/**
 * Both sides of a conflicting transaction.
 * "mine" = local version, "theirs" = remote (Drive) version.
 *
 * A true conflict occurs when BOTH local and remote updatedAt timestamps
 * are newer than the last Drive sync time. LWW cannot auto-resolve these
 * without potentially discarding user intent, so they are surfaced in the
 * conflict resolution modal.
 */
export interface ITransactionConflict {
    id: string;
    mine: IConflictSide;
    theirs: IConflictSide;
}

export interface IConflictSide {
    date: string;
    payee: string;
    totalAmount: number; // in cents
    memo: string | null;
    status: string;
    checkNumber: string | null;
    accountId: string;
    payeeId: string;
    importHash: string | null;
    updatedAt: string;
}

/**
 * Result returned by mergeRemoteIntoLocal().
 */
export interface IMergeResult {
    /** Records where remote was newer and was silently applied (LWW). */
    mergedCount: number;
    /** Transactions where BOTH sides changed since last Drive sync. */
    conflicts: Array<ITransactionConflict>;
}

// ── Internal types ────────────────────────────────────────────────────────────

interface IMergeable {
    id: string;
    updatedAt: string;
    isDeleted: number;
    clientId: string;
    createdAt?: string;
    accountId?: string;
    payeeId?: string;
    date?: string;
    payee?: string;
    memo?: string;
    totalAmount?: number;
    status?: string;
    checkNumber?: string | null;
    importHash?: string;
    categoryId?: string;
    transactionId?: string;
    scheduleId?: string;
    name?: string;
    type?: string;
    institutionName?: string;
    isActive?: number;
    deletedAt?: string;
    address?: string;
    city?: string;
    state?: string;
    zipCode?: string;
    latitude?: number;
    longitude?: number;
    website?: string;
    phone?: string;
    notes?: string;
    defaultCategoryId?: string;
    parentId?: string;
    description?: string;
    frequency?: string;
    paymentMethod?: string;
    startDate?: string;
    endDate?: string;
    nextDueDate?: string;
    lastOccurredDate?: string;
    autoPost?: number;
    amount?: number;
}

// ── Engine ────────────────────────────────────────────────────────────────────

/**
 * SQLiteMergeEngine handles the logical merging of two Path Logic databases.
 *
 * Strategy:
 *   - New remote records → inserted locally (no conflict)
 *   - Remote newer than lastSyncTime, local unchanged → LWW: apply remote
 *   - BOTH modified since lastSyncTime → conflict: return to caller for resolution
 *   - Local newer, remote unchanged → keep local (no action)
 */
// eslint-disable-next-line @typescript-eslint/no-extraneous-class
export class SQLiteMergeEngine {
    // eslint-disable-next-line @typescript-eslint/no-empty-function
    private constructor() {}

    /**
     * Merges a remote database into the local one.
     *
     * @param remoteDb       The remote Drive database instance
     * @param localDb        The local (primary) database instance
     * @param lastSyncTime   Unix ms timestamp of the last successful Drive sync.
     *                       Pass 0 on first sync (treats all remote records as newer).
     * @returns IMergeResult with the count of auto-merged records and any conflicts.
     */
    public static async mergeRemoteIntoLocal(
        remoteDb: Database,
        localDb: Database,
        lastSyncTime: number = 0
    ): Promise<IMergeResult> {
        let mergedCount = 0;
        const conflicts: Array<ITransactionConflict> = [];

        // Merge in dependency order:
        // 1. Categories (referenced by payees, splits, schedules)
        // 2. Payees (referenced by transactions, schedules)
        // 3. Accounts (referenced by transactions, schedules)
        // 4. Transactions & Splits
        // 5. Recurring Schedules & Splits

        mergedCount += this.mergeTable(
            remoteDb,
            localDb,
            'categories',
            this.mapCategory,
            lastSyncTime
        );
        mergedCount += this.mergeTable(remoteDb, localDb, 'payees', this.mapPayee, lastSyncTime);
        mergedCount += this.mergeTable(
            remoteDb,
            localDb,
            'accounts',
            this.mapAccount,
            lastSyncTime
        );

        const txResult = this.mergeTransactions(remoteDb, localDb, lastSyncTime);
        mergedCount += txResult.mergedCount;
        conflicts.push(...txResult.conflicts);

        mergedCount += this.mergeRecurringSchedules(remoteDb, localDb, lastSyncTime);

        return { mergedCount, conflicts };
    }

    // ── Generic flat-table merger ─────────────────────────────────────────────

    private static mergeTable<T extends IMergeable>(
        remoteDb: Database,
        localDb: Database,
        tableName: string,
        mapper: (row: Array<SqlValue>) => T,
        lastSyncTime: number
    ): number {
        let mergedCount = 0;

        const remoteResult = remoteDb.exec(`SELECT * FROM ${tableName} `);
        if (remoteResult.length === 0 || !remoteResult[0]) return 0;

        for (const row of remoteResult[0].values) {
            if (!row) continue;
            const remoteItem = mapper(row);

            const localResult = localDb.exec(`SELECT * FROM ${tableName} WHERE id = ? `, [
                remoteItem.id
            ]);

            if (localResult.length === 0 || !localResult[0] || localResult[0].values.length === 0) {
                // New record from remote — insert
                this.insertItem(localDb, tableName, remoteItem);
                mergedCount++;
                continue;
            }

            const localRow = localResult[0].values[0];
            if (!localRow) continue;
            const localItem = mapper(localRow);

            const remoteMs = new Date(remoteItem.updatedAt).getTime();
            const localMs = new Date(localItem.updatedAt).getTime();

            if (remoteMs > lastSyncTime && localMs <= lastSyncTime) {
                // Remote changed since last sync, local unchanged → apply remote
                this.updateItem(localDb, tableName, remoteItem);
                mergedCount++;
            }
            // else: local is newer or both equal → keep local
        }

        return mergedCount;
    }

    // ── Transaction merger (with conflict detection) ──────────────────────────

    private static mergeTransactions(
        remoteDb: Database,
        localDb: Database,
        lastSyncTime: number
    ): { mergedCount: number; conflicts: Array<ITransactionConflict> } {
        let mergedCount = 0;
        const conflicts: Array<ITransactionConflict> = [];

        const remoteResult = remoteDb.exec(`SELECT * FROM transactions`);
        if (remoteResult.length === 0 || !remoteResult[0]) return { mergedCount, conflicts };

        for (const row of remoteResult[0].values) {
            if (!row) continue;
            const remoteTx = this.mapTransaction(row);

            const localResult = localDb.exec(`SELECT * FROM transactions WHERE id = ? `, [
                remoteTx.id
            ]);
            const existsLocally =
                localResult.length > 0 &&
                localResult[0] !== undefined &&
                localResult[0].values.length > 0;

            if (!existsLocally) {
                // New transaction from remote — insert directly
                this.applyTransaction(localDb, remoteTx, remoteDb);
                mergedCount++;
                continue;
            }

            const localRow = localResult[0]?.values[0];
            if (!localRow) continue;
            const localTx = this.mapTransaction(localRow);
            const remoteMs = new Date(remoteTx.updatedAt).getTime();
            const localMs = new Date(localTx.updatedAt).getTime();

            const remoteChangedSinceSync = remoteMs > lastSyncTime;
            const localChangedSinceSync = localMs > lastSyncTime;

            if (remoteChangedSinceSync && localChangedSinceSync) {
                // ── True conflict: BOTH sides changed since last Drive sync ──
                // Surface to user for resolution instead of silently discarding.
                conflicts.push({
                    id: remoteTx.id,
                    mine: this.toConflictSide(localTx),
                    theirs: this.toConflictSide(remoteTx)
                });
            } else if (remoteChangedSinceSync && !localChangedSinceSync) {
                // Remote changed, local unchanged → apply remote (LWW)
                this.applyTransaction(localDb, remoteTx, remoteDb);
                mergedCount++;
            }
            // else: local changed or both equal → keep local
        }

        return { mergedCount, conflicts };
    }

    // ── Recurring schedule merger ─────────────────────────────────────────────

    private static mergeRecurringSchedules(
        remoteDb: Database,
        localDb: Database,
        lastSyncTime: number
    ): number {
        let mergedCount = 0;

        const remoteResult = remoteDb.exec(`SELECT * FROM recurring_schedules`);
        if (remoteResult.length === 0 || !remoteResult[0]) return 0;

        for (const row of remoteResult[0].values) {
            if (!row) continue;
            const remoteSchedule = this.mapSchedule(row);

            const localResult = localDb.exec(
                `SELECT updatedAt, isDeleted FROM recurring_schedules WHERE id = ? `,
                [remoteSchedule.id]
            );
            const existsLocally =
                localResult.length > 0 &&
                localResult[0] !== undefined &&
                localResult[0].values.length > 0;

            if (!existsLocally) {
                this.applySchedule(localDb, remoteSchedule, remoteDb);
                mergedCount++;
                continue;
            }

            const results = localResult[0];
            if (results && results.values.length > 0) {
                const localRow = results.values[0];
                if (localRow && localRow[0]) {
                    const localMs = new Date(localRow[0] as string).getTime();
                    const remoteMs = new Date(remoteSchedule.updatedAt).getTime();

                    if (remoteMs > lastSyncTime && localMs <= lastSyncTime) {
                        this.applySchedule(localDb, remoteSchedule, remoteDb);
                        mergedCount++;
                    }
                }
            }
        }

        return mergedCount;
    }

    // ── Helpers ───────────────────────────────────────────────────────────────

    private static toConflictSide(tx: IMergeable): IConflictSide {
        return {
            date: tx.date ?? '',
            payee: tx.payee ?? '',
            totalAmount: tx.totalAmount ?? 0,
            memo: tx.memo ?? null,
            status: tx.status ?? '',
            checkNumber: tx.checkNumber ?? null,
            accountId: tx.accountId ?? '',
            payeeId: tx.payeeId ?? '',
            importHash: tx.importHash ?? null,
            updatedAt: tx.updatedAt
        };
    }

    private static applyTransaction(
        localDb: Database,
        remoteTx: IMergeable,
        remoteDb: Database
    ): void {
        const remoteSplitsResult = remoteDb.exec(`SELECT * FROM splits WHERE transaction_id = ? `, [
            remoteTx.id
        ]);
        const remoteSplits = (remoteSplitsResult[0]?.values || [])
            .filter((r): r is Array<SqlValue> => r !== null)
            .map(r => this.mapSplit(r));

        localDb.run(
            SQL_QUERIES.INSERT_TRANSACTION.replace('INSERT INTO', 'INSERT OR REPLACE INTO'),
            [
                remoteTx.id,
                remoteTx.accountId as SqlValue,
                remoteTx.payeeId as SqlValue,
                remoteTx.date as SqlValue,
                remoteTx.payee as SqlValue,
                remoteTx.memo as SqlValue,
                remoteTx.totalAmount as SqlValue,
                remoteTx.status as SqlValue,
                remoteTx.checkNumber as SqlValue,
                remoteTx.importHash as SqlValue,
                remoteTx.isDeleted,
                remoteTx.clientId,
                remoteTx.createdAt ?? null,
                remoteTx.updatedAt
            ]
        );

        localDb.run('DELETE FROM splits WHERE transaction_id = ?', [remoteTx.id]);
        for (const split of remoteSplits) {
            localDb.run(SQL_QUERIES.INSERT_SPLIT, [
                split.id,
                remoteTx.id,
                split.categoryId as SqlValue,
                split.memo as SqlValue,
                split.amount as SqlValue,
                split.isDeleted,
                split.clientId,
                split.updatedAt
            ]);
        }
    }

    private static applySchedule(
        localDb: Database,
        remoteSchedule: IMergeable,
        remoteDb: Database
    ): void {
        const remoteSplitsResult = remoteDb.exec(
            `SELECT * FROM recurring_splits WHERE schedule_id = ? `,
            [remoteSchedule.id]
        );
        const remoteSplits = (remoteSplitsResult[0]?.values || [])
            .filter((r): r is Array<SqlValue> => r !== null)
            .map(r => this.mapRecurringSplit(r));

        localDb.run(
            SQL_QUERIES.INSERT_RECURRING_SCHEDULE.replace('INSERT INTO', 'INSERT OR REPLACE INTO'),
            [
                remoteSchedule.id,
                remoteSchedule.accountId as SqlValue,
                remoteSchedule.payee as SqlValue,
                remoteSchedule.totalAmount as SqlValue,
                remoteSchedule.type as SqlValue,
                remoteSchedule.frequency as SqlValue,
                remoteSchedule.paymentMethod as SqlValue,
                remoteSchedule.startDate as SqlValue,
                remoteSchedule.endDate as SqlValue,
                remoteSchedule.nextDueDate as SqlValue,
                remoteSchedule.lastOccurredDate as SqlValue,
                remoteSchedule.memo as SqlValue,
                remoteSchedule.autoPost as SqlValue,
                remoteSchedule.isActive as SqlValue,
                remoteSchedule.isDeleted,
                remoteSchedule.clientId,
                remoteSchedule.createdAt ?? null,
                remoteSchedule.updatedAt
            ]
        );

        localDb.run('DELETE FROM recurring_splits WHERE schedule_id = ?', [remoteSchedule.id]);
        for (const split of remoteSplits) {
            localDb.run(SQL_QUERIES.INSERT_RECURRING_SPLIT, [
                split.id,
                remoteSchedule.id,
                split.categoryId as SqlValue,
                split.memo as SqlValue,
                split.amount as SqlValue,
                split.isDeleted,
                split.clientId,
                split.updatedAt
            ]);
        }
    }

    // ── Mappers ───────────────────────────────────────────────────────────────

    private static mapTransaction(row: Array<SqlValue>): IMergeable {
        return {
            id: row[0] as string,
            accountId: row[1] as string,
            payeeId: row[2] as string,
            date: row[3] as string,
            payee: row[4] as string,
            memo: row[5] as string,
            totalAmount: row[6] as number,
            status: row[7] as string,
            checkNumber: row[8] as string,
            importHash: row[9] as string,
            isDeleted: row[10] as number,
            clientId: row[11] as string,
            createdAt: row[12] as string,
            updatedAt: row[13] as string
        };
    }

    private static mapSplit(row: Array<SqlValue>): IMergeable {
        return {
            id: row[0] as string,
            transactionId: row[1] as string,
            categoryId: row[2] as string,
            memo: row[3] as string,
            amount: row[4] as number,
            isDeleted: row[5] as number,
            clientId: row[6] as string,
            updatedAt: row[7] as string
        };
    }

    private static mapAccount(row: Array<SqlValue>): IMergeable {
        return {
            id: row[0] as string,
            name: row[1] as string,
            type: row[2] as string,
            institutionName: row[3] as string,
            isActive: row[4] as number,
            deletedAt: row[5] as string,
            isDeleted: row[6] as number,
            clientId: row[7] as string,
            createdAt: row[8] as string,
            updatedAt: row[9] as string
        };
    }

    private static mapPayee(row: Array<SqlValue>): IMergeable {
        return {
            id: row[0] as string,
            name: row[1] as string,
            address: row[2] as string,
            city: row[3] as string,
            state: row[4] as string,
            zipCode: row[5] as string,
            latitude: row[6] as number,
            longitude: row[7] as number,
            website: row[8] as string,
            phone: row[9] as string,
            notes: row[10] as string,
            defaultCategoryId: row[11] as string,
            isDeleted: row[12] as number,
            clientId: row[13] as string,
            createdAt: row[14] as string,
            updatedAt: row[15] as string
        };
    }

    private static mapCategory(row: Array<SqlValue>): IMergeable {
        return {
            id: row[0] as string,
            parentId: row[1] as string,
            name: row[2] as string,
            description: row[3] as string,
            isActive: row[4] as number,
            isDeleted: row[5] as number,
            clientId: row[6] as string,
            createdAt: row[7] as string,
            updatedAt: row[8] as string
        };
    }

    private static mapSchedule(row: Array<SqlValue>): IMergeable {
        return {
            id: row[0] as string,
            accountId: row[1] as string,
            payee: row[2] as string,
            totalAmount: row[3] as number,
            type: row[4] as string,
            frequency: row[5] as string,
            paymentMethod: row[6] as string,
            startDate: row[7] as string,
            endDate: row[8] as string,
            nextDueDate: row[9] as string,
            lastOccurredDate: row[10] as string,
            memo: row[11] as string,
            autoPost: row[12] as number,
            isActive: row[13] as number,
            isDeleted: row[14] as number,
            clientId: row[15] as string,
            createdAt: row[16] as string,
            updatedAt: row[17] as string
        };
    }

    private static mapRecurringSplit(row: Array<SqlValue>): IMergeable {
        return {
            id: row[0] as string,
            scheduleId: row[1] as string,
            categoryId: row[2] as string,
            memo: row[3] as string,
            amount: row[4] as number,
            isDeleted: row[5] as number,
            clientId: row[6] as string,
            updatedAt: row[7] as string
        };
    }

    // ── DB write helpers ──────────────────────────────────────────────────────

    private static insertItem(db: Database, table: string, item: IMergeable): void {
        const itemObj = item as unknown as Record<string, unknown>;
        const columns = Object.keys(itemObj).filter(k => typeof itemObj[k] !== 'undefined');
        const placeholders = columns.map(() => '?').join(', ');
        const values = columns.map(c => itemObj[c]) as Array<SqlValue>;
        db.run(`INSERT INTO ${table} (${columns.join(', ')}) VALUES(${placeholders})`, values);
    }

    private static updateItem(db: Database, table: string, item: IMergeable): void {
        const itemObj = item as unknown as Record<string, unknown>;
        const columns = Object.keys(itemObj).filter(
            k => k !== 'id' && typeof itemObj[k] !== 'undefined'
        );
        const setClause = columns.map(c => `${c} = ?`).join(', ');
        const values = columns.map(c => itemObj[c]) as Array<SqlValue>;
        values.push(item['id'] as SqlValue);
        db.run(`UPDATE ${table} SET ${setClause} WHERE id = ? `, values);
    }
}

import type { ISplit, ITransaction } from '../domain/types';
import { Frequency } from '../domain/types';

export interface IDetectedPattern {
    /** Normalized payee name used as the key. */
    payee: string;
    /** Account where the transactions were found. */
    accountId: string;
    /** Suggested repeating frequency. */
    suggestedFrequency: Frequency;
    /** Median amount (in cents) across matched occurrences. */
    suggestedAmount: number;
    /**
     * 0–1 confidence score.
     * 0.7+ = high confidence (safe to pre-select).
     * 0.4–0.69 = medium (show to user with caveat).
     * <0.4 = low (suppress unless user opts into low-confidence).
     */
    confidence: number;
    /** The most recent occurrence (used to populate the recurring form). */
    mostRecentTransaction: ITransaction;
    /** Splits from the most recent occurrence (preserves split structure). */
    mostRecentSplits: Array<ISplit>;
    /** Sample of dates from matched transactions. */
    sampleDates: Array<string>;
}

// ── Frequency thresholds (median days between occurrences) ──────────────────
interface IFrequencyBucket {
    frequency: Frequency;
    /** Expected interval in days (center). */
    center: number;
    /** Acceptable deviation ±days from center. */
    tolerance: number;
}

const FREQUENCY_BUCKETS: Array<IFrequencyBucket> = [
    { frequency: Frequency.Weekly, center: 7, tolerance: 2 },
    { frequency: Frequency.Biweekly, center: 14, tolerance: 3 },
    { frequency: Frequency.EveryFourWeeks, center: 28, tolerance: 3 },
    { frequency: Frequency.Monthly, center: 30, tolerance: 5 },
    { frequency: Frequency.Quarterly, center: 91, tolerance: 12 },
    { frequency: Frequency.Yearly, center: 365, tolerance: 20 }
];

// ── Helpers ──────────────────────────────────────────────────────────────────

function normalizePayee(payee: string): string {
    return payee.toLowerCase().trim().replace(/\s+/g, ' ');
}

function median(values: Array<number>): number {
    if (values.length === 0) return 0;
    const sorted = [...values].sort((a, b) => a - b);
    const mid = Math.floor(sorted.length / 2);
    return sorted.length % 2 !== 0
        ? (sorted[mid] ?? 0)
        : ((sorted[mid - 1] ?? 0) + (sorted[mid] ?? 0)) / 2;
}

function stddev(values: Array<number>, mean: number): number {
    if (values.length < 2) return 0;
    const variance = values.reduce((sum, v) => sum + Math.pow(v - mean, 2), 0) / values.length;
    return Math.sqrt(variance);
}

function daysBetween(dateA: string, dateB: string): number {
    return Math.round(
        Math.abs(new Date(dateB).getTime() - new Date(dateA).getTime()) / (1000 * 60 * 60 * 24)
    );
}

function classifyFrequency(medianDays: number): Frequency | null {
    for (const bucket of FREQUENCY_BUCKETS) {
        if (Math.abs(medianDays - bucket.center) <= bucket.tolerance) {
            return bucket.frequency;
        }
    }
    return null;
}

/**
 * Compute a confidence score [0, 1] based on:
 * - Interval consistency: low stddev relative to center = higher confidence
 * - Amount consistency: low coefficient of variation = higher confidence
 * - Occurrence count: more occurrences = higher confidence
 */
function computeConfidence(
    intervals: Array<number>,
    amounts: Array<number>,
    occurrences: number
): number {
    const medianInterval = median(intervals);
    if (medianInterval === 0) return 0;

    const intervalSd = stddev(intervals, medianInterval);
    const intervalCv = intervalSd / medianInterval; // coefficient of variation

    const medianAmount = median(amounts);
    const amountSd = stddev(amounts, medianAmount);
    const amountCv = medianAmount !== 0 ? amountSd / Math.abs(medianAmount) : 1;

    // More occurrences → higher floor
    const countScore = Math.min(1, (occurrences - 2) / 6); // 0 at 2 tx, 1 at 8+

    // Interval consistency (low CV = consistent = good)
    const intervalScore = Math.max(0, 1 - intervalCv * 2);

    // Amount consistency (CV < 0.1 = fixed rate, CV > 0.5 = highly variable)
    const amountScore = Math.max(0, 1 - amountCv * 2);

    return Math.min(1, countScore * 0.25 + intervalScore * 0.45 + amountScore * 0.3);
}

// ── Public API ───────────────────────────────────────────────────────────────

const MIN_OCCURRENCES = 3;
const MIN_CONFIDENCE = 0.35;

/**
 * Analyze a flat list of transactions and return detected recurring patterns.
 * Results are sorted by confidence descending.
 *
 * @param transactions - All transactions from a ledger (or filtered by account).
 * @param minConfidence - Minimum confidence threshold (default 0.35).
 */
export function detectRecurringPatterns(
    transactions: Array<ITransaction>,
    minConfidence = MIN_CONFIDENCE
): Array<IDetectedPattern> {
    // Group by normalized payee + accountId
    const groups = new Map<string, Array<ITransaction>>();

    for (const tx of transactions) {
        if (!tx.payee) continue;
        const key = `${tx.accountId}::${normalizePayee(tx.payee)}`;
        const group = groups.get(key) ?? [];
        group.push(tx);
        groups.set(key, group);
    }

    const results: Array<IDetectedPattern> = [];

    for (const [, group] of groups) {
        if (group.length < MIN_OCCURRENCES) continue;

        // Sort by date ascending
        const sorted = [...group].sort((a, b) => a.date.localeCompare(b.date));

        // Compute intervals
        const intervals: Array<number> = [];
        for (let i = 1; i < sorted.length; i++) {
            const prev = sorted[i - 1];
            const curr = sorted[i];
            if (prev && curr) {
                intervals.push(daysBetween(prev.date, curr.date));
            }
        }

        if (intervals.length === 0) continue;

        const medianInterval = median(intervals);
        const frequency = classifyFrequency(medianInterval);
        if (!frequency) continue; // No recognizable pattern

        const amounts = sorted.map(t => t.totalAmount);
        const confidence = computeConfidence(intervals, amounts, sorted.length);

        if (confidence < minConfidence) continue;

        const mostRecent = sorted[sorted.length - 1];
        if (!mostRecent) continue;

        results.push({
            payee: mostRecent.payee,
            accountId: mostRecent.accountId,
            suggestedFrequency: frequency,
            suggestedAmount: median(amounts),
            confidence,
            mostRecentTransaction: mostRecent,
            mostRecentSplits: mostRecent.splits ?? [],
            sampleDates: sorted.slice(-5).map(t => t.date)
        });
    }

    // Sort by confidence descending
    return results.sort((a, b) => b.confidence - a.confidence);
}

import { environment } from '../../../environments/environment';
import { GDriveAuthError, notifyAuthFailure } from './errors';

const DRIVE_API_BASE: string = 'https://www.googleapis.com/drive/v3';
const UPLOAD_API_BASE: string = 'https://www.googleapis.com/upload/drive/v3';

/**
 * Get the environment-specific suffix for filenames
 */
function getEnvSuffix(): string {
    if (environment.appEnv === 'production') return '';
    return `-${environment.appEnv}`;
}

const DB_FILENAME: string = `path-logic-ledger${getEnvSuffix()}.db.enc`;
const LOCK_FILENAME: string = `sync-lock${getEnvSuffix()}.json`;

/**
 * Helper to handle GDrive API response errors
 */
async function handleResponseError(response: Response, defaultMessage: string): Promise<never> {
    let errorMessage = `${defaultMessage}: ${response.status} ${response.statusText}`;
    try {
        const errorData = await response.json();
        errorMessage += ` - ${JSON.stringify(errorData)}`;
    } catch {
        // Ignore parse error
    }

    if (response.status === 401 || response.status === 403) {
        notifyAuthFailure(response.status);
        throw new GDriveAuthError(errorMessage, response.status);
    }
    throw new Error(errorMessage);
}

export interface ILockStatus {
    clientId: string;
    deviceName: string;
    issuedAt: string;
    expiresAt: string;
    status: 'merging';
}

export interface IDriveFile {
    id: string;
    name: string;
    modifiedTime: string;
}

/** Timeout for all Drive API requests. Prevents indefinite hangs on stale tokens. */
const DRIVE_REQUEST_TIMEOUT_MS = 10_000;

/**
 * Fetch wrapper for all Google Drive API calls.
 * Applies a hard timeout via AbortController so stale/expired tokens
 * or network issues fail fast instead of hanging the UI indefinitely.
 */
async function driveApiFetch(url: string, init: RequestInit = {}): Promise<Response> {
    const controller = new AbortController();
    const timerId = setTimeout(() => controller.abort(), DRIVE_REQUEST_TIMEOUT_MS);
    try {
        return await fetch(url, { ...init, signal: controller.signal });
    } catch (err: unknown) {
        if (err instanceof DOMException && err.name === 'AbortError') {
            throw new Error(
                `Drive API request timed out after ${DRIVE_REQUEST_TIMEOUT_MS}ms: ${url}`
            );
        }
        throw err;
    } finally {
        clearTimeout(timerId);
    }
}

/**
 * Find the encrypted database file in appDataFolder
 */
export async function findDatabaseFile(accessToken: string): Promise<IDriveFile | null> {
    const response: Response = await driveApiFetch(
        `${DRIVE_API_BASE}/files?spaces=appDataFolder&q=name='${DB_FILENAME}'`,
        {
            headers: {
                Authorization: `Bearer ${accessToken}`
            }
        }
    );

    if (!response.ok) {
        await handleResponseError(response, 'Failed to list files');
    }

    const data: { files: Array<IDriveFile> } = (await response.json()) as {
        files: Array<IDriveFile>;
    };
    const files = data.files;
    return files && files.length > 0 ? (files[0] ?? null) : null;
}

/**
 * Delete both database and lock files from Drive (Factory Reset)
 */
export async function factoryResetDrive(accessToken: string): Promise<void> {
    const filesResponse = await driveApiFetch(
        `${DRIVE_API_BASE}/files?spaces=appDataFolder&q=(name='${DB_FILENAME}' or name='${LOCK_FILENAME}')`,
        {
            headers: {
                Authorization: `Bearer ${accessToken}`
            }
        }
    );

    if (!filesResponse.ok) {
        await handleResponseError(filesResponse, 'Failed to list files for reset');
    }

    const { files } = (await filesResponse.json()) as { files: Array<IDriveFile> };

    for (const file of files) {
        const deleteResponse = await driveApiFetch(`${DRIVE_API_BASE}/files/${file.id}`, {
            method: 'DELETE',
            headers: {
                Authorization: `Bearer ${accessToken}`
            }
        });

        if (!deleteResponse.ok && deleteResponse.status !== 404) {
            await handleResponseError(deleteResponse, `Failed to delete file: ${file.name}`);
        }
    }
}

/**
 * Download the encrypted database from Drive
 */
export async function downloadDatabase(accessToken: string, fileId: string): Promise<Uint8Array> {
    const response: Response = await driveApiFetch(`${DRIVE_API_BASE}/files/${fileId}?alt=media`, {
        headers: {
            Authorization: `Bearer ${accessToken}`
        }
    });

    if (!response.ok) {
        await handleResponseError(response, 'Failed to download file');
    }

    const arrayBuffer: ArrayBuffer = await response.arrayBuffer();
    return new Uint8Array(arrayBuffer);
}

/**
 * Upload encrypted database to Drive (create or update)
 */
export async function uploadDatabase(
    accessToken: string,
    encryptedData: Uint8Array,
    existingFileId?: string
): Promise<string> {
    const metadata: { name: string; parents?: Array<string> } = {
        name: DB_FILENAME
    };

    if (!existingFileId) {
        metadata.parents = new Array<string>('appDataFolder');
    }

    const form: FormData = new FormData();
    form.append('metadata', new Blob([JSON.stringify(metadata)], { type: 'application/json' }));
    form.append('file', new Blob([encryptedData as BlobPart]), DB_FILENAME);

    const url: string = existingFileId
        ? `${UPLOAD_API_BASE}/files/${existingFileId}?uploadType=multipart`
        : `${UPLOAD_API_BASE}/files?uploadType=multipart`;

    const method: string = existingFileId ? 'PATCH' : 'POST';

    const response: Response = await driveApiFetch(url, {
        method,
        headers: {
            Authorization: `Bearer ${accessToken}`
        },
        body: form
    });

    if (!response.ok) {
        await handleResponseError(response, 'Failed to upload file');
    }

    const result: { id: string } = (await response.json()) as { id: string };
    return result.id;
}

/**
 * Get current lock status from Drive
 */
export async function getLockStatus(accessToken: string): Promise<ILockStatus | null> {
    const response: Response = await driveApiFetch(
        `${DRIVE_API_BASE}/files?spaces=appDataFolder&q=name='${LOCK_FILENAME}'&fields=files(id,name,modifiedTime)`,
        {
            headers: {
                Authorization: `Bearer ${accessToken}`
            }
        }
    );

    if (!response.ok) {
        await handleResponseError(response, 'Failed to list lock files');
    }

    const data: { files: Array<{ id: string }> } = (await response.json()) as {
        files: Array<{ id: string }>;
    };
    if (data.files.length === 0) return null;

    const firstFile = data.files[0];
    if (!firstFile) return null;

    const fileId: string = firstFile.id;
    const fileResponse: Response = await driveApiFetch(
        `${DRIVE_API_BASE}/files/${fileId}?alt=media`,
        {
            headers: {
                Authorization: `Bearer ${accessToken}`
            }
        }
    );

    if (!fileResponse.ok) {
        await handleResponseError(fileResponse, 'Failed to download lock');
    }

    try {
        return (await fileResponse.json()) as ILockStatus;
    } catch {
        return null;
    }
}

/**
 * Acquire a sync lock on Drive
 */
export async function acquireLock(
    accessToken: string,
    clientId: string,
    deviceName: string
): Promise<boolean> {
    // 1. Check for existing lock
    const existingLock = await getLockStatus(accessToken);
    if (existingLock) {
        const now = new Date();
        const expiresAt = new Date(existingLock.expiresAt);

        // If lock is held by someone else and hasn't expired, we can't acquire it
        if (existingLock.clientId !== clientId && now < expiresAt) {
            return false;
        }
    }

    // 2. Upload new lock
    const now = new Date();
    const expiresAt = new Date(now.getTime() + 5 * 60 * 1000); // 5 minute TTL

    const lockStatus: ILockStatus = {
        clientId,
        deviceName,
        issuedAt: now.toISOString(),
        expiresAt: expiresAt.toISOString(),
        status: 'merging'
    };

    const metadata = {
        name: LOCK_FILENAME,
        parents: ['appDataFolder']
    };

    const searchResponse: Response = await driveApiFetch(
        `${DRIVE_API_BASE}/files?spaces=appDataFolder&q=name='${LOCK_FILENAME}'`,
        {
            headers: {
                Authorization: `Bearer ${accessToken}`
            }
        }
    );

    if (!searchResponse.ok) {
        await handleResponseError(searchResponse, 'Failed to search for locks');
    }

    const searchData: { files?: Array<{ id: string }> } = await searchResponse.json();
    if (searchData.files && Array.isArray(searchData.files)) {
        for (const file of searchData.files) {
            await driveApiFetch(`${DRIVE_API_BASE}/files/${file.id}`, {
                method: 'DELETE',
                headers: { Authorization: `Bearer ${accessToken}` }
            });
        }
    }

    const form: FormData = new FormData();
    form.append('metadata', new Blob([JSON.stringify(metadata)], { type: 'application/json' }));
    form.append('file', new Blob([JSON.stringify(lockStatus)], { type: 'application/json' }));

    const response: Response = await driveApiFetch(
        `${UPLOAD_API_BASE}/files?uploadType=multipart`,
        {
            method: 'POST',
            headers: {
                Authorization: `Bearer ${accessToken}`
            },
            body: form
        }
    );

    if (!response.ok) {
        await handleResponseError(response, 'Failed to create lock');
    }

    // 3. Concurrency Check: Wait 500ms and re-verify we are the holder
    await new Promise(resolve => setTimeout(resolve, 500));
    const verifiedLock = await getLockStatus(accessToken);

    return verifiedLock?.clientId === clientId;
}

/**
 * Release a sync lock on Drive
 */
export async function releaseLock(accessToken: string): Promise<void> {
    const response: Response = await driveApiFetch(
        `${DRIVE_API_BASE}/files?spaces=appDataFolder&q=name='${LOCK_FILENAME}'`,
        {
            headers: {
                Authorization: `Bearer ${accessToken}`
            }
        }
    );

    if (!response.ok) {
        await handleResponseError(response, 'Failed to list locks for release');
    }

    const data: { files?: Array<{ id: string }> } = await response.json();

    if (data.files && Array.isArray(data.files)) {
        for (const file of data.files) {
            // We could verify clientId here, but usually, if you're releasing, you know what you're doing.
            // For safety, let's just delete the file.
            await driveApiFetch(`${DRIVE_API_BASE}/files/${file.id}`, {
                method: 'DELETE',
                headers: {
                    Authorization: `Bearer ${accessToken}`
                }
            });
        }
    }
}

/**
 * Forcibly release a lock (manual override)
 */
export async function forceReleaseLock(accessToken: string): Promise<void> {
    const response: Response = await driveApiFetch(
        `${DRIVE_API_BASE}/files?spaces=appDataFolder&q=name='${LOCK_FILENAME}'`,
        {
            headers: {
                Authorization: `Bearer ${accessToken}`
            }
        }
    );

    if (!response.ok) {
        await handleResponseError(response, 'Failed to list locks for force release');
    }

    const data: { files?: Array<{ id: string }> } = await response.json();

    if (data.files && Array.isArray(data.files)) {
        for (const file of data.files) {
            await driveApiFetch(`${DRIVE_API_BASE}/files/${file.id}`, {
                method: 'DELETE',
                headers: {
                    Authorization: `Bearer ${accessToken}`
                }
            });
        }
    }
}

