export type Cents = number;

/**
 * Unique identifier for entities (UUID or deterministic hash).
 */
export type EntityId = string;

/**
 * ISO 8601 Date string (YYYY-MM-DD).
 * @example "2026-01-17"
 */
export type ISODateString = string;

/**
 * Isomorphic timer handle that resolves to the correct type in both Node and Browser.
 */
export type TimerHandle = ReturnType<typeof setInterval>;

/**
 * Transaction status in the ledger lifecycle.
 */
export enum TransactionStatus {
    /** Imported but not yet matched or verified by the user. */
    Pending = 'pending',
    /** Matched with bank statement but not yet frozen. */
    Cleared = 'cleared',
    /** User-verified and locked; immutable for ledger integrity. */
    Reconciled = 'reconciled'
}

/**
 * Core supported account types.
 */
export enum AccountType {
    Checking = 'checking',
    Savings = 'savings',
    Credit = 'credit',
    Cash = 'cash',
    Mortgage = 'mortgage',
    AutoLoan = 'auto_loan',
    PersonalLoan = 'personal_loan'
}

/**
 * Types of recurring schedules.
 */
export enum ScheduleType {
    Debit = 'debit',
    Deposit = 'deposit',
    Paycheck = 'paycheck'
}

export interface IMortgageMetadata {
    propertyAddress?: string;
    propertyValue?: Cents;
    escrowIncluded: boolean;
    escrowAmount?: Cents;
}

export interface IAutoLoanMetadata {
    vehicleMake?: string;
    vehicleModel?: string;
    vehicleYear?: number;
    vin?: string;
}

export interface IPersonalLoanMetadata {
    purpose?: string;
    secured: boolean;
}

export interface ILoanDetails {
    /** Original principal amount in cents */
    originalAmount: Cents;
    /** Annual Percentage Rate as decimal (e.g., 0.0375 = 3.75%) */
    interestRate: number;
    /** Total loan term in months */
    termMonths: number;
    /** Monthly payment amount in cents */
    monthlyPayment: Cents;
    /** Day of month payment is due (1-31) */
    paymentDueDay: number;
    /** Loan origination date */
    startDate: ISODateString;
    /** Type-specific metadata */
    metadata?: IMortgageMetadata | IAutoLoanMetadata | IPersonalLoanMetadata;
}

/**
 * A sub-allocation of a transaction to a category.
 */
export interface ISplit {
    /** Unique ID for the split. */
    id: EntityId;
    /** Category to which this amount is allocated. Null if uncategorized. */
    categoryId: EntityId | null;
    /** Descriptive text for this split. */
    memo: string;
    /** Amount in cents. Can be negative for deductions (taxes, fees). */
    amount: Cents;
}

/**
 * A financial transaction in the ledger.
 * Transactions consist of a total amount and one or more splits.
 */
export interface ITransaction {
    /** Unique ID for the transaction. */
    id: EntityId;
    /** ID of the account this transaction belongs to. */
    accountId: EntityId;
    /** Mandatory ID of the payee entity. */
    payeeId: EntityId;
    /** Date the transaction occurred. */
    date: ISODateString;
    /** Name of the payee or entity involved (cached for performance). */
    payee: string;
    /** Optional descriptive text for the transaction. */
    memo: string;
    /** Total amount in cents. Rule: Sum(splits) === totalAmount. */
    totalAmount: Cents;
    /** Current status in the reconciliation lifecycle. */
    status: TransactionStatus;
    /** List of splits. Must contain at least one split. */
    splits: Array<ISplit>;
    /** Optional check number for bank transactions. */
    checkNumber: string | null;
    /** SHA-256 hash for duplicate detection during imports. */
    importHash: string;
    /** ISO timestamp when the record was created. */
    createdAt: ISODateString;
    /** ISO timestamp when the record was last modified. */
    updatedAt: ISODateString;
    /** Optional ID of a linked transfer record if this transaction is part of a cross-account transfer. */
    linkedTransferId?: EntityId;
}

/**
 * A cross-account transfer connecting two transactions.
 */
export interface ITransfer {
    /** Unique ID for the transfer record. */
    id: EntityId;
    /** Date the transfer occurred. */
    date: ISODateString;
    /** Amount of the transfer (positive absolute value). */
    amount: Cents;
    /** ID of the source account. */
    fromAccountId: EntityId;
    /** ID of the destination account. */
    toAccountId: EntityId;
    /** ID of the transaction recorded in the source account. */
    fromTransactionId: EntityId;
    /** ID of the transaction recorded in the destination account. */
    toTransactionId: EntityId;
    /** Snapshot of the source account name in case it is deleted. */
    fromAccountNameSnapshot: string;
    /** Snapshot of the destination account name in case it is deleted. */
    toAccountNameSnapshot: string;
    /** Optional memo for the transfer. */
    memo: string;
    /** ISO timestamp when the record was created. */
    createdAt: ISODateString;
    /** ISO timestamp when the record was last modified. */
    updatedAt: ISODateString;
    /** ISO timestamp when the record was soft-deleted (null if active). */
    deletedAt: ISODateString | null;
}

/**
 * An entity that receives or pays money.
 */
export interface IPayee {
    /** Unique ID for the payee. */
    id: EntityId;
    /** Human-readable name (e.g., "Starbucks"). */
    name: string;
    /** Geographical Address. */
    address: string | null;
    /** City location. */
    city: string | null;
    /** State/Province. */
    state: string | null;
    /** Postal/Zip code. */
    zipCode: string | null;
    /** Coordinate for map visualization. */
    latitude: number | null;
    /** Coordinate for map visualization. */
    longitude: number | null;
    /** Official website or portal. */
    website: string | null;
    /** Contact phone number. */
    phone: string | null;
    /** Arbitrary notes about this payee. */
    notes: string | null;
    /** Default category ID suggested for new transactions. */
    defaultCategoryId: EntityId | null;
    /** ISO timestamp when the record was created. */
    createdAt: ISODateString;
    /** ISO timestamp when the record was last modified. */
    updatedAt: ISODateString;
}

/**
 * A category for organizing transactions (e.g., "Groceries", "Rent").
 * Supports a hierarchical tree structure.
 */
export interface ICategory {
    /** Unique ID for the category. */
    id: EntityId;
    /** ID of the parent category (null if top-level). */
    parentId: EntityId | null;
    /** Name of the category (e.g., "Dining Out"). */
    name: string;
    /** Optional detailed description. */
    description: string | null;
    /** Whether the category is currently available for selection. */
    isActive: boolean;
    /** ISO timestamp when the record was created. */
    createdAt: ISODateString;
    /** ISO timestamp when the record was last modified. */
    updatedAt: ISODateString;
}

/**
 * An account containing a collection of transactions.
 */
export interface IAccount {
    /** Unique ID for the account. */
    id: EntityId;
    /** Human-readable name (e.g., "Main Checking"). */
    name: string;
    /** Type of account (e.g., checking, savings). */
    type: AccountType;
    /** Financial institution name. */
    institutionName: string;
    /** Sum of all Cleared/Reconciled transactions. */
    clearedBalance: Cents;
    /** Sum of all transactions (Cleared + Pending). */
    pendingBalance: Cents;
    /** Whether the account is currently in use. */
    isActive: boolean;
    /** ISO timestamp when the record was created. */
    createdAt: ISODateString;
    /** ISO timestamp when the record was last modified. */
    updatedAt: ISODateString;
    /** ISO timestamp when the record was soft-deleted (null if active). */
    deletedAt: ISODateString | null;
    /** Optional detailed information for loan accounts. */
    loanDetails?: ILoanDetails;
}

/**
 * Frequency interval for recurring scheduled items.
 */
export enum Frequency {
    Daily = 'daily',
    Weekly = 'weekly',
    Biweekly = 'biweekly',
    EveryFourWeeks = 'every_four_weeks',
    Monthly = 'monthly',
    TwiceAMonth = 'twice_a_month',
    Bimonthly = 'bimonthly',
    Quarterly = 'quarterly',
    Yearly = 'yearly'
}

/**
 * Payment methods for scheduled transactions.
 */
export enum PaymentMethod {
    DirectDebit = 'direct_debit',
    DirectDeposit = 'direct_deposit',
    WriteCheck = 'write_check',
    ElectronicTransfer = 'electronic_transfer',
    Other = 'other'
}

/**
 * A template for generating recurring transactions.
 */
export interface IRecurringSchedule {
    /** Unique ID for the schedule. */
    id: EntityId;
    /** The account where generated transactions will be posted. */
    accountId: EntityId;
    /** Default payee for generated transactions. */
    payee: string;
    /** Total amount for the transaction (parent). */
    amount: Cents;
    /** The type of schedule (Debit, Deposit, Paycheck). */
    type: ScheduleType;
    /** How often the transaction repeats. */
    frequency: Frequency;
    /** How the payment is processed. */
    paymentMethod: PaymentMethod;
    /** Date when the schedule begins. */
    startDate: ISODateString;
    /** Optional date when the schedule ends. */
    endDate: ISODateString | null;
    /** Calculated date of the next occurrence. */
    nextDueDate: ISODateString;
    /** Date when the last transaction was posted from this schedule. */
    lastOccurredDate: ISODateString | null;
    /** Splits for the generated transaction. */
    splits: Array<ISplit>;
    /** Optional memo for the transaction. */
    memo: string;
    /** Whether to automatically post the transaction to the ledger on the due date. */
    autoPost: boolean;
    /** Whether the schedule is active and generating projections. */
    isActive: boolean;
}

/**
 * Result of parsing a single split from an external source (e.g. QIF).
 */
export interface IParsedSplit {
    category: string | null;
    amount: Cents;
    memo: string | null;
}

/**
 * Result of parsing a single transaction from an external source (e.g. QIF).
 */
export interface IParsedTransaction {
    date: ISODateString;
    amount: Cents;
    payee: string;
    memo: string;
    checkNumber: string | null;
    category: string | null;
    splits: Array<IParsedSplit>;
    importHash: string;
}

import { environment } from '../../../environments/environment';

const DB_NAME: string = `PathLogicLocalCache-${environment.appEnv}`;
const STORE_NAME = 'backups';
const KEY_SNAPSHOT = 'ledger_snapshot_v2';
const KEY_DEVICE_ID = 'pl_device_id';
const DB_VERSION = 2; // bumped from 1 → 2 for new schema

// ── Types ─────────────────────────────────────────────────────────────────────

export interface ILocalSnapshot {
    /** AES-GCM encrypted SQLite binary (same format as Drive blob) */
    encryptedData: Uint8Array;
    /** Unix timestamp (ms) of the last local commit */
    version: number;
    /** Stable random device identifier, persisted in localStorage */
    deviceId: string;
}

// ── Device ID ─────────────────────────────────────────────────────────────────

function getOrCreateDeviceId(): string {
    try {
        let id = localStorage.getItem(KEY_DEVICE_ID);
        if (!id) {
            id = `dev-${Date.now()}-${Math.random().toString(36).substring(2, 10)}`;
            localStorage.setItem(KEY_DEVICE_ID, id);
        }
        return id;
    } catch {
        return 'unknown-device';
    }
}

// ── IndexedDB helpers ─────────────────────────────────────────────────────────

async function openDB(): Promise<IDBDatabase> {
    return new Promise((resolve, reject) => {
        const request = indexedDB.open(DB_NAME, DB_VERSION);

        request.onupgradeneeded = (event: IDBVersionChangeEvent): void => {
            const db = (event.target as IDBOpenDBRequest).result;
            if (!db.objectStoreNames.contains(STORE_NAME)) {
                db.createObjectStore(STORE_NAME);
            }
        };

        request.onsuccess = (): void => resolve(request.result);
        request.onerror = (): void => reject(request.error as Error);
    });
}

// ── Primary API ───────────────────────────────────────────────────────────────

/**
 * Save an encrypted snapshot to IndexedDB.
 * Called on every mutation — this is the local commit.
 *
 * @param encryptedData  AES-GCM encrypted SQLite binary
 * @param version        Unix timestamp (ms) — defaults to Date.now()
 */
export async function saveLocalSnapshot(
    encryptedData: Uint8Array,
    version: number = Date.now()
): Promise<void> {
    try {
        const snapshot: ILocalSnapshot = {
            encryptedData,
            version,
            deviceId: getOrCreateDeviceId()
        };
        const db = await openDB();
        return new Promise((resolve, reject) => {
            const tx = db.transaction(STORE_NAME, 'readwrite');
            const store = tx.objectStore(STORE_NAME);
            const req = store.put(snapshot, KEY_SNAPSHOT);
            req.onsuccess = (): void => resolve();
            req.onerror = (): void => reject(req.error as Error);
        });
    } catch (error) {
        console.error('[LocalPersistence] Failed to save snapshot:', error);
        throw error;
    }
}

/**
 * Load the snapshot from IndexedDB.
 * Returns null if no local data exists (new device / first install).
 */
export async function loadLocalSnapshot(): Promise<ILocalSnapshot | null> {
    try {
        const db = await openDB();
        return new Promise((resolve, reject) => {
            const tx = db.transaction(STORE_NAME, 'readonly');
            const store = tx.objectStore(STORE_NAME);
            const req = store.get(KEY_SNAPSHOT);

            req.onsuccess = (): void => {
                const result: unknown = req.result;
                if (
                    result &&
                    typeof result === 'object' &&
                    'encryptedData' in result &&
                    'version' in result &&
                    result.encryptedData instanceof Uint8Array
                ) {
                    resolve(result as ILocalSnapshot);
                } else if (result instanceof Uint8Array) {
                    // Migrate old v1 blob (plain Uint8Array) → v2 structure
                    resolve({
                        encryptedData: result,
                        version: Date.now(),
                        deviceId: getOrCreateDeviceId()
                    });
                } else {
                    resolve(null);
                }
            };
            req.onerror = (): void => reject(req.error as Error);
        });
    } catch (error) {
        console.error('[LocalPersistence] Failed to load snapshot:', error);
        return null;
    }
}

/**
 * Returns the version timestamp of the local snapshot, or 0 if none exists.
 * Used by background sync to compare against Drive's modifiedTime.
 */
export async function getLocalVersion(): Promise<number> {
    const snapshot = await loadLocalSnapshot();
    return snapshot?.version ?? 0;
}

/**
 * Clear the stored snapshot (e.g. on sign-out).
 */
export async function clearLocalSnapshot(): Promise<void> {
    try {
        const db = await openDB();
        return new Promise((resolve, reject) => {
            const tx = db.transaction(STORE_NAME, 'readwrite');
            const store = tx.objectStore(STORE_NAME);
            const req = store.delete(KEY_SNAPSHOT);
            req.onsuccess = (): void => {
                console.log('[LocalPersistence] Snapshot cleared');
                resolve();
            };
            req.onerror = (): void => reject(req.error as Error);
        });
    } catch (error) {
        console.warn('[LocalPersistence] Failed to clear snapshot:', error);
    }
}

// ── Legacy aliases (deprecated — kept for migration safety) ───────────────────

/** @deprecated Use saveLocalSnapshot() */
export async function saveLocalFallback(data: Uint8Array): Promise<void> {
    return saveLocalSnapshot(data);
}

/** @deprecated Use loadLocalSnapshot() */
export async function loadLocalFallback(): Promise<Uint8Array | null> {
    const snap = await loadLocalSnapshot();
    return snap?.encryptedData ?? null;
}

/** @deprecated Use clearLocalSnapshot() */
export async function clearLocalFallback(): Promise<void> {
    return clearLocalSnapshot();
}

/** @deprecated Use loadLocalSnapshot() */
export async function hasLocalFallback(): Promise<boolean> {
    const snap = await loadLocalSnapshot();
    return snap !== null;
}

// ── Drive sync timestamp ──────────────────────────────────────────────────────
// Tracks when the last successful Drive sync completed.
// Used as a baseline by MergeEngine to detect true conflicts:
// a record modified on BOTH sides after this point is a conflict.

const LAST_DRIVE_SYNC_KEY = 'pl_last_drive_sync';

/**
 * Persists the timestamp of the last successful Drive sync.
 * Call this after every successful Drive upload or merge.
 */
export function saveLastDriveSyncTime(timeMs: number): void {
    try {
        localStorage.setItem(LAST_DRIVE_SYNC_KEY, String(timeMs));
    } catch {
        // localStorage may be blocked in private browsing — non-fatal
    }
}

/**
 * Returns the timestamp of the last successful Drive sync, or 0 if never synced.
 */
export function getLastDriveSyncTime(): number {
    try {
        return parseInt(localStorage.getItem(LAST_DRIVE_SYNC_KEY) ?? '0', 10) || 0;
    } catch {
        return 0;
    }
}

import { environment } from '../../../environments/environment';
import { GDriveAuthError, notifyAuthFailure } from './errors';

const DRIVE_API_BASE: string = 'https://www.googleapis.com/drive/v3';
const UPLOAD_API_BASE: string = 'https://www.googleapis.com/upload/drive/v3';

/**
 * Get the environment-specific suffix for filenames
 */
function getEnvSuffix(): string {
    if (environment.appEnv === 'production') return '';
    return `-${environment.appEnv}`;
}

const DB_FILENAME: string = `path-logic-ledger${getEnvSuffix()}.db.enc`;
const LOCK_FILENAME: string = `sync-lock${getEnvSuffix()}.json`;

/**
 * Helper to handle GDrive API response errors
 */
async function handleResponseError(response: Response, defaultMessage: string): Promise<never> {
    let errorMessage = `${defaultMessage}: ${response.status} ${response.statusText}`;
    try {
        const errorData = await response.json();
        errorMessage += ` - ${JSON.stringify(errorData)}`;
    } catch {
        // Ignore parse error
    }

    if (response.status === 401 || response.status === 403) {
        notifyAuthFailure(response.status);
        throw new GDriveAuthError(errorMessage, response.status);
    }
    throw new Error(errorMessage);
}

export interface ILockStatus {
    clientId: string;
    deviceName: string;
    issuedAt: string;
    expiresAt: string;
    status: 'merging';
}

export interface IDriveFile {
    id: string;
    name: string;
    modifiedTime: string;
}

/** Timeout for all Drive API requests. Prevents indefinite hangs on stale tokens. */
const DRIVE_REQUEST_TIMEOUT_MS = 10_000;

/**
 * Fetch wrapper for all Google Drive API calls.
 * Applies a hard timeout via AbortController so stale/expired tokens
 * or network issues fail fast instead of hanging the UI indefinitely.
 */
async function driveApiFetch(url: string, init: RequestInit = {}): Promise<Response> {
    const controller = new AbortController();
    const timerId = setTimeout(() => controller.abort(), DRIVE_REQUEST_TIMEOUT_MS);
    try {
        return await fetch(url, { ...init, signal: controller.signal });
    } catch (err: unknown) {
        if (err instanceof DOMException && err.name === 'AbortError') {
            throw new Error(
                `Drive API request timed out after ${DRIVE_REQUEST_TIMEOUT_MS}ms: ${url}`
            );
        }
        throw err;
    } finally {
        clearTimeout(timerId);
    }
}

/**
 * Find the encrypted database file in appDataFolder
 */
export async function findDatabaseFile(accessToken: string): Promise<IDriveFile | null> {
    const response: Response = await driveApiFetch(
        `${DRIVE_API_BASE}/files?spaces=appDataFolder&q=name='${DB_FILENAME}'`,
        {
            headers: {
                Authorization: `Bearer ${accessToken}`
            }
        }
    );

    if (!response.ok) {
        await handleResponseError(response, 'Failed to list files');
    }

    const data: { files: Array<IDriveFile> } = (await response.json()) as {
        files: Array<IDriveFile>;
    };
    const files = data.files;
    return files && files.length > 0 ? (files[0] ?? null) : null;
}

/**
 * Delete both database and lock files from Drive (Factory Reset)
 */
export async function factoryResetDrive(accessToken: string): Promise<void> {
    const filesResponse = await driveApiFetch(
        `${DRIVE_API_BASE}/files?spaces=appDataFolder&q=(name='${DB_FILENAME}' or name='${LOCK_FILENAME}')`,
        {
            headers: {
                Authorization: `Bearer ${accessToken}`
            }
        }
    );

    if (!filesResponse.ok) {
        await handleResponseError(filesResponse, 'Failed to list files for reset');
    }

    const { files } = (await filesResponse.json()) as { files: Array<IDriveFile> };

    for (const file of files) {
        const deleteResponse = await driveApiFetch(`${DRIVE_API_BASE}/files/${file.id}`, {
            method: 'DELETE',
            headers: {
                Authorization: `Bearer ${accessToken}`
            }
        });

        if (!deleteResponse.ok && deleteResponse.status !== 404) {
            await handleResponseError(deleteResponse, `Failed to delete file: ${file.name}`);
        }
    }
}

/**
 * Download the encrypted database from Drive
 */
export async function downloadDatabase(accessToken: string, fileId: string): Promise<Uint8Array> {
    const response: Response = await driveApiFetch(`${DRIVE_API_BASE}/files/${fileId}?alt=media`, {
        headers: {
            Authorization: `Bearer ${accessToken}`
        }
    });

    if (!response.ok) {
        await handleResponseError(response, 'Failed to download file');
    }

    const arrayBuffer: ArrayBuffer = await response.arrayBuffer();
    return new Uint8Array(arrayBuffer);
}

/**
 * Upload encrypted database to Drive (create or update)
 */
export async function uploadDatabase(
    accessToken: string,
    encryptedData: Uint8Array,
    existingFileId?: string
): Promise<string> {
    const metadata: { name: string; parents?: Array<string> } = {
        name: DB_FILENAME
    };

    if (!existingFileId) {
        metadata.parents = new Array<string>('appDataFolder');
    }

    const form: FormData = new FormData();
    form.append('metadata', new Blob([JSON.stringify(metadata)], { type: 'application/json' }));
    form.append('file', new Blob([encryptedData as BlobPart]), DB_FILENAME);

    const url: string = existingFileId
        ? `${UPLOAD_API_BASE}/files/${existingFileId}?uploadType=multipart`
        : `${UPLOAD_API_BASE}/files?uploadType=multipart`;

    const method: string = existingFileId ? 'PATCH' : 'POST';

    const response: Response = await driveApiFetch(url, {
        method,
        headers: {
            Authorization: `Bearer ${accessToken}`
        },
        body: form
    });

    if (!response.ok) {
        await handleResponseError(response, 'Failed to upload file');
    }

    const result: { id: string } = (await response.json()) as { id: string };
    return result.id;
}

/**
 * Get current lock status from Drive
 */
export async function getLockStatus(accessToken: string): Promise<ILockStatus | null> {
    const response: Response = await driveApiFetch(
        `${DRIVE_API_BASE}/files?spaces=appDataFolder&q=name='${LOCK_FILENAME}'&fields=files(id,name,modifiedTime)`,
        {
            headers: {
                Authorization: `Bearer ${accessToken}`
            }
        }
    );

    if (!response.ok) {
        await handleResponseError(response, 'Failed to list lock files');
    }

    const data: { files: Array<{ id: string }> } = (await response.json()) as {
        files: Array<{ id: string }>;
    };
    if (data.files.length === 0) return null;

    const firstFile = data.files[0];
    if (!firstFile) return null;

    const fileId: string = firstFile.id;
    const fileResponse: Response = await driveApiFetch(
        `${DRIVE_API_BASE}/files/${fileId}?alt=media`,
        {
            headers: {
                Authorization: `Bearer ${accessToken}`
            }
        }
    );

    if (!fileResponse.ok) {
        await handleResponseError(fileResponse, 'Failed to download lock');
    }

    try {
        return (await fileResponse.json()) as ILockStatus;
    } catch {
        return null;
    }
}

/**
 * Acquire a sync lock on Drive
 */
export async function acquireLock(
    accessToken: string,
    clientId: string,
    deviceName: string
): Promise<boolean> {
    // 1. Check for existing lock
    const existingLock = await getLockStatus(accessToken);
    if (existingLock) {
        const now = new Date();
        const expiresAt = new Date(existingLock.expiresAt);

        // If lock is held by someone else and hasn't expired, we can't acquire it
        if (existingLock.clientId !== clientId && now < expiresAt) {
            return false;
        }
    }

    // 2. Upload new lock
    const now = new Date();
    const expiresAt = new Date(now.getTime() + 5 * 60 * 1000); // 5 minute TTL

    const lockStatus: ILockStatus = {
        clientId,
        deviceName,
        issuedAt: now.toISOString(),
        expiresAt: expiresAt.toISOString(),
        status: 'merging'
    };

    const metadata = {
        name: LOCK_FILENAME,
        parents: ['appDataFolder']
    };

    const searchResponse: Response = await driveApiFetch(
        `${DRIVE_API_BASE}/files?spaces=appDataFolder&q=name='${LOCK_FILENAME}'`,
        {
            headers: {
                Authorization: `Bearer ${accessToken}`
            }
        }
    );

    if (!searchResponse.ok) {
        await handleResponseError(searchResponse, 'Failed to search for locks');
    }

    const searchData: { files?: Array<{ id: string }> } = await searchResponse.json();
    if (searchData.files && Array.isArray(searchData.files)) {
        for (const file of searchData.files) {
            await driveApiFetch(`${DRIVE_API_BASE}/files/${file.id}`, {
                method: 'DELETE',
                headers: { Authorization: `Bearer ${accessToken}` }
            });
        }
    }

    const form: FormData = new FormData();
    form.append('metadata', new Blob([JSON.stringify(metadata)], { type: 'application/json' }));
    form.append('file', new Blob([JSON.stringify(lockStatus)], { type: 'application/json' }));

    const response: Response = await driveApiFetch(
        `${UPLOAD_API_BASE}/files?uploadType=multipart`,
        {
            method: 'POST',
            headers: {
                Authorization: `Bearer ${accessToken}`
            },
            body: form
        }
    );

    if (!response.ok) {
        await handleResponseError(response, 'Failed to create lock');
    }

    // 3. Concurrency Check: Wait 500ms and re-verify we are the holder
    await new Promise(resolve => setTimeout(resolve, 500));
    const verifiedLock = await getLockStatus(accessToken);

    return verifiedLock?.clientId === clientId;
}

/**
 * Release a sync lock on Drive
 */
export async function releaseLock(accessToken: string): Promise<void> {
    const response: Response = await driveApiFetch(
        `${DRIVE_API_BASE}/files?spaces=appDataFolder&q=name='${LOCK_FILENAME}'`,
        {
            headers: {
                Authorization: `Bearer ${accessToken}`
            }
        }
    );

    if (!response.ok) {
        await handleResponseError(response, 'Failed to list locks for release');
    }

    const data: { files?: Array<{ id: string }> } = await response.json();

    if (data.files && Array.isArray(data.files)) {
        for (const file of data.files) {
            // We could verify clientId here, but usually, if you're releasing, you know what you're doing.
            // For safety, let's just delete the file.
            await driveApiFetch(`${DRIVE_API_BASE}/files/${file.id}`, {
                method: 'DELETE',
                headers: {
                    Authorization: `Bearer ${accessToken}`
                }
            });
        }
    }
}

/**
 * Forcibly release a lock (manual override)
 */
export async function forceReleaseLock(accessToken: string): Promise<void> {
    const response: Response = await driveApiFetch(
        `${DRIVE_API_BASE}/files?spaces=appDataFolder&q=name='${LOCK_FILENAME}'`,
        {
            headers: {
                Authorization: `Bearer ${accessToken}`
            }
        }
    );

    if (!response.ok) {
        await handleResponseError(response, 'Failed to list locks for force release');
    }

    const data: { files?: Array<{ id: string }> } = await response.json();

    if (data.files && Array.isArray(data.files)) {
        for (const file of data.files) {
            await driveApiFetch(`${DRIVE_API_BASE}/files/${file.id}`, {
                method: 'DELETE',
                headers: {
                    Authorization: `Bearer ${accessToken}`
                }
            });
        }
    }
}

import type { Database, SqlValue } from 'sql.js';

import { SQL_QUERIES } from '../storage/SQLiteAdapter';

// ── Public types ──────────────────────────────────────────────────────────────

/**
 * Both sides of a conflicting transaction.
 * "mine" = local version, "theirs" = remote (Drive) version.
 *
 * A true conflict occurs when BOTH local and remote updatedAt timestamps
 * are newer than the last Drive sync time. LWW cannot auto-resolve these
 * without potentially discarding user intent, so they are surfaced in the
 * conflict resolution modal.
 */
export interface ITransactionConflict {
    id: string;
    mine: IConflictSide;
    theirs: IConflictSide;
}

export interface IConflictSide {
    date: string;
    payee: string;
    totalAmount: number; // in cents
    memo: string | null;
    status: string;
    checkNumber: string | null;
    accountId: string;
    payeeId: string;
    importHash: string | null;
    updatedAt: string;
}

/**
 * Result returned by mergeRemoteIntoLocal().
 */
export interface IMergeResult {
    /** Records where remote was newer and was silently applied (LWW). */
    mergedCount: number;
    /** Transactions where BOTH sides changed since last Drive sync. */
    conflicts: Array<ITransactionConflict>;
}

// ── Internal types ────────────────────────────────────────────────────────────

interface IMergeable {
    id: string;
    updatedAt: string;
    isDeleted: number;
    clientId: string;
    createdAt?: string;
    accountId?: string;
    payeeId?: string;
    date?: string;
    payee?: string;
    memo?: string;
    totalAmount?: number;
    status?: string;
    checkNumber?: string | null;
    importHash?: string;
    categoryId?: string;
    transactionId?: string;
    scheduleId?: string;
    name?: string;
    type?: string;
    institutionName?: string;
    isActive?: number;
    deletedAt?: string;
    address?: string;
    city?: string;
    state?: string;
    zipCode?: string;
    latitude?: number;
    longitude?: number;
    website?: string;
    phone?: string;
    notes?: string;
    defaultCategoryId?: string;
    parentId?: string;
    description?: string;
    frequency?: string;
    paymentMethod?: string;
    startDate?: string;
    endDate?: string;
    nextDueDate?: string;
    lastOccurredDate?: string;
    autoPost?: number;
    amount?: number;
}

// ── Engine ────────────────────────────────────────────────────────────────────

/**
 * SQLiteMergeEngine handles the logical merging of two Path Logic databases.
 *
 * Strategy:
 *   - New remote records → inserted locally (no conflict)
 *   - Remote newer than lastSyncTime, local unchanged → LWW: apply remote
 *   - BOTH modified since lastSyncTime → conflict: return to caller for resolution
 *   - Local newer, remote unchanged → keep local (no action)
 */
// eslint-disable-next-line @typescript-eslint/no-extraneous-class
export class SQLiteMergeEngine {
    // eslint-disable-next-line @typescript-eslint/no-empty-function
    private constructor() {}

    /**
     * Merges a remote database into the local one.
     *
     * @param remoteDb       The remote Drive database instance
     * @param localDb        The local (primary) database instance
     * @param lastSyncTime   Unix ms timestamp of the last successful Drive sync.
     *                       Pass 0 on first sync (treats all remote records as newer).
     * @returns IMergeResult with the count of auto-merged records and any conflicts.
     */
    public static async mergeRemoteIntoLocal(
        remoteDb: Database,
        localDb: Database,
        lastSyncTime: number = 0
    ): Promise<IMergeResult> {
        let mergedCount = 0;
        const conflicts: Array<ITransactionConflict> = [];

        // Merge in dependency order:
        // 1. Categories (referenced by payees, splits, schedules)
        // 2. Payees (referenced by transactions, schedules)
        // 3. Accounts (referenced by transactions, schedules)
        // 4. Transactions & Splits
        // 5. Recurring Schedules & Splits

        mergedCount += this.mergeTable(
            remoteDb,
            localDb,
            'categories',
            this.mapCategory,
            lastSyncTime
        );
        mergedCount += this.mergeTable(remoteDb, localDb, 'payees', this.mapPayee, lastSyncTime);
        mergedCount += this.mergeTable(
            remoteDb,
            localDb,
            'accounts',
            this.mapAccount,
            lastSyncTime
        );

        const txResult = this.mergeTransactions(remoteDb, localDb, lastSyncTime);
        mergedCount += txResult.mergedCount;
        conflicts.push(...txResult.conflicts);

        mergedCount += this.mergeRecurringSchedules(remoteDb, localDb, lastSyncTime);

        return { mergedCount, conflicts };
    }

    // ── Generic flat-table merger ─────────────────────────────────────────────

    private static mergeTable<T extends IMergeable>(
        remoteDb: Database,
        localDb: Database,
        tableName: string,
        mapper: (row: Array<SqlValue>) => T,
        lastSyncTime: number
    ): number {
        let mergedCount = 0;

        const remoteResult = remoteDb.exec(`SELECT * FROM ${tableName} `);
        if (remoteResult.length === 0 || !remoteResult[0]) return 0;

        for (const row of remoteResult[0].values) {
            if (!row) continue;
            const remoteItem = mapper(row);

            const localResult = localDb.exec(`SELECT * FROM ${tableName} WHERE id = ? `, [
                remoteItem.id
            ]);

            if (localResult.length === 0 || !localResult[0] || localResult[0].values.length === 0) {
                // New record from remote — insert
                this.insertItem(localDb, tableName, remoteItem);
                mergedCount++;
                continue;
            }

            const localRow = localResult[0].values[0];
            if (!localRow) continue;
            const localItem = mapper(localRow);

            const remoteMs = new Date(remoteItem.updatedAt).getTime();
            const localMs = new Date(localItem.updatedAt).getTime();

            if (remoteMs > lastSyncTime && localMs <= lastSyncTime) {
                // Remote changed since last sync, local unchanged → apply remote
                this.updateItem(localDb, tableName, remoteItem);
                mergedCount++;
            }
            // else: local is newer or both equal → keep local
        }

        return mergedCount;
    }

    // ── Transaction merger (with conflict detection) ──────────────────────────

    private static mergeTransactions(
        remoteDb: Database,
        localDb: Database,
        lastSyncTime: number
    ): { mergedCount: number; conflicts: Array<ITransactionConflict> } {
        let mergedCount = 0;
        const conflicts: Array<ITransactionConflict> = [];

        const remoteResult = remoteDb.exec(`SELECT * FROM transactions`);
        if (remoteResult.length === 0 || !remoteResult[0]) return { mergedCount, conflicts };

        for (const row of remoteResult[0].values) {
            if (!row) continue;
            const remoteTx = this.mapTransaction(row);

            const localResult = localDb.exec(`SELECT * FROM transactions WHERE id = ? `, [
                remoteTx.id
            ]);
            const existsLocally =
                localResult.length > 0 &&
                localResult[0] !== undefined &&
                localResult[0].values.length > 0;

            if (!existsLocally) {
                // New transaction from remote — insert directly
                this.applyTransaction(localDb, remoteTx, remoteDb);
                mergedCount++;
                continue;
            }

            const localRow = localResult[0]?.values[0];
            if (!localRow) continue;
            const localTx = this.mapTransaction(localRow);
            const remoteMs = new Date(remoteTx.updatedAt).getTime();
            const localMs = new Date(localTx.updatedAt).getTime();

            const remoteChangedSinceSync = remoteMs > lastSyncTime;
            const localChangedSinceSync = localMs > lastSyncTime;

            if (remoteChangedSinceSync && localChangedSinceSync) {
                // ── True conflict: BOTH sides changed since last Drive sync ──
                // Surface to user for resolution instead of silently discarding.
                conflicts.push({
                    id: remoteTx.id,
                    mine: this.toConflictSide(localTx),
                    theirs: this.toConflictSide(remoteTx)
                });
            } else if (remoteChangedSinceSync && !localChangedSinceSync) {
                // Remote changed, local unchanged → apply remote (LWW)
                this.applyTransaction(localDb, remoteTx, remoteDb);
                mergedCount++;
            }
            // else: local changed or both equal → keep local
        }

        return { mergedCount, conflicts };
    }

    // ── Recurring schedule merger ─────────────────────────────────────────────

    private static mergeRecurringSchedules(
        remoteDb: Database,
        localDb: Database,
        lastSyncTime: number
    ): number {
        let mergedCount = 0;

        const remoteResult = remoteDb.exec(`SELECT * FROM recurring_schedules`);
        if (remoteResult.length === 0 || !remoteResult[0]) return 0;

        for (const row of remoteResult[0].values) {
            if (!row) continue;
            const remoteSchedule = this.mapSchedule(row);

            const localResult = localDb.exec(
                `SELECT updatedAt, isDeleted FROM recurring_schedules WHERE id = ? `,
                [remoteSchedule.id]
            );
            const existsLocally =
                localResult.length > 0 &&
                localResult[0] !== undefined &&
                localResult[0].values.length > 0;

            if (!existsLocally) {
                this.applySchedule(localDb, remoteSchedule, remoteDb);
                mergedCount++;
                continue;
            }

            const results = localResult[0];
            if (results && results.values.length > 0) {
                const localRow = results.values[0];
                if (localRow && localRow[0]) {
                    const localMs = new Date(localRow[0] as string).getTime();
                    const remoteMs = new Date(remoteSchedule.updatedAt).getTime();

                    if (remoteMs > lastSyncTime && localMs <= lastSyncTime) {
                        this.applySchedule(localDb, remoteSchedule, remoteDb);
                        mergedCount++;
                    }
                }
            }
        }

        return mergedCount;
    }

    // ── Helpers ───────────────────────────────────────────────────────────────

    private static toConflictSide(tx: IMergeable): IConflictSide {
        return {
            date: tx.date ?? '',
