import { computed, effect, inject, Injectable, signal } from '@angular/core';
import { Router } from '@angular/router';
import type { User } from 'firebase/auth';
import {
    browserPopupRedirectResolver,
    GoogleAuthProvider,
    onAuthStateChanged,
    signInWithPopup,
    signOut
} from 'firebase/auth';

import { environment } from '../../../environments/environment';
import { FirebaseService } from '../firebase/firebase.service';
import { PostHogService } from '../posthog/posthog.service';

/** LocalStorage key prefix for the persisted Google OAuth token. */
const TOKEN_KEY = (uid: string): string => `pl_gdtoken_${uid}`;

/**
 * Google OAuth tokens last 60 minutes. We treat them as stale at 55 min
 * so we never attempt a Drive call with an expired token.
 */
const TOKEN_TTL_MS = 55 * 60 * 1000;

interface IStoredToken {
    token: string;
    expiresAt: number;
}

/**
 * AuthService wraps Firebase Authentication with Angular signals.
 *
 * ## Sign-in Flow (Popup)
 *
 * We use signInWithPopup() with browserPopupRedirectResolver explicitly
 * passed. The COOP warning about window.close() is non-fatal — Firebase
 * communicates the credential via window.opener.postMessage() which
 * works because our app's COOP header is unsafe-none.
 *
 * signInWithRedirect() was attempted but is broken for localhost in
 * Firebase v12: the /__/auth/iframe postMessage bridge fails in Chrome's
 * current security model, causing getRedirectResult() to always return null.
 *
 * ## Token Persistence
 *
 * Google OAuth tokens are persisted in localStorage with a 55-minute TTL.
 * On page refresh, the stored token is restored in onAuthStateChanged so
 * AppComponent can take the full Drive sync path without re-prompting.
 */
@Injectable({ providedIn: 'root' })
export class AuthService {
    private readonly firebase = inject(FirebaseService);
    private readonly router = inject(Router);
    private readonly posthogService = inject(PostHogService);

    /** Internal Firebase user signal */
    private readonly _user = signal<User | null | undefined>(undefined);

    /** The current Firebase user (null = not logged in, undefined = still loading) */
    readonly currentUser = computed(() => this._user());

    /** Whether the user is currently logged in. */
    readonly isLoggedIn = computed((): boolean => environment.e2e === true || !!this.currentUser());

    /** True until onAuthStateChanged fires with a definitive value. */
    readonly isInitializing = signal<boolean>(!environment.e2e);

    /** The Google OAuth access token for Drive API calls. */
    readonly accessToken = signal<string | null>(null);

    /** The user's Firebase UID. */
    readonly userId = computed((): string | null => this.currentUser()?.uid ?? null);

    constructor() {
        if (environment.e2e) {
            this._user.set({
                uid: 'e2e-user',
                email: 'e2e@example.com',
                displayName: 'E2E User'
            } as unknown as User);
            return;
        }

        // Listen for auth state changes (fires immediately with cached state)
        onAuthStateChanged(
            this.firebase.auth,
            (user: User | null): void => {
                this._user.set(user);
                this.isInitializing.set(false);

                if (user) {
                    const cached = this.restoreStoredToken(user.uid);
                    if (cached) {
                        this.accessToken.set(cached);
                        console.info(
                            '[AuthService] Restored cached Google token from localStorage'
                        );
                    } else {
                        console.info(
                            '[AuthService] No valid cached token — user must re-authenticate for Drive'
                        );
                    }
                }
            },
            error => {
                console.error('[AuthService] Fatal error inside onAuthStateChanged:', error);
                this.isInitializing.set(false);
            }
        );

        // Navigate based on auth state
        effect((): void => {
            if (this.isInitializing()) return;
            const user = this._user();
            if (user === undefined) return;
            if (!user) {
                if (!this.router.url.startsWith('/sign-in')) {
                    void this.router.navigate(['/sign-in']);
                }
            } else if (this.router.url.startsWith('/sign-in')) {
                const urlTree = this.router.parseUrl(this.router.url);
                const returnUrl = urlTree.queryParams['returnUrl'] || '/';
                void this.router.navigateByUrl(returnUrl);
            }
        });
    }

    /**
     * Initiates Google sign-in via a popup window.
     *
     * Note: Chrome shows a COOP warning about window.close() being blocked,
     * but this is non-fatal. The credential is communicated back via
     * window.opener.postMessage() which works because our app's COOP is
     * set to unsafe-none. The popup may not auto-close but auth completes.
     *
     * signInWithRedirect() was tried but is broken for localhost in Firebase
     * v12 — getRedirectResult() always returns null due to iframe bridge
     * failures in Chrome's current security model.
     */
    async signInWithGoogle(): Promise<void> {
        const provider = new GoogleAuthProvider();
        provider.addScope('https://www.googleapis.com/auth/drive.appdata');

        const result = await signInWithPopup(
            this.firebase.auth,
            provider,
            browserPopupRedirectResolver
        );

        const credential = GoogleAuthProvider.credentialFromResult(result);
        if (credential?.accessToken) {
            this.accessToken.set(credential.accessToken);
            this.storeToken(result.user.uid, credential.accessToken);
            console.info('[AuthService] Popup sign-in complete, Drive token stored');
        }
        this.posthogService.posthog.identify(result.user.uid, {
            email: result.user.email ?? undefined,
            name: result.user.displayName ?? undefined
        });
        this.posthogService.posthog.capture('user_signed_in', { provider: 'google' });
    }

    async signOut(): Promise<void> {
        this.posthogService.posthog.capture('user_signed_out');
        this.posthogService.posthog.reset();

        const uid = this.userId();
        if (uid) this.clearStoredToken(uid);

        await signOut(this.firebase.auth);
        this.accessToken.set(null);
    }

    // ── Token persistence ─────────────────────────────────────────────────────

    private storeToken(uid: string, token: string): void {
        try {
            const payload: IStoredToken = { token, expiresAt: Date.now() + TOKEN_TTL_MS };
            localStorage.setItem(TOKEN_KEY(uid), JSON.stringify(payload));
        } catch {
            // localStorage may be full or blocked — non-fatal
        }
    }

    private restoreStoredToken(uid: string): string | null {
        try {
            const raw = localStorage.getItem(TOKEN_KEY(uid));
            if (!raw) return null;
            const { token, expiresAt } = JSON.parse(raw) as IStoredToken;
            if (Date.now() >= expiresAt) {
                localStorage.removeItem(TOKEN_KEY(uid));
                return null;
            }
            return token;
        } catch {
            return null;
        }
    }

    private clearStoredToken(uid: string): void {
        try {
            localStorage.removeItem(TOKEN_KEY(uid));
        } catch {
            // non-fatal
        }
    }
}

import type { WritableSignal } from '@angular/core';
import { inject, Injectable, signal } from '@angular/core';

import { decryptDatabase, encryptDatabase } from '../../lib/crypto/encryption';
import { GDriveAuthError } from '../../lib/storage/errors';
import {
    acquireLock,
    downloadDatabase,
    findDatabaseFile,
    forceReleaseLock,
    getLockStatus,
    type IDriveFile,
    releaseLock,
    uploadDatabase
} from '../../lib/storage/GoogleDriveAdapter';
import {
    getLastDriveSyncTime,
    getLocalVersion,
    loadLocalSnapshot,
    saveLastDriveSyncTime,
    saveLocalSnapshot
} from '../../lib/storage/LocalPersistenceAdapter';
import { getDb } from '../../lib/storage/SQLiteAdapter';
import type { IMergeResult } from '../../lib/sync/MergeEngine';
import { SQLiteMergeEngine } from '../../lib/sync/MergeEngine';
import { AuthService } from '../auth/auth.service';
import { LedgerStore } from '../ledger-store/ledger.store';
import { PostHogService } from '../posthog/posthog.service';

interface ISyncStatus {
    inProgress: boolean;
    lastSyncTime: number;
}

const SYNC_DEBOUNCE_MS: number = 2000;

/**
 * SyncService — Local-First Architecture
 *
 * IndexedDB is the primary data store. Google Drive is the background
 * cloud backup. The app is always instantly usable from local storage.
 *
 * ## Startup sequence (called from AppComponent):
 *
 *   1. initFromLocal(userId)
 *      → Load IndexedDB snapshot → decrypt → SQL.js → app is usable
 *      → Returns true if local data existed, false if new device
 *
 *   2a. If local data existed:
 *      → syncFromDrive() runs in the BACKGROUND (no await)
 *      → Downloads Drive version, compares timestamps
 *      → If Drive is newer: merge + update IndexedDB
 *      → If local is newer: upload local to Drive
 *
 *   2b. If NO local data (new device):
 *      → syncFromDrive() runs with await (blocking)
 *      → Shows "Syncing your Ledger" screen
 *      → Downloads Drive data, writes to IndexedDB, app becomes usable
 *
 * ## Write path (every mutation):
 *   LedgerStore.mutate() → SQL.js → commitToLocal() (IndexedDB, immediate)
 *                        → isDirty = true → auto-save → saveToDrive() (background)
 */
@Injectable({ providedIn: 'root' })
export class SyncService {
    private syncInProgress: boolean = false;
    private lastSyncTime: number = 0;

    readonly isSyncing: WritableSignal<boolean> = signal<boolean>(false);

    private readonly ledgerStore: LedgerStore = inject(LedgerStore);
    private readonly authService: AuthService = inject(AuthService);
    private readonly posthogService: PostHogService = inject(PostHogService);

    // ── Startup: Step 1 — Load from IndexedDB ────────────────────────────────

    /**
     * Load the local IndexedDB snapshot and hydrate the store.
     * This is always the FIRST step on startup — instant, no network.
     *
     * Sets userId on the LedgerStore so commitToLocal() can encrypt.
     *
     * @returns true if local data was found and loaded, false if new device.
     */
    async initFromLocal(userId: string): Promise<boolean> {
        this.ledgerStore.userId = userId;
        this.ledgerStore.isLoading.set(true);

        try {
            const snapshot = await loadLocalSnapshot();

            if (snapshot) {
                const decrypted = await decryptDatabase(snapshot.encryptedData, userId);
                await this.ledgerStore.loadFromEncryptedData(decrypted);
                this.ledgerStore.hasLocalFallback.set(true);
                console.info(
                    `[Sync] Loaded local snapshot (version: ${new Date(snapshot.version).toISOString()})`
                );
                return true;
            } else {
                console.info('[Sync] No local snapshot — new device or first install.');
                return false;
            }
        } catch (err: unknown) {
            console.error('[Sync] Failed to load local snapshot:', err);
            return false;
        } finally {
            this.ledgerStore.isLoading.set(false);
        }
    }

    // ── Startup: Step 2 — Background Drive sync ───────────────────────────────

    /**
     * Background Drive sync — compares local version with Drive and
     * reconciles differences. Safe to call without await after initFromLocal().
     *
     * If no Drive token is available, sets authError and returns.
     * The sync-pending banner will prompt the user to re-authenticate.
     */
    async syncFromDrive(): Promise<void> {
        const accessToken = this.authService.accessToken();
        const userId = this.authService.userId();

        if (!accessToken || !userId) {
            // No Drive token — local-only mode
            this.ledgerStore.authError.set(true);
            this.ledgerStore.syncStatus.set('pending-local');

            // Ensure the DB is initialized even without Drive
            if (!this.ledgerStore.isInitialized()) {
                await this.ledgerStore.initialize();
            }
            return;
        }

        this.isSyncing.set(true);

        try {
            const driveFile: IDriveFile | null = await findDatabaseFile(accessToken);

            if (!driveFile) {
                // No Drive file — this is a fresh install or Drive was cleared.
                // Upload local state (if any) or just mark as synced.
                if (this.ledgerStore.isInitialized()) {
                    await this.uploadToDrive(accessToken, userId, null);
                } else {
                    // Truly fresh start — no local AND no Drive
                    await this.ledgerStore.initialize();
                    this.ledgerStore.syncStatus.set('synced');
                    this.posthogService.posthog.capture('data_loaded_from_drive', {
                        source: 'fresh_start',
                        is_returning_user: false
                    });
                }
                return;
            }

            // Drive file exists — compare timestamps
            const localVersion = await getLocalVersion();
            const driveModifiedMs = new Date(driveFile.modifiedTime ?? 0).getTime();

            if (driveModifiedMs > localVersion) {
                // Drive is newer — download, decrypt, merge
                await this.downloadAndMerge(accessToken, userId, driveFile);
            } else {
                // Local is newer (or equal) — upload
                if (this.ledgerStore.isDirty()) {
                    await this.uploadToDrive(accessToken, userId, driveFile.id);
                } else {
                    this.ledgerStore.syncStatus.set('synced');
                }
            }
        } catch (error: unknown) {
            if (error instanceof GDriveAuthError) {
                this.ledgerStore.authError.set(true);
                this.ledgerStore.syncStatus.set('pending-local');
            } else {
                console.error('[Sync] syncFromDrive failed:', error);
                this.ledgerStore.syncStatus.set('error');
                this.ledgerStore.syncError.set(
                    error instanceof Error ? error.message : 'Unknown sync error'
                );
            }
        } finally {
            this.isSyncing.set(false);
        }
    }

    // ── Mutations: Save dirty state to Drive ──────────────────────────────────

    /**
     * Save current database to Drive (debounced, with lock + merge).
     * Called by AppComponent's auto-save effect after mutations.
     */
    async saveToDrive(): Promise<void> {
        const accessToken: string | null = this.authService.accessToken();
        const userId: string | null = this.authService.userId();
        if (!accessToken || !userId) return;

        const now: number = Date.now();
        if (now - this.lastSyncTime < SYNC_DEBOUNCE_MS) return;
        if (this.syncInProgress) return;

        this.syncInProgress = true;
        this.isSyncing.set(true);
        this.ledgerStore.syncStatus.set('uploading');

        try {
            const clientId: string = this.getClientId();

            const lockAcquired: boolean = await acquireLock(
                accessToken,
                clientId,
                navigator.userAgent
            );
            if (!lockAcquired) {
                console.warn('[Sync] Could not acquire lock — another device is syncing');
                this.ledgerStore.syncStatus.set('error');
                this.ledgerStore.syncError.set('Another device is currently syncing');
                return;
            }

            try {
                // Check for remote changes and merge before uploading
                const driveFile: IDriveFile | null = await findDatabaseFile(accessToken);
                if (driveFile) {
                    const remoteEncrypted = await downloadDatabase(accessToken, driveFile.id);
                    const remoteDecrypted = await decryptDatabase(remoteEncrypted, userId);

                    const localDb = getDb();
                    if (localDb) {
                        // eslint-disable-next-line @typescript-eslint/no-explicit-any
                        const SQL: any = (localDb as any).constructor;
                        // SQL is the Database class itself — instantiate directly
                        const remoteDb = new SQL(remoteDecrypted);
                        try {
                            const lastSyncTime = getLastDriveSyncTime();
                            const mergeResult: IMergeResult =
                                await SQLiteMergeEngine.mergeRemoteIntoLocal(
                                    remoteDb,
                                    localDb,
                                    lastSyncTime
                                );
                            if (mergeResult.mergedCount > 0 || mergeResult.conflicts.length > 0) {
                                this.ledgerStore.syncStatus.set('merging');
                                await this.ledgerStore.loadFromEncryptedData(
                                    new Uint8Array(localDb.export())
                                );
                                this.ledgerStore.mergeCount.set(mergeResult.mergedCount);
                                if (mergeResult.conflicts.length > 0) {
                                    this.ledgerStore.syncConflicts.set(mergeResult.conflicts);
                                }
                            }
                        } finally {
                            remoteDb.close();
                        }
                    }
                }

                // Export, encrypt, upload
                await this.uploadToDrive(accessToken, userId, driveFile?.id ?? null);
                this.lastSyncTime = Date.now();
            } finally {
                await releaseLock(accessToken);
            }
        } catch (error: unknown) {
            if (error instanceof GDriveAuthError) {
                this.ledgerStore.authError.set(true);
                this.ledgerStore.syncStatus.set('pending-local');
            } else {
                console.error('[Sync] Failed to save to Drive:', error);
                this.ledgerStore.syncStatus.set('error');
                this.ledgerStore.syncError.set(
                    error instanceof Error ? error.message : 'Unknown error'
                );
                this.posthogService.posthog.capture('sync_failed', {
                    operation: 'save',
                    error_message: error instanceof Error ? error.message : 'Unknown error'
                });
            }
        } finally {
            this.syncInProgress = false;
            this.isSyncing.set(false);
        }
    }

    // ── Utility methods ───────────────────────────────────────────────────────

    async refreshLockStatus(): Promise<void> {
        const accessToken = this.authService.accessToken();
        if (!accessToken) return;
        try {
            const status = await getLockStatus(accessToken);
            this.ledgerStore.lockStatus.set(status);
        } catch (error) {
            console.error('[Sync] Failed to refresh lock status:', error);
        }
    }

    async forceReleaseSyncLock(): Promise<void> {
        const accessToken = this.authService.accessToken();
        if (!accessToken) return;
        try {
            await forceReleaseLock(accessToken);
            this.ledgerStore.lockStatus.set(null);
            this.ledgerStore.syncError.set(null);
        } catch (error) {
            console.error('[Sync] Failed to force release lock:', error);
        }
    }

    getSyncStatus(): ISyncStatus {
        return { inProgress: this.syncInProgress, lastSyncTime: this.lastSyncTime };
    }

    // ── Private helpers ───────────────────────────────────────────────────────

    private async downloadAndMerge(
        accessToken: string,
        userId: string,
        driveFile: IDriveFile
    ): Promise<void> {
        this.ledgerStore.syncStatus.set('downloading');

        const encryptedData = await downloadDatabase(accessToken, driveFile.id);
        const decryptedData = await decryptDatabase(encryptedData, userId);

        if (!this.ledgerStore.isInitialized()) {
            // New device — load Drive data directly (no merge needed)
            await this.ledgerStore.loadFromEncryptedData(decryptedData);
            await saveLocalSnapshot(encryptedData, Date.now());
            this.ledgerStore.hasLocalFallback.set(true);
            this.ledgerStore.syncStatus.set('synced');
            this.ledgerStore.isDirty.set(false);
            saveLastDriveSyncTime(Date.now());
            this.posthogService.posthog.capture('data_loaded_from_drive', {
                source: 'drive',
                is_returning_user: true
            });
            return;
        }

        // Existing device — merge Drive into local
        this.ledgerStore.syncStatus.set('merging');
        const localDb = getDb();
        if (localDb) {
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            const SQL: any = (localDb as any).constructor;
            // SQL is the Database class itself — instantiate directly
            const remoteDb = new SQL(decryptedData);
            try {
                const lastSyncTime = getLastDriveSyncTime();
                const mergeResult: IMergeResult = await SQLiteMergeEngine.mergeRemoteIntoLocal(
                    remoteDb,
                    localDb,
                    lastSyncTime
                );
                if (mergeResult.mergedCount > 0 || mergeResult.conflicts.length > 0) {
                    await this.ledgerStore.loadFromEncryptedData(new Uint8Array(localDb.export()));
                    this.ledgerStore.mergeCount.set(mergeResult.mergedCount);
                    if (mergeResult.conflicts.length > 0) {
                        this.ledgerStore.syncConflicts.set(mergeResult.conflicts);
                    }
                    this.posthogService.posthog.capture('data_merged_from_drive', {
                        merge_count: mergeResult.mergedCount,
                        conflict_count: mergeResult.conflicts.length
                    });
                }
            } finally {
                remoteDb.close();
            }
        }

        // Upload merged result back to Drive
        await this.uploadToDrive(accessToken, userId, driveFile.id);
    }

    private async uploadToDrive(
        accessToken: string,
        userId: string,
        driveFileId: string | null
    ): Promise<void> {
        this.ledgerStore.syncStatus.set('uploading');
        const dbExport = this.ledgerStore.exportForSync();
        const encrypted = await encryptDatabase(dbExport, userId);
        await uploadDatabase(accessToken, encrypted, driveFileId ?? undefined);
        const now = Date.now();
        await saveLocalSnapshot(encrypted, now);
        saveLastDriveSyncTime(now);
        this.ledgerStore.hasLocalFallback.set(true);
        this.ledgerStore.syncStatus.set('synced');
        this.ledgerStore.isDirty.set(false);
        this.ledgerStore.syncError.set(null);
    }

    private getClientId(): string {
        let clientId = localStorage.getItem('path-logic-client-id');
        if (!clientId) {
            clientId = `client-${Date.now()}-${Math.random().toString(36).substring(2, 9)}`;
            localStorage.setItem('path-logic-client-id', clientId);
        }
        return clientId;
    }
}

export type Cents = number;

/**
 * Unique identifier for entities (UUID or deterministic hash).
 */
export type EntityId = string;

/**
 * ISO 8601 Date string (YYYY-MM-DD).
 * @example "2026-01-17"
 */
export type ISODateString = string;

/**
 * Isomorphic timer handle that resolves to the correct type in both Node and Browser.
 */
export type TimerHandle = ReturnType<typeof setInterval>;

/**
 * Transaction status in the ledger lifecycle.
 */
export enum TransactionStatus {
    /** Imported but not yet matched or verified by the user. */
    Pending = 'pending',
    /** Matched with bank statement but not yet frozen. */
    Cleared = 'cleared',
    /** User-verified and locked; immutable for ledger integrity. */
    Reconciled = 'reconciled'
}

/**
 * Core supported account types.
 */
export enum AccountType {
    Checking = 'checking',
    Savings = 'savings',
    Credit = 'credit',
    Cash = 'cash',
    Mortgage = 'mortgage',
    AutoLoan = 'auto_loan',
    PersonalLoan = 'personal_loan'
}

/**
 * Types of recurring schedules.
 */
export enum ScheduleType {
    Debit = 'debit',
    Deposit = 'deposit',
    Paycheck = 'paycheck'
}

export interface IMortgageMetadata {
    propertyAddress?: string;
    propertyValue?: Cents;
    escrowIncluded: boolean;
    escrowAmount?: Cents;
}

export interface IAutoLoanMetadata {
    vehicleMake?: string;
    vehicleModel?: string;
    vehicleYear?: number;
    vin?: string;
}

export interface IPersonalLoanMetadata {
    purpose?: string;
    secured: boolean;
}

export interface ILoanDetails {
    /** Original principal amount in cents */
    originalAmount: Cents;
    /** Annual Percentage Rate as decimal (e.g., 0.0375 = 3.75%) */
    interestRate: number;
    /** Total loan term in months */
    termMonths: number;
    /** Monthly payment amount in cents */
    monthlyPayment: Cents;
    /** Day of month payment is due (1-31) */
    paymentDueDay: number;
    /** Loan origination date */
    startDate: ISODateString;
    /** Type-specific metadata */
    metadata?: IMortgageMetadata | IAutoLoanMetadata | IPersonalLoanMetadata;
}

/**
 * A sub-allocation of a transaction to a category.
 */
export interface ISplit {
    /** Unique ID for the split. */
    id: EntityId;
    /** Category to which this amount is allocated. Null if uncategorized. */
    categoryId: EntityId | null;
    /** Descriptive text for this split. */
    memo: string;
    /** Amount in cents. Can be negative for deductions (taxes, fees). */
    amount: Cents;
}

/**
 * A financial transaction in the ledger.
 * Transactions consist of a total amount and one or more splits.
 */
export interface ITransaction {
    /** Unique ID for the transaction. */
    id: EntityId;
    /** ID of the account this transaction belongs to. */
    accountId: EntityId;
    /** Mandatory ID of the payee entity. */
    payeeId: EntityId;
    /** Date the transaction occurred. */
    date: ISODateString;
    /** Name of the payee or entity involved (cached for performance). */
    payee: string;
    /** Optional descriptive text for the transaction. */
    memo: string;
    /** Total amount in cents. Rule: Sum(splits) === totalAmount. */
    totalAmount: Cents;
    /** Current status in the reconciliation lifecycle. */
    status: TransactionStatus;
    /** List of splits. Must contain at least one split. */
    splits: Array<ISplit>;
    /** Optional check number for bank transactions. */
    checkNumber: string | null;
    /** SHA-256 hash for duplicate detection during imports. */
    importHash: string;
    /** ISO timestamp when the record was created. */
    createdAt: ISODateString;
    /** ISO timestamp when the record was last modified. */
    updatedAt: ISODateString;
    /** Optional ID of a linked transfer record if this transaction is part of a cross-account transfer. */
    linkedTransferId?: EntityId;
}

/**
 * A cross-account transfer connecting two transactions.
 */
export interface ITransfer {
    /** Unique ID for the transfer record. */
    id: EntityId;
    /** Date the transfer occurred. */
    date: ISODateString;
    /** Amount of the transfer (positive absolute value). */
    amount: Cents;
    /** ID of the source account. */
    fromAccountId: EntityId;
    /** ID of the destination account. */
    toAccountId: EntityId;
    /** ID of the transaction recorded in the source account. */
    fromTransactionId: EntityId;
    /** ID of the transaction recorded in the destination account. */
    toTransactionId: EntityId;
    /** Snapshot of the source account name in case it is deleted. */
    fromAccountNameSnapshot: string;
    /** Snapshot of the destination account name in case it is deleted. */
    toAccountNameSnapshot: string;
    /** Optional memo for the transfer. */
    memo: string;
    /** ISO timestamp when the record was created. */
    createdAt: ISODateString;
    /** ISO timestamp when the record was last modified. */
    updatedAt: ISODateString;
    /** ISO timestamp when the record was soft-deleted (null if active). */
    deletedAt: ISODateString | null;
}

/**
 * An entity that receives or pays money.
 */
export interface IPayee {
    /** Unique ID for the payee. */
    id: EntityId;
    /** Human-readable name (e.g., "Starbucks"). */
    name: string;
    /** Geographical Address. */
    address: string | null;
    /** City location. */
    city: string | null;
    /** State/Province. */
    state: string | null;
    /** Postal/Zip code. */
    zipCode: string | null;
    /** Coordinate for map visualization. */
    latitude: number | null;
    /** Coordinate for map visualization. */
    longitude: number | null;
    /** Official website or portal. */
    website: string | null;
    /** Contact phone number. */
    phone: string | null;
    /** Arbitrary notes about this payee. */
    notes: string | null;
    /** Default category ID suggested for new transactions. */
    defaultCategoryId: EntityId | null;
    /** ISO timestamp when the record was created. */
    createdAt: ISODateString;
    /** ISO timestamp when the record was last modified. */
    updatedAt: ISODateString;
}

/**
 * A category for organizing transactions (e.g., "Groceries", "Rent").
 * Supports a hierarchical tree structure.
 */
export interface ICategory {
    /** Unique ID for the category. */
    id: EntityId;
    /** ID of the parent category (null if top-level). */
    parentId: EntityId | null;
    /** Name of the category (e.g., "Dining Out"). */
    name: string;
    /** Optional detailed description. */
    description: string | null;
    /** Whether the category is currently available for selection. */
    isActive: boolean;
    /** ISO timestamp when the record was created. */
    createdAt: ISODateString;
    /** ISO timestamp when the record was last modified. */
    updatedAt: ISODateString;
}

/**
 * An account containing a collection of transactions.
 */
export interface IAccount {
    /** Unique ID for the account. */
    id: EntityId;
    /** Human-readable name (e.g., "Main Checking"). */
    name: string;
    /** Type of account (e.g., checking, savings). */
    type: AccountType;
    /** Financial institution name. */
    institutionName: string;
    /** Sum of all Cleared/Reconciled transactions. */
    clearedBalance: Cents;
    /** Sum of all transactions (Cleared + Pending). */
    pendingBalance: Cents;
    /** Whether the account is currently in use. */
    isActive: boolean;
    /** ISO timestamp when the record was created. */
    createdAt: ISODateString;
    /** ISO timestamp when the record was last modified. */
    updatedAt: ISODateString;
    /** ISO timestamp when the record was soft-deleted (null if active). */
    deletedAt: ISODateString | null;
    /** Optional detailed information for loan accounts. */
    loanDetails?: ILoanDetails;
}

/**
 * Frequency interval for recurring scheduled items.
 */
export enum Frequency {
    Daily = 'daily',
    Weekly = 'weekly',
    Biweekly = 'biweekly',
    EveryFourWeeks = 'every_four_weeks',
    Monthly = 'monthly',
    TwiceAMonth = 'twice_a_month',
    Bimonthly = 'bimonthly',
    Quarterly = 'quarterly',
    Yearly = 'yearly'
}

/**
 * Payment methods for scheduled transactions.
 */
export enum PaymentMethod {
    DirectDebit = 'direct_debit',
    DirectDeposit = 'direct_deposit',
    WriteCheck = 'write_check',
    ElectronicTransfer = 'electronic_transfer',
    Other = 'other'
}

/**
 * A template for generating recurring transactions.
 */
export interface IRecurringSchedule {
    /** Unique ID for the schedule. */
    id: EntityId;
    /** The account where generated transactions will be posted. */
    accountId: EntityId;
    /** Default payee for generated transactions. */
    payee: string;
    /** Total amount for the transaction (parent). */
    amount: Cents;
    /** The type of schedule (Debit, Deposit, Paycheck). */
    type: ScheduleType;
    /** How often the transaction repeats. */
    frequency: Frequency;
    /** How the payment is processed. */
    paymentMethod: PaymentMethod;
    /** Date when the schedule begins. */
    startDate: ISODateString;
    /** Optional date when the schedule ends. */
    endDate: ISODateString | null;
    /** Calculated date of the next occurrence. */
    nextDueDate: ISODateString;
    /** Date when the last transaction was posted from this schedule. */
    lastOccurredDate: ISODateString | null;
    /** Splits for the generated transaction. */
    splits: Array<ISplit>;
    /** Optional memo for the transaction. */
    memo: string;
    /** Whether to automatically post the transaction to the ledger on the due date. */
    autoPost: boolean;
    /** Whether the schedule is active and generating projections. */
    isActive: boolean;
}

/**
 * Result of parsing a single split from an external source (e.g. QIF).
 */
export interface IParsedSplit {
    category: string | null;
    amount: Cents;
    memo: string | null;
}

/**
 * Result of parsing a single transaction from an external source (e.g. QIF).
 */
export interface IParsedTransaction {
    date: ISODateString;
    amount: Cents;
    payee: string;
    memo: string;
    checkNumber: string | null;
    category: string | null;
    splits: Array<IParsedSplit>;
    importHash: string;
}

import type { Database, SqlValue } from 'sql.js';

import { SQL_QUERIES } from '../storage/SQLiteAdapter';

// ── Public types ──────────────────────────────────────────────────────────────

/**
 * Both sides of a conflicting transaction.
 * "mine" = local version, "theirs" = remote (Drive) version.
 *
 * A true conflict occurs when BOTH local and remote updatedAt timestamps
 * are newer than the last Drive sync time. LWW cannot auto-resolve these
 * without potentially discarding user intent, so they are surfaced in the
 * conflict resolution modal.
 */
export interface ITransactionConflict {
    id: string;
    mine: IConflictSide;
    theirs: IConflictSide;
}

export interface IConflictSide {
    date: string;
    payee: string;
    totalAmount: number; // in cents
    memo: string | null;
    status: string;
    checkNumber: string | null;
    accountId: string;
    payeeId: string;
    importHash: string | null;
    updatedAt: string;
}

/**
 * Result returned by mergeRemoteIntoLocal().
 */
export interface IMergeResult {
    /** Records where remote was newer and was silently applied (LWW). */
    mergedCount: number;
    /** Transactions where BOTH sides changed since last Drive sync. */
    conflicts: Array<ITransactionConflict>;
}

// ── Internal types ────────────────────────────────────────────────────────────

interface IMergeable {
    id: string;
    updatedAt: string;
    isDeleted: number;
    clientId: string;
    createdAt?: string;
    accountId?: string;
    payeeId?: string;
    date?: string;
    payee?: string;
    memo?: string;
    totalAmount?: number;
    status?: string;
    checkNumber?: string | null;
    importHash?: string;
    categoryId?: string;
    transactionId?: string;
    scheduleId?: string;
    name?: string;
    type?: string;
    institutionName?: string;
    isActive?: number;
    deletedAt?: string;
    address?: string;
    city?: string;
    state?: string;
    zipCode?: string;
    latitude?: number;
    longitude?: number;
    website?: string;
    phone?: string;
    notes?: string;
    defaultCategoryId?: string;
    parentId?: string;
    description?: string;
    frequency?: string;
    paymentMethod?: string;
    startDate?: string;
    endDate?: string;
    nextDueDate?: string;
    lastOccurredDate?: string;
    autoPost?: number;
    amount?: number;
}

// ── Engine ────────────────────────────────────────────────────────────────────

/**
 * SQLiteMergeEngine handles the logical merging of two Path Logic databases.
 *
 * Strategy:
 *   - New remote records → inserted locally (no conflict)
 *   - Remote newer than lastSyncTime, local unchanged → LWW: apply remote
 *   - BOTH modified since lastSyncTime → conflict: return to caller for resolution
 *   - Local newer, remote unchanged → keep local (no action)
 */
// eslint-disable-next-line @typescript-eslint/no-extraneous-class
export class SQLiteMergeEngine {
    // eslint-disable-next-line @typescript-eslint/no-empty-function
    private constructor() {}

    /**
     * Merges a remote database into the local one.
     *
     * @param remoteDb       The remote Drive database instance
     * @param localDb        The local (primary) database instance
     * @param lastSyncTime   Unix ms timestamp of the last successful Drive sync.
     *                       Pass 0 on first sync (treats all remote records as newer).
     * @returns IMergeResult with the count of auto-merged records and any conflicts.
     */
    public static async mergeRemoteIntoLocal(
        remoteDb: Database,
        localDb: Database,
        lastSyncTime: number = 0
    ): Promise<IMergeResult> {
        let mergedCount = 0;
        const conflicts: Array<ITransactionConflict> = [];

        // Merge in dependency order:
        // 1. Categories (referenced by payees, splits, schedules)
        // 2. Payees (referenced by transactions, schedules)
        // 3. Accounts (referenced by transactions, schedules)
        // 4. Transactions & Splits
        // 5. Recurring Schedules & Splits

        mergedCount += this.mergeTable(
            remoteDb,
            localDb,
            'categories',
            this.mapCategory,
            lastSyncTime
        );
        mergedCount += this.mergeTable(remoteDb, localDb, 'payees', this.mapPayee, lastSyncTime);
        mergedCount += this.mergeTable(
            remoteDb,
            localDb,
            'accounts',
            this.mapAccount,
            lastSyncTime
        );

        const txResult = this.mergeTransactions(remoteDb, localDb, lastSyncTime);
        mergedCount += txResult.mergedCount;
        conflicts.push(...txResult.conflicts);

        mergedCount += this.mergeRecurringSchedules(remoteDb, localDb, lastSyncTime);

        return { mergedCount, conflicts };
    }

    // ── Generic flat-table merger ─────────────────────────────────────────────

    private static mergeTable<T extends IMergeable>(
        remoteDb: Database,
        localDb: Database,
        tableName: string,
        mapper: (row: Array<SqlValue>) => T,
        lastSyncTime: number
    ): number {
        let mergedCount = 0;

        const remoteResult = remoteDb.exec(`SELECT * FROM ${tableName} `);
        if (remoteResult.length === 0 || !remoteResult[0]) return 0;

        for (const row of remoteResult[0].values) {
            if (!row) continue;
            const remoteItem = mapper(row);

            const localResult = localDb.exec(`SELECT * FROM ${tableName} WHERE id = ? `, [
                remoteItem.id
            ]);

            if (localResult.length === 0 || !localResult[0] || localResult[0].values.length === 0) {
                // New record from remote — insert
                this.insertItem(localDb, tableName, remoteItem);
                mergedCount++;
                continue;
            }

            const localRow = localResult[0].values[0];
            if (!localRow) continue;
            const localItem = mapper(localRow);

            const remoteMs = new Date(remoteItem.updatedAt).getTime();
            const localMs = new Date(localItem.updatedAt).getTime();

            if (remoteMs > lastSyncTime && localMs <= lastSyncTime) {
                // Remote changed since last sync, local unchanged → apply remote
                this.updateItem(localDb, tableName, remoteItem);
                mergedCount++;
            }
            // else: local is newer or both equal → keep local
        }

        return mergedCount;
    }

    // ── Transaction merger (with conflict detection) ──────────────────────────

    private static mergeTransactions(
        remoteDb: Database,
        localDb: Database,
        lastSyncTime: number
    ): { mergedCount: number; conflicts: Array<ITransactionConflict> } {
        let mergedCount = 0;
        const conflicts: Array<ITransactionConflict> = [];

        const remoteResult = remoteDb.exec(`SELECT * FROM transactions`);
        if (remoteResult.length === 0 || !remoteResult[0]) return { mergedCount, conflicts };

        for (const row of remoteResult[0].values) {
            if (!row) continue;
            const remoteTx = this.mapTransaction(row);

            const localResult = localDb.exec(`SELECT * FROM transactions WHERE id = ? `, [
                remoteTx.id
            ]);
            const existsLocally =
                localResult.length > 0 &&
                localResult[0] !== undefined &&
                localResult[0].values.length > 0;

            if (!existsLocally) {
                // New transaction from remote — insert directly
                this.applyTransaction(localDb, remoteTx, remoteDb);
                mergedCount++;
                continue;
            }

            const localRow = localResult[0]?.values[0];
            if (!localRow) continue;
            const localTx = this.mapTransaction(localRow);
            const remoteMs = new Date(remoteTx.updatedAt).getTime();
            const localMs = new Date(localTx.updatedAt).getTime();

            const remoteChangedSinceSync = remoteMs > lastSyncTime;
            const localChangedSinceSync = localMs > lastSyncTime;

            if (remoteChangedSinceSync && localChangedSinceSync) {
                // ── True conflict: BOTH sides changed since last Drive sync ──
                // Surface to user for resolution instead of silently discarding.
                conflicts.push({
                    id: remoteTx.id,
                    mine: this.toConflictSide(localTx),
                    theirs: this.toConflictSide(remoteTx)
                });
            } else if (remoteChangedSinceSync && !localChangedSinceSync) {
                // Remote changed, local unchanged → apply remote (LWW)
                this.applyTransaction(localDb, remoteTx, remoteDb);
                mergedCount++;
            }
            // else: local changed or both equal → keep local
        }

        return { mergedCount, conflicts };
    }

    // ── Recurring schedule merger ─────────────────────────────────────────────

    private static mergeRecurringSchedules(
        remoteDb: Database,
        localDb: Database,
        lastSyncTime: number
    ): number {
        let mergedCount = 0;

        const remoteResult = remoteDb.exec(`SELECT * FROM recurring_schedules`);
        if (remoteResult.length === 0 || !remoteResult[0]) return 0;

        for (const row of remoteResult[0].values) {
            if (!row) continue;
            const remoteSchedule = this.mapSchedule(row);

            const localResult = localDb.exec(
                `SELECT updatedAt, isDeleted FROM recurring_schedules WHERE id = ? `,
                [remoteSchedule.id]
            );
            const existsLocally =
                localResult.length > 0 &&
                localResult[0] !== undefined &&
                localResult[0].values.length > 0;

            if (!existsLocally) {
                this.applySchedule(localDb, remoteSchedule, remoteDb);
                mergedCount++;
                continue;
            }

            const results = localResult[0];
            if (results && results.values.length > 0) {
                const localRow = results.values[0];
                if (localRow && localRow[0]) {
                    const localMs = new Date(localRow[0] as string).getTime();
                    const remoteMs = new Date(remoteSchedule.updatedAt).getTime();

                    if (remoteMs > lastSyncTime && localMs <= lastSyncTime) {
                        this.applySchedule(localDb, remoteSchedule, remoteDb);
                        mergedCount++;
                    }
                }
            }
        }

        return mergedCount;
    }

    // ── Helpers ───────────────────────────────────────────────────────────────

    private static toConflictSide(tx: IMergeable): IConflictSide {
        return {
            date: tx.date ?? '',
            payee: tx.payee ?? '',
            totalAmount: tx.totalAmount ?? 0,
            memo: tx.memo ?? null,
            status: tx.status ?? '',
            checkNumber: tx.checkNumber ?? null,
            accountId: tx.accountId ?? '',
            payeeId: tx.payeeId ?? '',
            importHash: tx.importHash ?? null,
            updatedAt: tx.updatedAt
        };
    }

    private static applyTransaction(
        localDb: Database,
        remoteTx: IMergeable,
        remoteDb: Database
    ): void {
        const remoteSplitsResult = remoteDb.exec(`SELECT * FROM splits WHERE transaction_id = ? `, [
            remoteTx.id
        ]);
        const remoteSplits = (remoteSplitsResult[0]?.values || [])
            .filter((r): r is Array<SqlValue> => r !== null)
            .map(r => this.mapSplit(r));

        localDb.run(
            SQL_QUERIES.INSERT_TRANSACTION.replace('INSERT INTO', 'INSERT OR REPLACE INTO'),
            [
                remoteTx.id,
                remoteTx.accountId as SqlValue,
                remoteTx.payeeId as SqlValue,
                remoteTx.date as SqlValue,
                remoteTx.payee as SqlValue,
                remoteTx.memo as SqlValue,
                remoteTx.totalAmount as SqlValue,
                remoteTx.status as SqlValue,
                remoteTx.checkNumber as SqlValue,
                remoteTx.importHash as SqlValue,
                remoteTx.isDeleted,
                remoteTx.clientId,
                remoteTx.createdAt ?? null,
                remoteTx.updatedAt
            ]
        );

        localDb.run('DELETE FROM splits WHERE transaction_id = ?', [remoteTx.id]);
        for (const split of remoteSplits) {
            localDb.run(SQL_QUERIES.INSERT_SPLIT, [
                split.id,
                remoteTx.id,
                split.categoryId as SqlValue,
                split.memo as SqlValue,
                split.amount as SqlValue,
                split.isDeleted,
                split.clientId,
                split.updatedAt
            ]);
        }
    }

    private static applySchedule(
        localDb: Database,
        remoteSchedule: IMergeable,
        remoteDb: Database
    ): void {
        const remoteSplitsResult = remoteDb.exec(
            `SELECT * FROM recurring_splits WHERE schedule_id = ? `,
            [remoteSchedule.id]
        );
        const remoteSplits = (remoteSplitsResult[0]?.values || [])
            .filter((r): r is Array<SqlValue> => r !== null)
            .map(r => this.mapRecurringSplit(r));

        localDb.run(
            SQL_QUERIES.INSERT_RECURRING_SCHEDULE.replace('INSERT INTO', 'INSERT OR REPLACE INTO'),
            [
                remoteSchedule.id,
                remoteSchedule.accountId as SqlValue,
                remoteSchedule.payee as SqlValue,
                remoteSchedule.totalAmount as SqlValue,
                remoteSchedule.type as SqlValue,
                remoteSchedule.frequency as SqlValue,
                remoteSchedule.paymentMethod as SqlValue,
                remoteSchedule.startDate as SqlValue,
                remoteSchedule.endDate as SqlValue,
                remoteSchedule.nextDueDate as SqlValue,
                remoteSchedule.lastOccurredDate as SqlValue,
                remoteSchedule.memo as SqlValue,
                remoteSchedule.autoPost as SqlValue,
                remoteSchedule.isActive as SqlValue,
                remoteSchedule.isDeleted,
                remoteSchedule.clientId,
                remoteSchedule.createdAt ?? null,
                remoteSchedule.updatedAt
            ]
        );

        localDb.run('DELETE FROM recurring_splits WHERE schedule_id = ?', [remoteSchedule.id]);
        for (const split of remoteSplits) {
            localDb.run(SQL_QUERIES.INSERT_RECURRING_SPLIT, [
                split.id,
                remoteSchedule.id,
                split.categoryId as SqlValue,
                split.memo as SqlValue,
                split.amount as SqlValue,
                split.isDeleted,
                split.clientId,
                split.updatedAt
            ]);
        }
    }

    // ── Mappers ───────────────────────────────────────────────────────────────

    private static mapTransaction(row: Array<SqlValue>): IMergeable {
        return {
            id: row[0] as string,
            accountId: row[1] as string,
            payeeId: row[2] as string,
            date: row[3] as string,
            payee: row[4] as string,
            memo: row[5] as string,
            totalAmount: row[6] as number,
            status: row[7] as string,
            checkNumber: row[8] as string,
            importHash: row[9] as string,
            isDeleted: row[10] as number,
            clientId: row[11] as string,
            createdAt: row[12] as string,
            updatedAt: row[13] as string
        };
    }

    private static mapSplit(row: Array<SqlValue>): IMergeable {
        return {
            id: row[0] as string,
            transactionId: row[1] as string,
            categoryId: row[2] as string,
            memo: row[3] as string,
            amount: row[4] as number,
            isDeleted: row[5] as number,
            clientId: row[6] as string,
            updatedAt: row[7] as string
        };
    }

    private static mapAccount(row: Array<SqlValue>): IMergeable {
        return {
            id: row[0] as string,
            name: row[1] as string,
            type: row[2] as string,
            institutionName: row[3] as string,
            isActive: row[4] as number,
            deletedAt: row[5] as string,
            isDeleted: row[6] as number,
            clientId: row[7] as string,
            createdAt: row[8] as string,
            updatedAt: row[9] as string
        };
    }

    private static mapPayee(row: Array<SqlValue>): IMergeable {
        return {
            id: row[0] as string,
            name: row[1] as string,
            address: row[2] as string,
            city: row[3] as string,
            state: row[4] as string,
            zipCode: row[5] as string,
            latitude: row[6] as number,
            longitude: row[7] as number,
            website: row[8] as string,
            phone: row[9] as string,
            notes: row[10] as string,
            defaultCategoryId: row[11] as string,
            isDeleted: row[12] as number,
            clientId: row[13] as string,
            createdAt: row[14] as string,
            updatedAt: row[15] as string
        };
    }

    private static mapCategory(row: Array<SqlValue>): IMergeable {
        return {
            id: row[0] as string,
            parentId: row[1] as string,
            name: row[2] as string,
            description: row[3] as string,
            isActive: row[4] as number,
            isDeleted: row[5] as number,
            clientId: row[6] as string,
            createdAt: row[7] as string,
            updatedAt: row[8] as string
        };
    }

    private static mapSchedule(row: Array<SqlValue>): IMergeable {
        return {
            id: row[0] as string,
            accountId: row[1] as string,
            payee: row[2] as string,
            totalAmount: row[3] as number,
            type: row[4] as string,
            frequency: row[5] as string,
            paymentMethod: row[6] as string,
            startDate: row[7] as string,
            endDate: row[8] as string,
            nextDueDate: row[9] as string,
            lastOccurredDate: row[10] as string,
            memo: row[11] as string,
            autoPost: row[12] as number,
            isActive: row[13] as number,
            isDeleted: row[14] as number,
            clientId: row[15] as string,
            createdAt: row[16] as string,
            updatedAt: row[17] as string
        };
    }

    private static mapRecurringSplit(row: Array<SqlValue>): IMergeable {
        return {
            id: row[0] as string,
            scheduleId: row[1] as string,
            categoryId: row[2] as string,
            memo: row[3] as string,
            amount: row[4] as number,
            isDeleted: row[5] as number,
            clientId: row[6] as string,
            updatedAt: row[7] as string
        };
    }

    // ── DB write helpers ──────────────────────────────────────────────────────

    private static insertItem(db: Database, table: string, item: IMergeable): void {
        const itemObj = item as unknown as Record<string, unknown>;
        const columns = Object.keys(itemObj).filter(k => typeof itemObj[k] !== 'undefined');
        const placeholders = columns.map(() => '?').join(', ');
        const values = columns.map(c => itemObj[c]) as Array<SqlValue>;
        db.run(`INSERT INTO ${table} (${columns.join(', ')}) VALUES(${placeholders})`, values);
    }

    private static updateItem(db: Database, table: string, item: IMergeable): void {
        const itemObj = item as unknown as Record<string, unknown>;
        const columns = Object.keys(itemObj).filter(
            k => k !== 'id' && typeof itemObj[k] !== 'undefined'
        );
        const setClause = columns.map(c => `${c} = ?`).join(', ');
        const values = columns.map(c => itemObj[c]) as Array<SqlValue>;
        values.push(item['id'] as SqlValue);
        db.run(`UPDATE ${table} SET ${setClause} WHERE id = ? `, values);
    }
}

import { KnownCategory } from '../domain/CategoryDefaults';
import { ErrorCode } from '../domain/ErrorCode';
import type { Cents, EntityId, ISODateString, ISplit, ITransaction } from '../domain/types';
import { TransactionStatus } from '../domain/types';
import type { Result } from '../shared/Result';
import type { IValidationResult } from './invariants';
import { validateSplitSum } from './invariants';

export interface IPaycheckParams {
    id: EntityId;
    accountId: EntityId;
    payeeId: EntityId;
    date: ISODateString;
    memo?: string;
    grossPay: Cents;
    federalTax?: Cents;
    stateTax?: Cents;
    localTax?: Cents;
    socialSecurity?: Cents;
    medicare?: Cents;
    healthInsurance?: Cents;
    visionInsurance?: Cents;
    dentalInsurance?: Cents;
    fourOhOneK?: Cents;
    hsa?: Cents;
    otherDeductions?: Array<{ memo: string; amount: Cents; categoryId?: EntityId }>;
}

export interface IMortgageParams {
    id: EntityId;
    accountId: EntityId;
    payeeId: EntityId;
    date: ISODateString;
    memo?: string;
    totalAmount: Cents;
    principal: Cents;
    interest: Cents;
    escrow?: Cents;
    propertyTax?: Cents;
    pmi?: Cents;
    otherFees?: Array<{ memo: string; amount: Cents; categoryId?: EntityId }>;
}

/**
 * Interface definition for the core transaction engine.
 * Decoupled for testing and dependency injection.
 */
export interface ITransactionEngine {
    autoBalanceSplits(transaction: ITransaction): ITransaction;
    validateTransaction(transaction: ITransaction): Result<void>;
    createPaycheck(params: IPaycheckParams): ITransaction;
    createMortgagePayment(params: IMortgageParams): ITransaction;
}

/**
 * Concrete implementation of the Penny-Perfect Core Engine logic.
 */
export class TransactionEngine implements ITransactionEngine {
    /**
     * Automatically balances the splits of a transaction to match the totalAmount.
     * Strategy: Adds discrepancy to the last split or creates a new one.
     */
    public autoBalanceSplits(transaction: ITransaction): ITransaction {
        const currentSum: number = transaction.splits.reduce(
            (s: number, sp: ISplit) => s + sp.amount,
            0
        );
        const discrepancy: number = transaction.totalAmount - currentSum;

        if (discrepancy === 0) return transaction;

        const updatedSplits: Array<ISplit> = [...transaction.splits];

        if (updatedSplits.length === 0) {
            updatedSplits.push({
                id: `${transaction.id}-split-auto`,
                categoryId: null,
                memo: 'Auto-balanced discrepancy',
                amount: discrepancy
            } satisfies ISplit);
        } else {
            const lastIndex: number = updatedSplits.length - 1;
            const lastSplit: ISplit | undefined = updatedSplits[lastIndex];
            if (lastSplit) {
                updatedSplits[lastIndex] = {
                    ...lastSplit,
                    amount: lastSplit.amount + discrepancy
                } satisfies ISplit;
            }
        }

        return {
            ...transaction,
            splits: updatedSplits,
            updatedAt: new Date().toISOString()
        } satisfies ITransaction;
    }

    /**
     * Runs all domain-level validation rules for a transaction.
     */
    public validateTransaction(transaction: ITransaction): Result<void> {
        // 1. Validate split sum invariant
        const validation: IValidationResult = validateSplitSum(transaction);
        if (!validation.valid) {
            return {
                success: false,
                error: {
                    code: ErrorCode.SplitSumMismatch,
                    message: validation.error || 'Split sum mismatch',
                    details: { discrepancy: validation.discrepancy }
                }
            } satisfies Result<void>;
        }

        // 2. Validate status rules
        if (transaction.status === TransactionStatus.Reconciled) {
            // Reconciled transactions are immutable at this level
        }

        return { success: true, value: undefined } satisfies Result<void>;
    }

    /**
     * Helper to create a granular paycheck transaction.
     */
    public createPaycheck(params: IPaycheckParams): ITransaction {
        const splits: Array<ISplit> = [];
        let netAmount: number = params.grossPay;

        // Add Gross Pay split
        splits.push({
            id: `${params.id}-gross`,
            categoryId: KnownCategory.GrossPay,
            memo: 'Gross Pay',
            amount: params.grossPay
        });

        const addDeduction = (
            amount: Cents | undefined,
            categoryId: string,
            memo: string
        ): void => {
            if (amount && amount !== 0) {
                // Deductions are stored as negative amounts in splits
                const deductionAmount: number = amount > 0 ? -amount : amount;
                splits.push({
                    id: `${params.id}-${categoryId.replace('cat-', '')}`,
                    categoryId,
                    memo,
                    amount: deductionAmount
                });
                netAmount += deductionAmount;
            }
        };

        addDeduction(params.federalTax, KnownCategory.FederalTax, 'Federal Income Tax');
        addDeduction(params.stateTax, KnownCategory.StateTax, 'State Income Tax');
        addDeduction(params.localTax, KnownCategory.LocalTax, 'Local Income Tax');
        addDeduction(params.socialSecurity, KnownCategory.SocialSecurity, 'Social Security');
        addDeduction(params.medicare, KnownCategory.Medicare, 'Medicare');
        addDeduction(params.healthInsurance, KnownCategory.HealthInsurance, 'Health Insurance');
        addDeduction(params.visionInsurance, KnownCategory.VisionInsurance, 'Vision Insurance');
        addDeduction(params.dentalInsurance, KnownCategory.DentalInsurance, 'Dental Insurance');
        addDeduction(params.fourOhOneK, KnownCategory.FourOhOneK, '401(k) Contribution');
        addDeduction(params.hsa, KnownCategory.HSA, 'HSA Contribution');

        if (params.otherDeductions) {
            params.otherDeductions.forEach((d, i) => {
                const deductionAmount: number = d.amount > 0 ? -d.amount : d.amount;
                splits.push({
                    id: `${params.id}-other-${i}`,
                    categoryId: d.categoryId || KnownCategory.Uncategorized,
                    memo: d.memo,
                    amount: deductionAmount
                });
                netAmount += deductionAmount;
            });
        }

        const now: string = new Date().toISOString();
        return {
            id: params.id,
            accountId: params.accountId,
            payeeId: params.payeeId,
            date: params.date,
            payee: 'Paycheck', // Default payee name
            memo: params.memo || '',
            totalAmount: netAmount, // Total is the net amount deposited
            status: TransactionStatus.Pending,
            splits,
            checkNumber: null,
            importHash: '',
            createdAt: now,
            updatedAt: now
        } satisfies ITransaction;
    }

    /**
     * Helper to create a granular mortgage payment transaction.
     */
    public createMortgagePayment(params: IMortgageParams): ITransaction {
        const splits: Array<ISplit> = [];

        splits.push({
            id: `${params.id}-principal`,
            categoryId: KnownCategory.MortgagePrincipal,
            memo: 'Principal',
            amount: params.principal
        });

        splits.push({
            id: `${params.id}-interest`,
            categoryId: KnownCategory.MortgageInterest,
            memo: 'Interest',
            amount: params.interest
        });

        if (params.escrow) {
            splits.push({
                id: `${params.id}-escrow`,
                categoryId: KnownCategory.Escrow,
                memo: 'Escrow',
                amount: params.escrow
            });
        }

        if (params.propertyTax) {
            splits.push({
                id: `${params.id}-prop-tax`,
                categoryId: KnownCategory.PropertyTax,
                memo: 'Property Tax',
                amount: params.propertyTax
            });
        }

        if (params.pmi) {
            splits.push({
                id: `${params.id}-pmi`,
                categoryId: KnownCategory.MortgagePMI,
                memo: 'PMI',
                amount: params.pmi
            });
        }

        if (params.otherFees) {
            params.otherFees.forEach((f, i) => {
                splits.push({
                    id: `${params.id}-fee-${i}`,
                    categoryId: f.categoryId || KnownCategory.Uncategorized,
                    memo: f.memo,
                    amount: f.amount
                });
            });
        }

        const now: string = new Date().toISOString();
        return {
            id: params.id,
            accountId: params.accountId,
            payeeId: params.payeeId,
            date: params.date,
            payee: 'Mortgage',
            memo: params.memo || '',
            totalAmount: params.totalAmount,
            status: TransactionStatus.Pending,
            splits,
            checkNumber: null,
            importHash: '',
            createdAt: now,
            updatedAt: now
        } satisfies ITransaction;
    }
}

import type { Cents, IParsedSplit, IParsedTransaction, ISODateString } from '../domain/types';
import { generateImportHash } from '../engine/hashing';

export enum QIFAccountType {
    Bank = 'Bank',
    CCard = 'CCard',
    Cash = 'Cash'
}

export interface IParseError {
    code: string;
    message: string;
    line?: number;
}

export interface IParseWarning {
    code: string;
    message: string;
    line?: number;
}

export interface IQIFParseResult {
    transactions: Array<IParsedTransaction>;
    accountType: QIFAccountType;
    accountName: string | null;
    errors: Array<IParseError>;
    warnings: Array<IParseWarning>;
}

/**
 * Defensive QIF parser implementation.
 * Handles legacy Quicken Interchange Format with robust error handling.
 */
export class QIFParser {
    private readonly DATE_PATTERNS: Array<RegExp> = [
        /^(\d{1,2})\/(\d{1,2})'(\d{2,4})$/, // M/D'YY or M/D'YYYY (Quicken: 1/15'26 or 3/7'2005)
        /^(\d{1,2})\/(\d{1,2})\/(\d{4})$/, // M/D/YYYY (1/15/2026)
        /^(\d{1,2})\/(\d{1,2})\/(\d{2})$/, // M/D/YY (1/15/26)
        /^(\d{1,2})-(\d{1,2})-(\d{4})$/, // M-D-YYYY (1-15-2026)
        /^(\d{1,2})-(\d{1,2})-(\d{2})$/, // M-D-YY (1-15-26)
        /^(\d{4})-(\d{2})-(\d{2})$/ // YYYY-MM-DD (ISO)
    ];

    /**
     * Parses QIF content into structured transactions.
     */
    public parse(content: string): IQIFParseResult {
        const result: IQIFParseResult = {
            transactions: new Array<IParsedTransaction>(),
            accountType: QIFAccountType.Bank,
            accountName: null,
            errors: new Array<IParseError>(),
            warnings: new Array<IParseWarning>()
        };

        if (!content || content.trim().length === 0) {
            result.errors.push({
                code: 'EMPTY_CONTENT',
                message: 'QIF content is empty'
            });
            return result;
        }

        const lines: Array<string> = content.split('\n').map((l: string) => l.trim());
        let lineNumber: number = 0;
        let currentAccountType: QIFAccountType = QIFAccountType.Bank;

        // Parse headers (!Type, !Account)
        while (lineNumber < lines.length && lines[lineNumber]?.startsWith('!')) {
            const line: string = lines[lineNumber] ?? '';
            if (line.startsWith('!Type:')) {
                const typeHeader: string = line.substring(6);
                if (typeHeader === 'Bank') currentAccountType = QIFAccountType.Bank;
                else if (typeHeader === 'CCard') currentAccountType = QIFAccountType.CCard;
                else if (typeHeader === 'Cash') currentAccountType = QIFAccountType.Cash;
                else {
                    result.warnings.push({
                        code: 'UNKNOWN_ACCOUNT_TYPE',
                        message: `Unknown account type: ${typeHeader}, defaulting to Bank`,
                        line: lineNumber + 1
                    });
                }
                result.accountType = currentAccountType;
            } else if (line.startsWith('!Account')) {
                // Peek at next line for account name (N field)
                const nextLine = lines[lineNumber + 1];
                if (nextLine?.startsWith('N')) {
                    result.accountName = nextLine.substring(1).trim();
                    lineNumber++;
                }
            }
            lineNumber++;
        }

        // Parse transactions
        while (lineNumber < lines.length) {
            // Skip blank lines between transactions
            if (lines[lineNumber]?.trim().length === 0) {
                lineNumber++;
                continue;
            }

            const txResult: ITransactionParseResult = this.parseTransaction(lines, lineNumber);

            if (txResult.transaction) {
                result.transactions.push(txResult.transaction);
            }

            if (txResult.errors.length > 0) {
                result.errors.push(...txResult.errors);
            }

            if (txResult.warnings.length > 0) {
                result.warnings.push(...txResult.warnings);
            }

            lineNumber = txResult.nextLine;
        }

        return result;
    }

    /**
     * Parses a single transaction from QIF lines.
     */
    private parseTransaction(lines: Array<string>, startLine: number): ITransactionParseResult {
        const result: ITransactionParseResult = {
            transaction: null,
            errors: new Array<IParseError>(),
            warnings: new Array<IParseWarning>(),
            nextLine: startLine
        };

        let date: ISODateString | null = null;
        let amount: Cents | null = null;
        let payee: string = '';
        let memo: string = '';
        let checkNumber: string | null = null;
        let category: string | null = null;
        const splits: Array<IParsedSplit> = new Array<IParsedSplit>();

        let lineIdx: number = startLine;
        let foundEnd: boolean = false;

        // Parse transaction fields
        while (lineIdx < lines.length) {
            const line: string = lines[lineIdx] ?? '';
            lineIdx++;

            if (line.length === 0) continue;

            const code: string = line.charAt(0);
            const value: string = line.substring(1).trim();

            switch (code) {
                case 'D': // Date
                    try {
                        date = this.normalizeDate(value);
                    } catch {
                        result.errors.push({
                            code: 'INVALID_DATE',
                            message: `Failed to parse date: ${value}`,
                            line: lineIdx
                        });
                    }
                    break;

                case 'T': // Amount
                    try {
                        amount = this.parseAmount(value);
                    } catch {
                        result.errors.push({
                            code: 'INVALID_AMOUNT',
                            message: `Failed to parse amount: ${value}`,
                            line: lineIdx
                        });
                    }
                    break;

                case 'P': // Payee
                    payee = value;
                    break;

                case 'M': // Memo
                    memo = value;
                    break;

                case 'N': // Check number
                    checkNumber = value;
                    break;

                case 'L': // Category
                    category = value;
                    break;

                case 'C': // Cleared status (X=cleared, *=reconciled, or empty)
                    // Parser ignores this field for now, but we handle it to avoid warnings
                    break;

                case 'S': // Split category (multi-line)
                    {
                        const split: IParsedSplit = {
                            category: value,
                            amount: 0,
                            memo: null
                        };

                        // Parse following lines until we hit another transaction field or ^
                        // Can be: $ (amount), E (memo), or both in either order
                        let foundAmount: boolean = false;
                        let foundMemo: boolean = false;

                        while (lineIdx < lines.length && (!foundAmount || !foundMemo)) {
                            const nextLine: string = lines[lineIdx] ?? '';
                            if (nextLine.length === 0) {
                                lineIdx++;
                                continue;
                            }

                            const nextCode: string = nextLine.charAt(0);

                            if (nextCode === '$') {
                                // Split amount
                                try {
                                    split.amount = this.parseAmount(nextLine.substring(1).trim());
                                } catch {
                                    result.warnings.push({
                                        code: 'SPLIT_AMOUNT_ERROR',
                                        message: `Failed to parse split amount: ${nextLine}`,
                                        line: lineIdx + 1
                                    });
                                }
                                lineIdx++;
                                foundAmount = true;
                            } else if (nextCode === 'E') {
                                // Split memo
                                split.memo = nextLine.substring(1).trim();
                                lineIdx++;
                                foundMemo = true;
                            } else {
                                // Not a split continuation field, break
                                break;
                            }
                        }

                        splits.push(split);
                    }
                    break;

                case '^': // End of record
                    foundEnd = true;
                    break;

                default:
                    result.warnings.push({
                        code: 'UNKNOWN_FIELD',
                        message: `Unrecognized QIF field code: ${code}`,
                        line: lineIdx
                    });
            }

            if (foundEnd) break;
        }

        result.nextLine = lineIdx;

        // Validate required fields
        if (date === null) {
            result.errors.push({
                code: 'MISSING_DATE',
                message: 'Transaction is missing required date field',
                line: startLine
            });
            return result;
        }

        if (amount === null) {
            result.errors.push({
                code: 'MISSING_AMOUNT',
                message: 'Transaction is missing required amount field',
                line: startLine
            });
            return result;
        }

        if (payee.length === 0) {
            result.warnings.push({
                code: 'MISSING_PAYEE',
                message: 'Transaction is missing payee, using "Unknown"',
                line: startLine
            });
            payee = 'Unknown';
        }

        // Generate import hash for deduplication
        const importHash: string = generateImportHash(date, amount, payee);

        // Auto-balance splits if there's a math mismatch
        if (splits.length > 0) {
            const sumSplits = splits.reduce((acc, s) => acc + s.amount, 0);
            if (sumSplits !== amount) {
                splits.push({
                    category: null,
                    amount: amount - sumSplits,
                    memo: 'Auto-balancing adjustment'
                });
            }
        }

        result.transaction = {
            date,
            amount,
            payee,
            memo,
            checkNumber,
            category,
            splits,
            importHash
        } satisfies IParsedTransaction;

        return result;
    }

    /**
     * Handles the complex task of normalizing various QIF date formats.
     * Supports: M/D'YY, M/D/YYYY, M/D/YY, M-D-YYYY, M-D-YY, YYYY-MM-DD
     */
    public normalizeDate(raw: string): ISODateString {
        const trimmed: string = raw.trim();

        for (const pattern of this.DATE_PATTERNS) {
            const match: RegExpMatchArray | null = trimmed.match(pattern);
            if (match) {
                return this.parseMatchToISO(match, pattern);
            }
        }

        throw new Error(`Unrecognized date format: ${raw}`);
    }

    /**
     * Converts a regex match to ISO date format.
     */
    private parseMatchToISO(match: RegExpMatchArray, pattern: RegExp): ISODateString {
        const patternStr: string = pattern.toString();

        // YYYY-MM-DD (already ISO)
        if (patternStr.includes('\\d{4})-')) {
            const year: string = match[1] ?? '1970';
            const month: string = (match[2] ?? '01').padStart(2, '0');
            const day: string = (match[3] ?? '01').padStart(2, '0');
            return `${year}-${month}-${day}`;
        }

        // M/D or M-D formats
        const month: string = (match[1] ?? '01').padStart(2, '0');
        const day: string = (match[2] ?? '01').padStart(2, '0');
        const yearPart: string = match[3] ?? '00';

        let year: number;
        if (yearPart.length === 4) {
            year = parseInt(yearPart, 10);
        } else {
            // 2-digit year: 00-49 = 2000s, 50-99 = 1900s
            const yy: number = parseInt(yearPart, 10);
            year = yy < 50 ? 2000 + yy : 1900 + yy;
        }

        return `${year}-${month}-${day}`;
    }

    /**
     * Parses a QIF amount string into cents.
     * Handles: "-500.00", "1,234.56", "$100.00"
     */
    private parseAmount(raw: string): Cents {
        // Remove currency symbols, commas, and whitespace
        const cleaned: string = raw.replace(/[$,\s]/g, '');

        const dollars: number = parseFloat(cleaned);

        if (isNaN(dollars)) {
            throw new Error(`Invalid amount: ${raw}`);
        }

        // Convert to cents (integer)
        return Math.round(dollars * 100);
    }
}

/**
 * Internal result type for transaction parsing.
 */
interface ITransactionParseResult {
    transaction: IParsedTransaction | null;
    errors: Array<IParseError>;
    warnings: Array<IParseWarning>;
    nextLine: number;
}

export type Cents = number;

/**
 * Unique identifier for entities (UUID or deterministic hash).
 */
export type EntityId = string;

/**
 * ISO 8601 Date string (YYYY-MM-DD).
 * @example "2026-01-17"
 */
export type ISODateString = string;

/**
 * Isomorphic timer handle that resolves to the correct type in both Node and Browser.
 */
export type TimerHandle = ReturnType<typeof setInterval>;

/**
 * Transaction status in the ledger lifecycle.
 */
export enum TransactionStatus {
    /** Imported but not yet matched or verified by the user. */
    Pending = 'pending',
    /** Matched with bank statement but not yet frozen. */
    Cleared = 'cleared',
    /** User-verified and locked; immutable for ledger integrity. */
    Reconciled = 'reconciled'
}

/**
 * Core supported account types.
 */
export enum AccountType {
    Checking = 'checking',
    Savings = 'savings',
    Credit = 'credit',
    Cash = 'cash',
    Mortgage = 'mortgage',
    AutoLoan = 'auto_loan',
    PersonalLoan = 'personal_loan'
}

/**
 * Types of recurring schedules.
 */
export enum ScheduleType {
    Debit = 'debit',
    Deposit = 'deposit',
    Paycheck = 'paycheck'
}

export interface IMortgageMetadata {
    propertyAddress?: string;
    propertyValue?: Cents;
    escrowIncluded: boolean;
    escrowAmount?: Cents;
}

export interface IAutoLoanMetadata {
    vehicleMake?: string;
    vehicleModel?: string;
    vehicleYear?: number;
    vin?: string;
}

export interface IPersonalLoanMetadata {
    purpose?: string;
    secured: boolean;
}

export interface ILoanDetails {
    /** Original principal amount in cents */
    originalAmount: Cents;
    /** Annual Percentage Rate as decimal (e.g., 0.0375 = 3.75%) */
    interestRate: number;
    /** Total loan term in months */
    termMonths: number;
    /** Monthly payment amount in cents */
    monthlyPayment: Cents;
    /** Day of month payment is due (1-31) */
    paymentDueDay: number;
    /** Loan origination date */
    startDate: ISODateString;
    /** Type-specific metadata */
    metadata?: IMortgageMetadata | IAutoLoanMetadata | IPersonalLoanMetadata;
}

/**
 * A sub-allocation of a transaction to a category.
 */
export interface ISplit {
    /** Unique ID for the split. */
    id: EntityId;
    /** Category to which this amount is allocated. Null if uncategorized. */
    categoryId: EntityId | null;
    /** Descriptive text for this split. */
    memo: string;
    /** Amount in cents. Can be negative for deductions (taxes, fees). */
    amount: Cents;
}

/**
 * A financial transaction in the ledger.
 * Transactions consist of a total amount and one or more splits.
 */
export interface ITransaction {
    /** Unique ID for the transaction. */
    id: EntityId;
    /** ID of the account this transaction belongs to. */
    accountId: EntityId;
    /** Mandatory ID of the payee entity. */
    payeeId: EntityId;
    /** Date the transaction occurred. */
    date: ISODateString;
    /** Name of the payee or entity involved (cached for performance). */
    payee: string;
    /** Optional descriptive text for the transaction. */
    memo: string;
    /** Total amount in cents. Rule: Sum(splits) === totalAmount. */
    totalAmount: Cents;
    /** Current status in the reconciliation lifecycle. */
    status: TransactionStatus;
    /** List of splits. Must contain at least one split. */
    splits: Array<ISplit>;
    /** Optional check number for bank transactions. */
    checkNumber: string | null;
    /** SHA-256 hash for duplicate detection during imports. */
    importHash: string;
    /** ISO timestamp when the record was created. */
    createdAt: ISODateString;
    /** ISO timestamp when the record was last modified. */
    updatedAt: ISODateString;
    /** Optional ID of a linked transfer record if this transaction is part of a cross-account transfer. */
    linkedTransferId?: EntityId;
}

/**
 * A cross-account transfer connecting two transactions.
 */
export interface ITransfer {
    /** Unique ID for the transfer record. */
    id: EntityId;
    /** Date the transfer occurred. */
    date: ISODateString;
    /** Amount of the transfer (positive absolute value). */
    amount: Cents;
    /** ID of the source account. */
    fromAccountId: EntityId;
    /** ID of the destination account. */
    toAccountId: EntityId;
    /** ID of the transaction recorded in the source account. */
    fromTransactionId: EntityId;
    /** ID of the transaction recorded in the destination account. */
    toTransactionId: EntityId;
    /** Snapshot of the source account name in case it is deleted. */
    fromAccountNameSnapshot: string;
    /** Snapshot of the destination account name in case it is deleted. */
    toAccountNameSnapshot: string;
    /** Optional memo for the transfer. */
    memo: string;
    /** ISO timestamp when the record was created. */
    createdAt: ISODateString;
    /** ISO timestamp when the record was last modified. */
    updatedAt: ISODateString;
    /** ISO timestamp when the record was soft-deleted (null if active). */
    deletedAt: ISODateString | null;
}

/**
 * An entity that receives or pays money.
 */
export interface IPayee {
    /** Unique ID for the payee. */
    id: EntityId;
    /** Human-readable name (e.g., "Starbucks"). */
    name: string;
    /** Geographical Address. */
    address: string | null;
    /** City location. */
    city: string | null;
    /** State/Province. */
    state: string | null;
    /** Postal/Zip code. */
    zipCode: string | null;
    /** Coordinate for map visualization. */
    latitude: number | null;
    /** Coordinate for map visualization. */
    longitude: number | null;
    /** Official website or portal. */
    website: string | null;
    /** Contact phone number. */
    phone: string | null;
    /** Arbitrary notes about this payee. */
    notes: string | null;
    /** Default category ID suggested for new transactions. */
    defaultCategoryId: EntityId | null;
    /** ISO timestamp when the record was created. */
    createdAt: ISODateString;
    /** ISO timestamp when the record was last modified. */
    updatedAt: ISODateString;
}

/**
 * A category for organizing transactions (e.g., "Groceries", "Rent").
 * Supports a hierarchical tree structure.
 */
export interface ICategory {
    /** Unique ID for the category. */
    id: EntityId;
    /** ID of the parent category (null if top-level). */
    parentId: EntityId | null;
    /** Name of the category (e.g., "Dining Out"). */
    name: string;
    /** Optional detailed description. */
    description: string | null;
    /** Whether the category is currently available for selection. */
    isActive: boolean;
    /** ISO timestamp when the record was created. */
    createdAt: ISODateString;
    /** ISO timestamp when the record was last modified. */
    updatedAt: ISODateString;
}

/**
 * An account containing a collection of transactions.
 */
export interface IAccount {
    /** Unique ID for the account. */
    id: EntityId;
    /** Human-readable name (e.g., "Main Checking"). */
    name: string;
    /** Type of account (e.g., checking, savings). */
    type: AccountType;
    /** Financial institution name. */
    institutionName: string;
    /** Sum of all Cleared/Reconciled transactions. */
    clearedBalance: Cents;
    /** Sum of all transactions (Cleared + Pending). */
    pendingBalance: Cents;
    /** Whether the account is currently in use. */
    isActive: boolean;
    /** ISO timestamp when the record was created. */
    createdAt: ISODateString;
    /** ISO timestamp when the record was last modified. */
    updatedAt: ISODateString;
    /** ISO timestamp when the record was soft-deleted (null if active). */
    deletedAt: ISODateString | null;
    /** Optional detailed information for loan accounts. */
    loanDetails?: ILoanDetails;
}

/**
 * Frequency interval for recurring scheduled items.
 */
export enum Frequency {
    Daily = 'daily',
    Weekly = 'weekly',
    Biweekly = 'biweekly',
    EveryFourWeeks = 'every_four_weeks',
    Monthly = 'monthly',
    TwiceAMonth = 'twice_a_month',
    Bimonthly = 'bimonthly',
    Quarterly = 'quarterly',
    Yearly = 'yearly'
}

/**
 * Payment methods for scheduled transactions.
 */
export enum PaymentMethod {
    DirectDebit = 'direct_debit',
    DirectDeposit = 'direct_deposit',
    WriteCheck = 'write_check',
    ElectronicTransfer = 'electronic_transfer',
    Other = 'other'
}

/**
 * A template for generating recurring transactions.
 */
export interface IRecurringSchedule {
    /** Unique ID for the schedule. */
    id: EntityId;
    /** The account where generated transactions will be posted. */
    accountId: EntityId;
    /** Default payee for generated transactions. */
    payee: string;
    /** Total amount for the transaction (parent). */
    amount: Cents;
    /** The type of schedule (Debit, Deposit, Paycheck). */
    type: ScheduleType;
    /** How often the transaction repeats. */
    frequency: Frequency;
    /** How the payment is processed. */
    paymentMethod: PaymentMethod;
    /** Date when the schedule begins. */
    startDate: ISODateString;
    /** Optional date when the schedule ends. */
    endDate: ISODateString | null;
    /** Calculated date of the next occurrence. */
    nextDueDate: ISODateString;
    /** Date when the last transaction was posted from this schedule. */
    lastOccurredDate: ISODateString | null;
    /** Splits for the generated transaction. */
    splits: Array<ISplit>;
    /** Optional memo for the transaction. */
    memo: string;
    /** Whether to automatically post the transaction to the ledger on the due date. */
    autoPost: boolean;
    /** Whether the schedule is active and generating projections. */
    isActive: boolean;
}

/**
 * Result of parsing a single split from an external source (e.g. QIF).
 */
export interface IParsedSplit {
    category: string | null;
    amount: Cents;
    memo: string | null;
}

/**
 * Result of parsing a single transaction from an external source (e.g. QIF).
 */
export interface IParsedTransaction {
    date: ISODateString;
    amount: Cents;
    payee: string;
    memo: string;
    checkNumber: string | null;
    category: string | null;
    splits: Array<IParsedSplit>;
    importHash: string;
}

import type { Cents, ISplit, ITransaction } from '../domain/types';

export interface IValidationResult {
    valid: boolean;
    error?: string;
    discrepancy?: Cents;
}

/**
 * Validates that the sum of splits equals the transaction totalAmount.
 * Rule: Sum(Splits) === totalAmount
 */
export function validateSplitSum(transaction: ITransaction): IValidationResult {
    const splitSum: number = transaction.splits.reduce(
        (sum: number, split: ISplit) => sum + split.amount,
        0
    );

    if (splitSum !== transaction.totalAmount) {
        return {
            valid: false,
            error: `Split sum (${splitSum}) !== Total (${transaction.totalAmount})`,
            discrepancy: transaction.totalAmount - splitSum
        } satisfies IValidationResult;
    }

    return { valid: true } satisfies IValidationResult;
}

