import { CommonModule } from '@angular/common';
import type { ElementRef, OnDestroy, OnInit } from '@angular/core';
import {
    ChangeDetectionStrategy,
    Component,
    HostListener,
    computed,
    effect,
    inject,
    input,
    signal,
    untracked,
    viewChild
} from '@angular/core';
import { FormsModule } from '@angular/forms';
import { RouterLink } from '@angular/router';
import type { IPayee, ISODateString, ITransaction } from '@core';
import { AccountType, KnownCategory, Money, TransactionStatus } from '@core';
import { MessageService } from 'primeng/api';

import type { IAccount } from '@core';
import { ImportOrchestrationService } from '../../../services/import/import-orchestration.service';
import type { ReconciliationDecision } from '../../../services/import/import.types';
import { LedgerStore } from '../../../services/ledger-store/ledger.store';
import { PostHogService } from '../../../services/posthog/posthog.service';
import { NewAccountDialogComponent } from '../../onboarding/new-account-dialog/new-account-dialog.component';
import { SyncIndicatorComponent } from '../../sync/sync-indicator/sync-indicator.component';
import { CategoryMappingDialogComponent } from '../category-mapping-dialog/category-mapping-dialog.component';
import { ExpressImportDialogComponent } from '../express-import-dialog/express-import-dialog.component';
import { ImportProgressOverlayComponent } from '../import-progress-overlay/import-progress-overlay.component';
import { ReconciliationDialogComponent } from '../reconciliation-dialog/reconciliation-dialog.component';
import { TransactionEntryFormComponent } from '../transaction-entry-form/transaction-entry-form.component';
import { TransactionTableComponent } from '../transaction-table/transaction-table.component';

@Component({
    selector: 'account-ledger',
    standalone: true,
    imports: [
        CommonModule,
        FormsModule,
        RouterLink,
        TransactionTableComponent,
        TransactionEntryFormComponent,
        SyncIndicatorComponent,
        ReconciliationDialogComponent,
        ExpressImportDialogComponent,
        ImportProgressOverlayComponent,
        CategoryMappingDialogComponent,
        NewAccountDialogComponent
    ],
    providers: [MessageService],
    templateUrl: './account-ledger.component.html',
    styleUrls: ['./account-ledger.component.css'],
    changeDetection: ChangeDetectionStrategy.OnPush
})
export class AccountLedgerComponent implements OnInit, OnDestroy {
    private readonly ledgerStore = inject(LedgerStore);
    private readonly posthogService = inject(PostHogService);
    readonly importService = inject(ImportOrchestrationService);
    private readonly messageService = inject(MessageService);

    // Inputs
    readonly initialAccountId = input<string | null>(null);

    // State
    readonly activeAccountId = signal<string | null>(null);

    // New Account Dialog
    readonly isAddDialogOpen = signal<boolean>(false);

    // Reconciliation Dialog
    readonly reconciliationOpen = signal<boolean>(false);
    readonly expressImportOpen = signal<boolean>(false);

    // Drag-and-drop state
    readonly isDragOver = signal<boolean>(false);

    // File input ref
    readonly fileInput = viewChild<ElementRef<HTMLInputElement>>('fileInput');

    // Computed from store
    readonly accounts = this.ledgerStore.accounts;
    readonly transactions = this.ledgerStore.transactions;

    readonly filteredTransactions = computed(() => {
        const accId = this.activeAccountId();
        const allTxs = this.transactions();
        if (!accId) return allTxs;
        return allTxs.filter(tx => tx.accountId === accId);
    });

    readonly clearedBalance = computed(() =>
        this.filteredTransactions()
            .filter(tx => tx.status === TransactionStatus.Cleared)
            .reduce((sum, tx) => sum + tx.totalAmount, 0)
    );

    readonly pendingBalance = computed(() =>
        this.filteredTransactions()
            .filter(tx => tx.status === TransactionStatus.Pending)
            .reduce((sum, tx) => sum + tx.totalAmount, 0)
    );

    /** Convenience alias so the template can read import progress reactively. */
    readonly importProgress = this.importService.progress;
    readonly importMatches = this.importService.matches;
    readonly importStats = this.importService.stats;

    // ── Lifecycle ─────────────────────────────────────────────────────────────

    constructor() {
        // Open the appropriate dialog when import finishes
        effect(() => {
            const stage = this.importService.progress().stage;
            if (stage === 'done') {
                untracked(() => {
                    const matches = this.importService.matches();
                    const stats = this.importService.stats();
                    const isExpress = matches.length >= 100 && stats?.fuzzyCount === 0;

                    if (isExpress) {
                        this.expressImportOpen.set(true);
                    } else {
                        this.reconciliationOpen.set(true);
                    }

                    this.posthogService.posthog.capture('qif_import_parsed', {
                        match_count: matches.length,
                        account_id: this.activeAccountId()
                    });
                });
            }
        });
    }

    ngOnInit(): void {
        this.activeAccountId.set(this.initialAccountId());
    }

    ngOnDestroy(): void {
        this.importService.reset();
    }

    handleAccountCreated(account: IAccount): void {
        this.ledgerStore.addAccount(account);
    }

    // ── Drag and Drop ─────────────────────────────────────────────────────────

    @HostListener('dragover', ['$event'])
    onDragOver(event: DragEvent): void {
        event.preventDefault();
        event.stopPropagation();
        const hasFiles = event.dataTransfer?.types.includes('Files') ?? false;
        if (hasFiles) this.isDragOver.set(true);
    }

    @HostListener('dragleave', ['$event'])
    onDragLeave(event: DragEvent): void {
        // Only clear if leaving the host element (not a child)
        const rect = (event.currentTarget as HTMLElement).getBoundingClientRect();
        const outside =
            event.clientX < rect.left ||
            event.clientX > rect.right ||
            event.clientY < rect.top ||
            event.clientY > rect.bottom;
        if (outside) this.isDragOver.set(false);
    }

    @HostListener('drop', ['$event'])
    onDrop(event: DragEvent): void {
        event.preventDefault();
        event.stopPropagation();
        this.isDragOver.set(false);

        const file = event.dataTransfer?.files[0];
        if (file && this.isQifFile(file)) {
            this.startImport(file);
        }
    }

    // ── Import actions ────────────────────────────────────────────────────────

    triggerImport(): void {
        this.fileInput()?.nativeElement.click();
    }

    onFileSelected(event: Event): void {
        const input = event.target as HTMLInputElement;
        const file = input.files?.[0];
        if (!file) return;
        input.value = ''; // reset so same file can be re-selected
        this.startImport(file);
    }

    private startImport(file: File): void {
        const accountId = this.activeAccountId() ?? 'default';
        this.importService.startImport(file, accountId);
    }

    private isQifFile(file: File): boolean {
        return (
            file.name.toLowerCase().endsWith('.qif') ||
            file.name.toLowerCase().endsWith('.csv') ||
            file.type === 'application/qif' ||
            file.type === 'text/plain'
        );
    }

    // ── Reconciliation commit ─────────────────────────────────────────────────

    async handleReconciliationConfirmed(event: {
        decisions: Record<number, ReconciliationDecision>;
        payeeOverrides?: Record<number, string>;
        categoryOverrides?: Record<number, string>;
        matchOverrides?: Record<number, string>;
        done: () => void;
    }): Promise<void> {
        const {
            decisions,
            payeeOverrides = {},
            categoryOverrides = {},
            matchOverrides = {},
            done
        } = event;
        const matches = this.importService.matches();
        const accountId = this.activeAccountId() ?? 'default';
        const now = new Date().toISOString() as ISODateString;

        const txsToImport: Array<ITransaction> = [];
        const txsToUpdate: Array<ITransaction> = [];
        const newPayees = new Map<string, IPayee>();
        const currentPayees = new Map(this.ledgerStore.payees().map(p => [p.name, p]));

        let matchedCount = 0;
        let ignoredCount = 0;

        for (const [idxStr, decision] of Object.entries(decisions)) {
            const idx = parseInt(idxStr, 10);
            const match = matches[idx];
            if (!match) continue;

            if (decision === 'import') {
                const parsed = match.parsedTx;
                const overriddenPayeeName = payeeOverrides[idx] || parsed.payee;

                let payee = currentPayees.get(overriddenPayeeName);
                if (!payee && newPayees.has(overriddenPayeeName)) {
                    payee = newPayees.get(overriddenPayeeName);
                }
                if (!payee) {
                    payee = {
                        id: `payee-${Date.now()}-${Math.random().toString(36).substring(2, 9)}`,
                        name: overriddenPayeeName,
                        address: null,
                        city: null,
                        state: null,
                        zipCode: null,
                        latitude: null,
                        longitude: null,
                        website: null,
                        phone: null,
                        notes: null,
                        defaultCategoryId: null,
                        createdAt: now,
                        updatedAt: now
                    };
                    newPayees.set(overriddenPayeeName, payee);
                }

                txsToImport.push({
                    id: `tx-import-${Date.now()}-${idx}`,
                    accountId,
                    payeeId: payee.id,
                    date: parsed.date,
                    payee: overriddenPayeeName,
                    memo: parsed.memo,
                    totalAmount: parsed.amount,
                    status: TransactionStatus.Cleared,
                    checkNumber: parsed.checkNumber,
                    importHash: parsed.importHash,
                    splits:
                        parsed.splits && parsed.splits.length > 0
                            ? parsed.splits.map((s, sIdx) => ({
                                  id: `split-import-${Date.now()}-${idx}-${sIdx}`,
                                  amount: s.amount,
                                  memo: s.memo || '',
                                  categoryId:
                                      categoryOverrides[idx] ||
                                      this.mapQifCategory(s.category ?? undefined)
                              }))
                            : [
                                  {
                                      id: `split-import-${Date.now()}-${idx}`,
                                      amount: parsed.amount,
                                      memo: parsed.memo,
                                      categoryId:
                                          categoryOverrides[idx] ||
                                          this.mapQifCategory(parsed.category ?? undefined)
                                  }
                              ],
                    createdAt: now,
                    updatedAt: now
                });
            } else if (decision === 'match') {
                const targetMatchId = matchOverrides[idx] || match.existingTxId;
                if (targetMatchId) {
                    const existingTx = this.transactions().find(t => t.id === targetMatchId);
                    if (existingTx) {
                        txsToUpdate.push({
                            ...existingTx,
                            status: TransactionStatus.Cleared,
                            updatedAt: now
                        });
                        matchedCount++;
                    }
                }
            } else {
                ignoredCount++;
            }
        }

        if (newPayees.size > 0 || txsToImport.length > 0 || txsToUpdate.length > 0) {
            await this.ledgerStore.applyReconciliationBatch(
                Array.from(newPayees.values()),
                txsToImport,
                txsToUpdate
            );
        }

        // Show completion toast
        this.messageService.add({
            severity: 'success',
            summary: 'Import Complete',
            detail: [
                txsToImport.length > 0 ? `${txsToImport.length.toLocaleString()} added` : '',
                matchedCount > 0 ? `${matchedCount} matched` : '',
                ignoredCount > 0 ? `${ignoredCount} skipped` : ''
            ]
                .filter(Boolean)
                .join(' · '),
            life: 5000
        });

        this.posthogService.posthog.capture('qif_import_completed', {
            imported_count: txsToImport.length,
            matched_count: matchedCount,
            ignored_count: ignoredCount
        });

        this.importService.reset();
        done();
    }

    handleReviewFirst(): void {
        this.expressImportOpen.set(false);
        this.reconciliationOpen.set(true);
    }

    handleImportCancelled(): void {
        this.importService.reset();
    }

    private mapQifCategory(qifCategory: string | undefined): string {
        if (!qifCategory) return KnownCategory.Uncategorized;

        // If it's already a valid category ID, use it directly
        const categories = this.ledgerStore.categories();
        if (categories.some(c => c.id === qifCategory)) {
            return qifCategory;
        }

        // Clean: remove brackets and take the last part after ':'
        const cleanNameRaw = qifCategory.replace(/[[\]]/g, '').trim();
        let cleanName = cleanNameRaw;
        if (cleanNameRaw.includes(':')) {
            const parts = cleanNameRaw.split(':');
            const lastPart = parts[parts.length - 1];
            if (lastPart) {
                cleanName = lastPart.trim();
            }
        }

        const match = categories.find(c => c.name.toLowerCase() === cleanName.toLowerCase());

        return match ? match.id : KnownCategory.Uncategorized;
    }

    // ── Edit Transaction ──────────────────────────────────────────────────────

    readonly entryForm = viewChild(TransactionEntryFormComponent);

    editTransaction(tx: ITransaction): void {
        this.entryForm()?.editTransaction(tx);
    }

    async deleteTransaction(txId: string): Promise<void> {
        await this.ledgerStore.removeTransaction(txId);
        this.messageService.add({
            severity: 'success',
            summary: 'Transaction Deleted',
            detail: 'The transaction has been removed.',
            life: 3000
        });
    }

    // ── Helpers ───────────────────────────────────────────────────────────────

    formatCurrency(amount: number): string {
        return Money.formatCurrency(amount);
    }

    getAccountIcon(type: AccountType | undefined): string {
        switch (type) {
            case AccountType.Checking:
                return 'pi-building-columns';
            case AccountType.Savings:
                return 'pi-chart-line';
            case AccountType.Credit:
                return 'pi-credit-card';
            case AccountType.Cash:
                return 'pi-wallet';
            default:
                return 'pi-building-columns';
        }
    }

    getAccountBalance(accId: string): number {
        return this.transactions()
            .filter(t => t.accountId === accId)
            .reduce((s, t) => s + t.totalAmount, 0);
    }

    // ── Icons ─────────────────────────────────────────────────────────────────
}

import { CommonModule } from '@angular/common';
import { ChangeDetectionStrategy, Component, effect, inject, signal } from '@angular/core';
import { ActivatedRoute, Router, RouterLink } from '@angular/router';
import { AccountType, type IAccount, Money } from '@core';

import { AppShellComponent } from '../../components/layout/app-shell/app-shell.component';
import { NewAccountDialogComponent } from '../../components/onboarding/new-account-dialog/new-account-dialog.component';
import { WelcomeWizardComponent } from '../../components/onboarding/welcome-wizard/welcome-wizard.component';
import { LedgerStore } from '../../services/ledger-store/ledger.store';

/**
 * Page for managing all accounts.
 * Shows a list of accounts with basic actions and provides an onboarding flow
 * if no accounts exist.
 */
@Component({
    selector: 'accounts-page',
    standalone: true,
    imports: [
        CommonModule,
        RouterLink,
        WelcomeWizardComponent,
        NewAccountDialogComponent,
        AppShellComponent
    ],
    templateUrl: './accounts-page.component.html',
    styleUrls: ['./accounts-page.component.css'],
    changeDetection: ChangeDetectionStrategy.OnPush
})
export class AccountsPageComponent {
    private readonly ledgerStore = inject(LedgerStore);
    private readonly route = inject(ActivatedRoute);
    private readonly router = inject(Router);

    // State
    readonly expandedId = signal<string | null>(null);
    readonly isAddDialogOpen = signal<boolean>(false);
    readonly pendingDeleteId = signal<string | null>(null);
    readonly isDeleteConfirmOpen = signal<boolean>(false);
    readonly isOnboarding = signal<boolean>(false);

    // Store Signals
    readonly accounts = this.ledgerStore.accounts;
    readonly isDbReady = this.ledgerStore.isInitialized;

    constructor() {
        effect(
            () => {
                if (this.isDbReady()) {
                    if (this.accounts().length === 0 && !this.isOnboarding()) {
                        this.isOnboarding.set(true);
                    }
                }
            },
            { allowSignalWrites: true }
        );

        // Auto-open the Add Account dialog when navigated with ?openDialog=true
        this.route.queryParams.subscribe(params => {
            if (params['openDialog'] === 'true') {
                this.isAddDialogOpen.set(true);
                // Consume the query param so it doesn't re-trigger on refresh
                void this.router.navigate([], {
                    relativeTo: this.route,
                    queryParams: {},
                    replaceUrl: true
                });
            }
        });
    }

    handleOnboardingCompleted(): void {
        this.isOnboarding.set(false);
    }

    /**
     * Helper to determine account icon based on type
     */
    getAccountIcon(type: AccountType): string {
        switch (type) {
            case AccountType.Checking:
                return 'pi-building-columns';
            case AccountType.Savings:
                return 'pi-chart-line';
            case AccountType.Credit:
                return 'pi-credit-card';
            case AccountType.Cash:
                return 'pi-wallet';
            default:
                return 'pi-building-columns';
        }
    }

    formatCurrency(amount: number): string {
        return Money.formatCurrency(amount);
    }

    toggleExpand(accountId: string): void {
        this.expandedId.update(id => (id === accountId ? null : accountId));
    }

    handleAccountCreated(account: IAccount): void {
        this.ledgerStore.addAccount(account);
        // Do not close the dialog here — the wizard proceeds to the import step
        // (step 3) and will emit (closed) when the user finishes or skips.
    }

    requestDeleteAccount(accountId: string, event: Event): void {
        event.stopPropagation(); // Don't toggle the expand panel
        this.pendingDeleteId.set(accountId);
        this.isDeleteConfirmOpen.set(true);
    }

    confirmDeleteAccount(): void {
        const id = this.pendingDeleteId();
        if (id) {
            void this.ledgerStore.removeAccount(id);
            // Collapse if this account was expanded
            if (this.expandedId() === id) this.expandedId.set(null);
        }
        this.isDeleteConfirmOpen.set(false);
        this.pendingDeleteId.set(null);
    }

    cancelDelete(): void {
        this.isDeleteConfirmOpen.set(false);
        this.pendingDeleteId.set(null);
    }

    // Lucide Icons
}

import { isPlatformBrowser } from '@angular/common';
import {
    ChangeDetectionStrategy,
    Component,
    DestroyRef,
    effect,
    inject,
    PLATFORM_ID,
    signal
} from '@angular/core';
import { Title } from '@angular/platform-browser';
import { RouterOutlet } from '@angular/router';

import { environment } from '../environments/environment';
import { EnvBannerComponent } from './components/ui/env-banner/env-banner.component';
import { AuthService } from './services/auth/auth.service';
import { FaviconService } from './services/favicon/favicon.service';
import { LedgerStore } from './services/ledger-store/ledger.store';
import { PostHogService } from './services/posthog/posthog.service';
import { SyncService } from './services/sync/sync.service';
import { ThemeService } from './services/theme/theme.service';

/** How long after the last mutation before auto-saving to Drive. */
const AUTO_SAVE_DEBOUNCE_MS = 3_000;

/**
 * Root application component.
 *
 * ## Local-First Startup Sequence
 *
 *   1. Firebase resolves onAuthStateChanged → currentUser() set
 *      AuthService simultaneously restores the Google OAuth token from localStorage.
 *
 *   2. initializeApp() runs exactly once (guarded by initStarted):
 *
 *      a. SyncService.initFromLocal(userId)
 *         → Loads IndexedDB snapshot instantly (<200ms)
 *         → App is immediately usable if local data exists
 *         → Returns false if this is a new device (no local data)
 *
 *      b. SyncService.syncFromDrive() — BACKGROUND
 *         → If local data existed: no await, fully background
 *         → If new device: awaited — shows "Syncing your Ledger" until done
 *         → Compares local version timestamp with Drive modifiedTime
 *         → Downloads + merges if Drive is newer; uploads if local is newer
 *
 *   3. All subsequent mutations write to IndexedDB immediately (via
 *      LedgerStore.commitToLocal()) then trigger debounced Drive upload.
 *
 * ## Error Cases
 *   - Firebase fails / no session → AuthService redirects to /sign-in
 *   - No Drive token (token expired) → local-only, authError banner shows
 *   - Drive API fails → syncStatus = 'error', error detail shown in banner
 */
@Component({
    imports: [RouterOutlet, EnvBannerComponent],
    selector: 'root',
    template: `
        <env-banner />
        <router-outlet />
    `,
    styles: `
        :host {
            display: block;
            min-height: 100vh;
        }
    `,
    changeDetection: ChangeDetectionStrategy.OnPush
})
export class AppComponent {
    readonly title = 'Path Logic';

    private readonly authService = inject(AuthService);
    private readonly syncService = inject(SyncService);
    private readonly ledgerStore = inject(LedgerStore);
    private readonly posthogService = inject(PostHogService);
    private readonly platformId = inject(PLATFORM_ID);
    private readonly destroyRef = inject(DestroyRef);

    /** True while waiting for Drive data on a new device (no local snapshot). */
    readonly isSyncingNewDevice = signal<boolean>(false);

    private autoSaveTimer: ReturnType<typeof setTimeout> | null = null;
    private initStarted = false;

    constructor() {
        // Initialize theme before first paint — reads OS/saved preference and
        // sets data-theme on <html>, activating the CSS custom property system.
        inject(ThemeService);

        // Initialize dynamic favicon based on active theme and environment
        inject(FaviconService);

        // Set document title — include env label on non-production builds
        const titleService = inject(Title);
        const isProd = environment.production || environment.appEnv === 'production';
        titleService.setTitle(
            isProd ? 'Path Logic' : `[${environment.appEnv.toUpperCase()}] Path Logic`
        );

        if (isPlatformBrowser(this.platformId) && environment.posthogKey) {
            this.posthogService.init(environment.posthogKey, {
                api_host: environment.posthogHost || 'https://us.i.posthog.com',
                ui_host: 'https://us.posthog.com',
                capture_exceptions: true
            });
        }

        // ── Local-First startup: Firebase confirmed → IndexedDB → Drive sync ──
        effect(() => {
            const isInitializing = this.authService.isInitializing();
            const user = this.authService.currentUser();

            if (isInitializing || !user) return;
            if (this.initStarted) return;
            this.initStarted = true;

            if (environment.e2e) {
                this.syncService
                    .initFromLocal('e2e-user')
                    .then((loaded: boolean) => {
                        if (!loaded) {
                            return this.ledgerStore.initialize();
                        }
                        return;
                    })
                    .catch((e: unknown) => {
                        console.error('[AppComponent] E2E DB init failed:', e);
                        this.ledgerStore.initialize().catch(console.error);
                    });
                return;
            }

            this.initializeApp(user.uid);
        });

        // ── Auto-save: push dirty local state to Drive in the background ──────
        effect(() => {
            const isDirty = this.ledgerStore.isDirty();
            const hasToken = !!this.authService.accessToken();
            const isLoggedIn = this.authService.isLoggedIn();

            if (!isDirty || !isLoggedIn || !hasToken || environment.e2e) return;

            if (this.autoSaveTimer !== null) clearTimeout(this.autoSaveTimer);

            this.autoSaveTimer = setTimeout(() => {
                this.autoSaveTimer = null;
                this.syncService.saveToDrive().catch((e: unknown) => {
                    console.error('[AppComponent] Auto-save to Drive failed:', e);
                });
            }, AUTO_SAVE_DEBOUNCE_MS);
        });

        this.destroyRef.onDestroy(() => {
            if (this.autoSaveTimer !== null) clearTimeout(this.autoSaveTimer);
        });
    }

    /**
     * Local-first initialization:
     *   1. Load from IndexedDB (instant)
     *   2. Sync with Drive in the background
     *
     * If no local data exists (new device), step 2 blocks the UI with
     * a "Syncing your Ledger" screen until Drive data is downloaded.
     */
    private initializeApp(userId: string): void {
        this.syncService
            .initFromLocal(userId)
            .then(async (hasLocalData: boolean) => {
                if (!hasLocalData) {
                    // New device — attempt to load from Drive.
                    // Race against a hard timeout so a stale token or network
                    // issue never permanently hangs the UI.
                    this.isSyncingNewDevice.set(true);
                    const SYNC_TIMEOUT_MS = 15_000;
                    const timeoutPromise = new Promise<void>(resolve =>
                        setTimeout(() => {
                            console.warn(
                                `[AppComponent] Drive sync timed out after ${SYNC_TIMEOUT_MS}ms — falling through to local-only mode.`
                            );
                            resolve();
                        }, SYNC_TIMEOUT_MS)
                    );
                    try {
                        await Promise.race([this.syncService.syncFromDrive(), timeoutPromise]);
                    } finally {
                        // Ensure DB is initialized even if sync failed or timed out
                        if (!this.ledgerStore.isInitialized()) {
                            await this.ledgerStore.initialize();
                        }
                        this.isSyncingNewDevice.set(false);
                    }
                } else {
                    // App is immediately usable — sync Drive in the background
                    this.syncService.syncFromDrive().catch((e: unknown) => {
                        console.error('[AppComponent] Background Drive sync failed:', e);
                    });
                }
            })
            .catch((e: unknown) => {
                console.error('[AppComponent] initFromLocal failed:', e);
                // Last resort: ensure app is at least initialized
                this.ledgerStore.initialize().catch(console.error);
            });
    }
}

