import { ChangeDetectionStrategy, Component, computed, inject } from '@angular/core';
import { Router } from '@angular/router';
import { type MenuItem } from 'primeng/api';
import { Breadcrumb } from 'primeng/breadcrumb';

import { LedgerStore } from '../../../services/ledger-store/ledger.store';

/**
 * Map of route segments to their human-readable labels.
 */
const routeLabels: Record<string, string> = {
    accounts: 'Accounts',
    payees: 'Payees',
    settings: 'Settings',
    'style-guide': 'Style Guide',
    dev: 'Developer Tools',
    'sync-test': 'Sync Test',
    auth: 'Authentication',
    info: 'Information'
};

/**
 * Breadcrumb navigation component that dynamically resolves labels based on the current URL.
 */
@Component({
    selector: 'breadcrumb-nav',
    standalone: true,
    imports: [Breadcrumb],
    templateUrl: './breadcrumb-nav.component.html',
    styleUrl: './breadcrumb-nav.component.css',
    changeDetection: ChangeDetectionStrategy.OnPush
})
export class BreadcrumbNavComponent {
    private readonly router: Router = inject(Router);
    private readonly ledgerStore: LedgerStore = inject(LedgerStore);

    /**
     * The "home" slot holds the first route segment so PrimeNG never
     * renders a separator before it. Subsequent segments go into `model`.
     */
    readonly home = computed((): MenuItem => {
        const url: string = this.router.url.split('?')[0] ?? '';
        const segments: Array<string> = url.split('/').filter(Boolean);
        const first = segments[0];
        if (!first) return { icon: 'pi pi-home', routerLink: '/' };

        const label = routeLabels[first] ?? first.charAt(0).toUpperCase() + first.slice(1);
        return { label, routerLink: `/${first}` };
    });

    /**
     * Computed signal that builds the breadcrumb list from the current URL.
     * Only segments after the first are included — the first is in `home`.
     */
    readonly breadcrumbs = computed((): Array<MenuItem> => {
        const url: string = this.router.url.split('?')[0] ?? '';
        const segments: Array<string> = url.split('/').filter(Boolean);

        // Need at least 2 segments to show breadcrumbs beyond the home item
        if (segments.length < 2) {
            return new Array<MenuItem>();
        }

        // Skip index 0 — that's handled by the home slot above
        return segments.slice(1).map((segment: string, index: number): MenuItem => {
            const absoluteIndex = index + 1; // index relative to full segments array
            const routerLink: string = `/${segments.slice(0, absoluteIndex + 1).join('/')}`;

            let label: string = routeLabels[segment] ?? segment;

            // Resolve account ID to name if in accounts path
            if (segments[absoluteIndex - 1] === 'accounts') {
                const account = this.ledgerStore.accounts().find(a => a.id === segment);
                if (account) {
                    label = account.name;
                }
            }

            // Capitalize if no specific label found
            if (label === segment) {
                label = segment.charAt(0).toUpperCase() + segment.slice(1);
            }

            return { label, routerLink };
        });
    });
}

import { CommonModule } from '@angular/common';
import {
    ChangeDetectionStrategy,
    Component,
    EventEmitter,
    forwardRef,
    Input,
    Output,
    signal
} from '@angular/core';
import type { ControlValueAccessor } from '@angular/forms';
import { FormsModule, NG_VALUE_ACCESSOR } from '@angular/forms';
import { cleanExpression, evalArithmetic, formatCurrency } from '@core';
import { ButtonModule } from 'primeng/button';
import { InputGroupModule } from 'primeng/inputgroup';
import { InputGroupAddonModule } from 'primeng/inputgroupaddon';
import { InputTextModule } from 'primeng/inputtext';
import { PopoverModule } from 'primeng/popover';
import { TooltipModule } from 'primeng/tooltip';

@Component({
    selector: 'calculator-input',
    standalone: true,
    imports: [
        CommonModule,
        FormsModule,
        InputTextModule,
        InputGroupModule,
        InputGroupAddonModule,
        PopoverModule,
        ButtonModule,
        TooltipModule
    ],
    templateUrl: './calculator-input.component.html',
    providers: [
        {
            provide: NG_VALUE_ACCESSOR,
            useExisting: forwardRef(() => CalculatorInputComponent),
            multi: true
        }
    ],
    changeDetection: ChangeDetectionStrategy.OnPush
})
export class CalculatorInputComponent implements ControlValueAccessor {
    @Input() placeholder = '$0.00';
    @Input() disabled = false;
    @Input() readonly = false;
    @Input() prefix = '$';
    @Input() inputClass = '';
    @Input() styleClass = '';
    @Input() inputId = '';

    @Output() valueChange = new EventEmitter<number>();

    // Internal display value (string)
    displayValue = signal<string>('');
    history = signal<Array<string>>([]);

    // Internal parsed value (cents)
    private _valueInCents = 0;
    overflowTitle = '';

    // ControlValueAccessor functions
    // eslint-disable-next-line @typescript-eslint/no-empty-function
    onChange: (value: number) => void = () => {};
    // eslint-disable-next-line @typescript-eslint/no-empty-function
    onTouched: () => void = () => {};

    writeValue(cents: number): void {
        this._valueInCents = cents || 0;
        this.setDisplayValueFromCents();
    }

    registerOnChange(fn: (value: number) => void): void {
        this.onChange = fn;
    }

    registerOnTouched(fn: () => void): void {
        this.onTouched = fn;
    }

    setDisabledState(isDisabled: boolean): void {
        this.disabled = isDisabled;
    }

    handleFocus(): void {
        if (this.readonly || this.disabled) return;
        if (this._valueInCents) {
            this.displayValue.set((this._valueInCents / 100).toString());
        }
    }

    checkOverflow(event: MouseEvent): void {
        const input = event.target as HTMLInputElement;
        if (input.scrollWidth > input.clientWidth) {
            this.overflowTitle = (this.prefix || '') + this.displayValue();
        } else {
            this.overflowTitle = '';
        }
    }

    handleBlur(): void {
        this.evaluateExpression(this.displayValue());
        this.onTouched();
    }

    handleKeydown(event: KeyboardEvent): void {
        if (event.key === 'Enter') {
            event.preventDefault();
            this.evaluateExpression(this.displayValue());
            return;
        }

        // Allow control keys
        const isControlKey = [
            'Backspace',
            'Delete',
            'Tab',
            'Escape',
            'ArrowLeft',
            'ArrowRight',
            'ArrowUp',
            'ArrowDown',
            'Home',
            'End'
        ].includes(event.key);

        if (isControlKey || event.ctrlKey || event.metaKey) {
            return;
        }

        // Allow only numbers, dot, and comma
        if (!/^[0-9.,]$/.test(event.key)) {
            event.preventDefault();
            return;
        }

        const input = event.target as HTMLInputElement;
        const currentVal = input.value;
        const selStart = input.selectionStart || 0;
        const selEnd = input.selectionEnd || 0;

        // If replacing text, allow it
        if (selEnd > selStart) return;

        // Prevent multiple dots
        if (event.key === '.' && currentVal.includes('.')) {
            event.preventDefault();
            return;
        }

        // Limit to 2 digits after the dot
        const dotIndex = currentVal.indexOf('.');
        if (dotIndex !== -1 && /^[0-9]$/.test(event.key)) {
            if (selStart > dotIndex) {
                const decimalPart = currentVal.substring(dotIndex + 1);
                if (decimalPart.length >= 2) {
                    event.preventDefault();
                }
            }
        }
    }

    private evaluateExpression(expr: string): void {
        if (!expr || expr.trim() === '') {
            this.updateValue(0);
            return;
        }

        try {
            const result = evalArithmetic(cleanExpression(expr).trim());
            const cents = Math.round(result * 100);
            this.history.update(h => [...h, `${expr} = ${formatCurrency(cents)}`]);
            this.updateValue(cents);
        } catch {
            // Invalid expression — revert to last committed value
            this.setDisplayValueFromCents();
        }
    }

    private updateValue(cents: number): void {
        this._valueInCents = cents;
        this.setDisplayValueFromCents();
        this.onChange(cents);
        this.valueChange.emit(cents);
    }

    private setDisplayValueFromCents(): void {
        const formatted = this._valueInCents ? formatCurrency(this._valueInCents) : '';
        this.displayValue.set(formatted.replace(/^\$/, ''));
    }
}

import { CommonModule } from '@angular/common';
import { ChangeDetectionStrategy, Component, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { PrimeTemplate } from 'primeng/api';
import { Button } from 'primeng/button';
import { Dialog } from 'primeng/dialog';
import { Select } from 'primeng/select';
import { ImportOrchestrationService } from '../../../services/import/import-orchestration.service';
import { LedgerStore } from '../../../services/ledger-store/ledger.store';

@Component({
    selector: 'category-mapping-dialog',
    standalone: true,
    imports: [CommonModule, FormsModule, Dialog, Button, Select, PrimeTemplate],
    templateUrl: './category-mapping-dialog.component.html',
    changeDetection: ChangeDetectionStrategy.OnPush
})
export class CategoryMappingDialogComponent {
    readonly importService = inject(ImportOrchestrationService);
    readonly ledgerStore = inject(LedgerStore);

    // Mappings: Unknown QIF Category String -> Internal Category ID
    readonly mappings = signal<Record<string, string>>({});

    handleCategoryChange(unknownString: string, categoryId: string | null): void {
        this.mappings.update(m => {
            if (categoryId) {
                return { ...m, [unknownString]: categoryId };
            } else {
                const { [unknownString]: _removed, ...rest } = m;
                return rest;
            }
        });
    }

    async handleConfirm(): Promise<void> {
        await this.importService.resolveUnknownCategories(this.mappings());
    }

    handleCancel(): void {
        this.importService.cancel();
    }

    get isFullyMapped(): boolean {
        const unknowns = this.importService.unknownCategories();
        const mapped = this.mappings();
        return unknowns.every(u => !!mapped[u]);
    }
}

import { ChangeDetectionStrategy, Component, computed, inject } from '@angular/core';

import type { ITransactionConflict } from '../../../lib/sync/MergeEngine';
import { LedgerStore } from '../../../services/ledger-store/ledger.store';

/**
 * Modal for resolving true sync conflicts — transactions modified on BOTH
 * the local device AND another device since the last Drive sync.
 *
 * Shown when syncConflicts().length > 0. The user resolves each conflict by
 * choosing "Keep Mine" (local) or "Keep Theirs" (remote from Drive). After all
 * conflicts are resolved the modal disappears and the ledger triggers a Drive upload.
 */
@Component({
    selector: 'conflict-resolution-modal',
    standalone: true,
    imports: [],
    templateUrl: './conflict-resolution-modal.component.html',
    styleUrl: './conflict-resolution-modal.component.css',
    changeDetection: ChangeDetectionStrategy.OnPush
})
export class ConflictResolutionModalComponent {
    private readonly ledgerStore = inject(LedgerStore);

    readonly conflicts = computed(() => this.ledgerStore.syncConflicts());
    readonly showModal = computed(() => this.conflicts().length > 0);

    formatAmount(cents: number): string {
        const sign = cents < 0 ? '-' : '';
        return `${sign}$${(Math.abs(cents) / 100).toFixed(2)}`;
    }

    formatDate(dateStr: string): string {
        try {
            return new Date(dateStr + 'T00:00:00').toLocaleDateString('en-US', {
                month: 'short',
                day: 'numeric',
                year: 'numeric'
            });
        } catch {
            return dateStr;
        }
    }

    formatTimestamp(iso: string): string {
        try {
            return new Date(iso).toLocaleString('en-US', {
                month: 'short',
                day: 'numeric',
                hour: 'numeric',
                minute: '2-digit'
            });
        } catch {
            return iso;
        }
    }

    keepMine(conflict: ITransactionConflict): void {
        this.ledgerStore.resolveConflict(conflict.id, true).catch(console.error);
    }

    keepTheirs(conflict: ITransactionConflict): void {
        this.ledgerStore.resolveConflict(conflict.id, false).catch(console.error);
    }

    keepAllMine(): void {
        const ids = this.conflicts().map(c => c.id);
        for (const id of ids) {
            this.ledgerStore.resolveConflict(id, true).catch(console.error);
        }
    }

    keepAllTheirs(): void {
        const ids = this.conflicts().map(c => c.id);
        for (const id of ids) {
            this.ledgerStore.resolveConflict(id, false).catch(console.error);
        }
    }
}

